modules.actions:
'use strict';
/**
 * creep 动作管线守卫。
 *
 * 引擎在 tick 末尾按 @screeps/engine processor/intents/creeps/intents.js 的表结算：某个 intent 只要
 * 与它冲突的 intent 在同一 tick 也发了，它就被**整个丢弃**，与代码里的调用顺序无关
 * （docs/game/simultaneous-actions.md：「The sequence of calling commands for different methods in the
 * code is irrelevant, only the aforementioned priorities matter」）。
 *
 * 这张表是**有向**的，不是互斥集合：
 *   - heal 永远执行（不在表里），所以 range 1 的 heal 可以和 rangedAttack 同 tick，白拿；
 *   - rangedHeal 会顶掉 rangedAttack / rangedMassAttack —— 想边打边奶，range 1 用 heal，别用 rangedHeal；
 *   - heal / rangedHeal 还会顶掉 attack：近战奶自己那一 tick 是不出伤害的。
 *
 * 用法：发出动作后 note(creep, 'rangedAttack')，发下一个之前问 wouldVoid(creep, 'rangedHeal')
 * ——「现在发这个，会不会把已经发出去的顶掉」。
 */

// key = 该 intent，value = 只要其中任何一个也发了、key 就被丢弃
const BLOCKED_BY = {
    rangedHeal: ['heal'],
    attackController: ['rangedHeal', 'heal'],
    dismantle: ['attackController', 'rangedHeal', 'heal'],
    repair: ['dismantle', 'attackController', 'rangedHeal', 'heal'],
    build: ['repair', 'dismantle', 'attackController', 'rangedHeal', 'heal'],
    attack: ['build', 'repair', 'dismantle', 'attackController', 'rangedHeal', 'heal'],
    harvest: ['attack', 'build', 'repair', 'dismantle', 'attackController', 'rangedHeal', 'heal'],
    rangedMassAttack: ['build', 'repair', 'rangedHeal'],
    rangedAttack: ['rangedMassAttack', 'build', 'repair', 'rangedHeal'],
};

const runtimeGlobal = typeof global !== 'undefined' ? global : {};
const runtime = runtimeGlobal.__actionRuntime || (runtimeGlobal.__actionRuntime = { tick: -1, byCreep: {}, skipped: {} });
if (!runtime.skipped) runtime.skipped = {};

function table() {
    if (runtime.tick !== Game.time) { runtime.tick = Game.time; runtime.byCreep = {}; }
    return runtime.byCreep;
}

function issuedSet(creep, create) {
    const all = table();
    const name = creep && creep.name;
    if (!name) return null;
    if (!all[name] && create) all[name] = {};
    return all[name] || null;
}

/** 记下本 tick 已经发出的动作 */
function note(creep, action) {
    const set = issuedSet(creep, true);
    if (set) set[action] = true;
    return action;
}

/** 本 tick 是否已经发过这个动作 */
function issued(creep, action) {
    const set = issuedSet(creep, false);
    return !!(set && set[action]);
}

/** 现在发 action，会不会把本 tick 已经发出的某个动作顶掉（返回被顶掉的那个，没有则 null） */
function wouldVoid(creep, action) {
    const set = issuedSet(creep, false);
    if (!set) return null;
    for (const other of Object.keys(set)) {
        const blockers = BLOCKED_BY[other];
        if (blockers && blockers.indexOf(action) >= 0) return other;
    }
    return null;
}

/** action 本身是否已经被本 tick 发出的动作挡住（发了也不会执行） */
function blocked(creep, action) {
    const blockers = BLOCKED_BY[action];
    if (!blockers) return null;
    const set = issuedSet(creep, false);
    if (!set) return null;
    for (const blocker of blockers) if (set[blocker]) return blocker;
    return null;
}

/** 因为会顶掉已发出的动作而主动放弃的次数（累计在 global 上，不进 Memory）：
 *  私服探针据此观察「守卫在开火的 tick 真的没发 rangedHeal」 */
function skipped(action) {
    runtime.skipped[action] = (runtime.skipped[action] || 0) + 1;
}

function stats() {
    return runtime.skipped;
}

/** 单测用：清掉本 tick 的记录 */
function reset() {
    runtime.tick = -1;
    runtime.byCreep = {};
    runtime.skipped = {};
}

module.exports = { BLOCKED_BY, note, issued, wouldVoid, blocked, skipped, stats, reset };

modules.aid:
'use strict';
/**
 * 援建：容量大的母房为邻近的弱房（无 storage、容量 < untilCapacity）直接孵满配 creep，memory.home 指向弱房。
 * 弱房靠 400 容量的小身板要爬很久才能达到"每源 5 WORK、300 tick 采完 3000"的采集上限；
 * 母房一只 5W 静态矿工走过去就立刻到位。需求排在外矿之前（spawn.js 合并顺序），母房核心角色缺编时照旧等待。
 */
const config = require('config');
const utils = require('utils');
const movement = require('movement');

function cfg() {
    return Object.assign({ untilCapacity: 1300, storageBelow: 10000, minHomeCapacity: 800, maxRange: 2, haulerCarry: 12, builderWork: 5, lead: 200,
        couriers: 1, exportAbove: 10000, exportKeep: 5000, courierBudget: 1600, routeCacheTicks: 1000 }, config.aid || {});
}

/** from → to 有没有援建 creep 真走得通的路（movement.safeRouteExists：整房避开 SK/他人房，与援建角色的默认移动同口径）。
 *  findRoute 抛错时放行并记错：别因为地图 API 出岔子把整个 spawn.run 带崩，也别据此退役在途的 creep */
function routeOk(from, to, c) {
    try { return movement.safeRouteExists(from, to, c.routeCacheTicks); }
    catch (e) { utils.logErr('aid.safeRoute ' + from + '>' + to, e); return true; }
}

/** bodyFor(budget)：预算不足满配时按预算缩身的身体（spawn 队列在宽限用完后调用）；不给则只能等满配。
 *  strategic：弱房经济还没起来（某个源没人挖 / 没有 hauler）时为 true——可越过母房等能量的发展档请求；
 *  弱房已能自转、只是身板小时为 false——排在母房自己的 builder/hauler 之后（线上 2026-09-05：W33S7 单 spawn 满负荷，
 *  自己的 builder 1/3 等了十几小时、storage 工地停在 10834/30000，却一直给 spawn 闲着、能量满仓的 W35S7/W33S8 送援建 creep） */
function demand(role, slot, body, memory, lead, priority, bodyFor, strategic) {
    return { role, slot, body, memory: Object.assign({ role, slotKey: slot }, memory), lead, priority, bodyFor, strategic: strategic !== false };
}

/** 弱房的某个源一只在岗矿工都没有 → 该源的援建矿工是 strategic */
function sourceManned(creeps, entry, lead) {
    return creeps.some((creep) => creep.memory.role === 'harvester' && alive(creep, lead) &&
        (creep.memory.sourceId ? creep.memory.sourceId === entry.id : creep.memory.sourceIdx === entry.index));
}

/** 弱房没有任何在岗 hauler → 援建 hauler 是 strategic */
function hasHauler(creeps, lead) {
    return creeps.some((creep) => creep.memory.role === 'hauler' && alive(creep, lead) && utils.bodyPartCount(creep.body, 'carry') > 0);
}

/** 弱房是否还缺基本经济：某个源没人挖，或没有 hauler（monitor / 测试用） */
function shortHanded(room, creeps, lead) {
    return roomSources(room).some((entry) => !sourceManned(creeps, entry, lead)) || !hasHauler(creeps, lead);
}

const linearDistance = utils.roomDistance;

function needsAid(home, room) {
    const c = cfg();
    if (!room || !room.controller || !room.controller.my || room.name === home.name) return false;
    // 还没有 spawn 的新房不援：矿工落地采、hauler 没处送、builder 不建 spawn 工地，能量白堆在地上（线上快照 soak：4000 tick 堆了 1.2 万），
    // 开荒归 expansion 的 pioneer
    if (typeof room.find === 'function' && !(room.find(FIND_MY_SPAWNS) || []).length) return false;
    // 有 storage 但里面没多少能量的房（刚建成 storage 的 RCL4）仍算弱房
    if (room.storage && room.storage.store && Number(room.storage.store[RESOURCE_ENERGY] || 0) >= c.storageBelow) return false;
    if (room.energyCapacityAvailable >= c.untilCapacity) return false;
    if (home.energyCapacityAvailable < c.minHomeCapacity) return false;
    if (linearDistance(home.name, room.name) > c.maxRange) return false;
    // 直线距离近不等于走得到：母房到弱房得有一条不穿 SK/他人房的路。没路的援建 creep 在母房原地寻路，还按 home 占着弱房的编制
    // （线上 2026-09-15 W35S7 → W37S5：两个源 18 小时 0 采集——W37S5 自己不补矿工，走得到的 W38S7 也看到"已有 5 WORK"不再援）。
    // 遥测 Memory.rooms[母房].aidNoRoute = 最近一次因此拒援的弱房与 tick
    if (routeOk(home.name, room.name, c)) return true;
    const mem = Memory.rooms && Memory.rooms[home.name];
    if (mem) mem.aidNoRoute = { room: room.name, at: Game.time };
    return false;
}

/** 援建 creep（memory.aid）不在弱房、从当前房已没有到弱房的安全路线（当初派错了，或路上的房被人占了）：标记退役，
 *  由 main.js 紧接着的 spawn.retireReplaced 走回最近的 spawn 回收（编制计数立刻按 isRetiring 排除它，走得到的母房可以接手）。
 *  不然它原地寻路烧 CPU，还按 home 占着弱房的编制。已在弱房的不管（母房那头断路不影响它干活）。
 *  返回本 tick 是否新标记；遥测 Memory.rooms[弱房].aidStranded */
function markStranded(creep) {
    const mem = creep && creep.memory;
    if (!mem || !mem.aid || !mem.home || creep.spawning || utils.isRetiring(mem) || !creep.room || creep.room.name === mem.home) return false;
    if (routeOk(creep.room.name, mem.home, cfg())) return false;
    mem.bodyUpgradeRetiring = true;
    if (Memory.rooms) {
        const target = Memory.rooms[mem.home] || (Memory.rooms[mem.home] = {});
        target.aidStranded = { name: creep.name, role: mem.role, from: creep.room.name, aid: mem.aid, at: Game.time };
    }
    return true;
}

function targets(home) {
    const out = [];
    for (const name in Game.rooms) {
        const room = Game.rooms[name];
        if (needsAid(home, room)) out.push(room);
    }
    return out.sort((a, b) => a.name.localeCompare(b.name));
}

function alive(creep, lead) {
    if (creep.spawning) return true;
    return creep.ticksToLive == null || creep.ticksToLive > lead;
}

function roomSources(room) {
    const mem = (Memory.rooms && Memory.rooms[room.name]) || {};
    const ids = Array.isArray(mem.sources) ? mem.sources : [];
    const found = typeof room.find === 'function' ? room.find(FIND_SOURCES) || [] : [];
    if (ids.length) {
        return ids.map((id, index) => ({ id, index, source: found.find((s) => s.id === id) || null }));
    }
    return found.map((source, index) => ({ id: source.id, index, source }));
}

function getDemands(home) {
    if (!home || !home.controller || !home.controller.my) return [];
    const c = cfg();
    const demands = [];
    let priority = 0;
    for (const room of targets(home)) {
        const cap = home.energyCapacityAvailable;
        const creeps = utils.creepsHome(room.name).filter((creep) => !utils.isRetiring(creep.memory));
        // 1) 每个源 5 WORK（该源完全没人挖时 strategic，只是身板小时排在母房自己的发展档之后）
        const minerBody = utils.makeBody('staticHarvester', cap);
        for (const entry of roomSources(room)) {
            const work = creeps
                .filter((creep) => creep.memory.role === 'harvester' && alive(creep, c.lead) &&
                    (creep.memory.sourceId ? creep.memory.sourceId === entry.id : creep.memory.sourceIdx === entry.index))
                .reduce((sum, creep) => sum + utils.bodyPartCount(creep.body, 'work'), 0);
            if (work >= 5) continue;
            demands.push(demand('harvester', 'aid:harvester:' + room.name + ':' + entry.index, minerBody,
                { home: room.name, sourceIdx: entry.index, sourceId: entry.id, staticMiner: true, aid: home.name }, c.lead, priority++,
                (budget) => utils.makeBody('staticHarvester', budget), !sourceManned(creeps, entry, c.lead)));
        }
        // 2) 一只像样的 hauler（一只都没有时 strategic）
        const carry = creeps.filter((creep) => creep.memory.role === 'hauler' && alive(creep, c.lead))
            .reduce((sum, creep) => sum + utils.bodyPartCount(creep.body, 'carry'), 0);
        if (carry < c.haulerCarry) {
            demands.push(demand('hauler', 'aid:hauler:' + room.name, utils.makeBody('hauler', cap), { home: room.name, aid: home.name }, c.lead, priority++,
                (budget) => utils.makeBody('hauler', budget), !hasHauler(creeps, c.lead)));
        }
        // 3) 有工地时一只大 builder（extension 建得越快，弱房自己的容量涨得越快；从不越过母房自己的发展档）
        const sites = typeof room.find === 'function' ? (room.find(FIND_MY_CONSTRUCTION_SITES) || []).length : 0;
        const builderWork = creeps.filter((creep) => creep.memory.role === 'builder' && alive(creep, c.lead))
            .reduce((sum, creep) => sum + utils.bodyPartCount(creep.body, 'work'), 0);
        if (sites > 0 && builderWork < c.builderWork) {
            demands.push(demand('builder', 'aid:builder:' + room.name, utils.makeBody('builder', cap), { home: room.name, aid: home.name }, c.lead, priority++,
                (budget) => utils.makeBody('builder', budget), false));
        }
        // 4) 母房 storage 富余（≥ exportAbove）时派 courier 把能量搬到弱房（弱房要有 spawn 可收）：能量在母房 storage 里闲着，
        //    新房却靠 20/tick 的自产爬 extension；只多付一只 hauler 的 spawn 时间
        const storage = home.storage;
        const levels = utils.aidExportLevels(c, config.upgrading);
        const exportable = storage && storage.my !== false && storage.store && Number(storage.store[RESOURCE_ENERGY] || 0) >= levels.above;
        const couriers = creeps.filter((creep) => creep.memory.role === 'courier' && alive(creep, c.lead)).length;
        const weakSpawns = typeof room.find === 'function' ? (room.find(FIND_MY_SPAWNS) || []).length : 0;
        if (exportable && couriers < c.couriers && weakSpawns > 0) {
            const budget = Math.min(cap, c.courierBudget);
            demands.push(demand('courier', 'aid:courier:' + room.name, utils.makeBody('hauler', budget), { home: room.name, from: home.name, aid: home.name }, c.lead, priority++,
                (b) => utils.makeBody('hauler', Math.min(b, c.courierBudget)), false));
        }
    }
    return demands;
}

module.exports = { getDemands, needsAid, linearDistance, shortHanded, markStranded };

modules.boost:
'use strict';
/**
 * Boost 流水线（移植 overmind-absorb 79a5ee4 / 6dd5cbb，重建在当前 main 上）：出发前把 creep 送到装着化合物的 lab 旁强化。
 * 我们原本只会**读**敌人的 boost（defense.js 的战力公式），自己从来不上。
 *
 * 引擎规则（@screeps/common constants 与 engine/src/game/structures.js）：
 *   - 每个身体部件消耗 LAB_BOOST_MINERAL(30) 化合物 + LAB_BOOST_ENERGY(20) 能量
 *   - creep 必须与 lab **相邻**（range 1）
 *   - 孵化中 boost 已经被移除（2018 年的改动），只能对已出生的 creep 做
 *
 * 用法：给 creep 写 memory.boosts = ['XZH2O', …]（化合物列表；攻城 creep 由 conquest.demand 按指令的 boosts 或 config.conquest.boosts 写入，默认空 = 关闭）。
 * pending(creep) 说明还有做得到的强化没做完；apply(creep) 每 tick 推进一步，返回 true 表示调用方这一 tick 别走。
 * 三道保险，绝不让一队人卡在家里等永远不会来的化合物：
 *   1. 没有对应 lab、货或能量不够 ⇒ 这项算「做不到」，不 pending
 *   2. boostCreep 报 OK/不在射程以外的错（lab 未激活 ERR_RCL_NOT_ENOUGH 等）⇒ 这项记进 memory.boostSkip，不再试
 *   3. 从第一次 pending 起等满 config.conquest.boostMaxWait tick 还没做完 ⇒ memory.boostDone，整份清单放弃
 * 只在母房（memory.home）做：途经别的己方房不绕去它的 lab。
 */
const config = require('config');
const movement = require('movement');

const MINERAL_PER_PART = typeof LAB_BOOST_MINERAL !== 'undefined' ? LAB_BOOST_MINERAL : 30;
const ENERGY_PER_PART = typeof LAB_BOOST_ENERGY !== 'undefined' ? LAB_BOOST_ENERGY : 20;

function maxWait() {
    const value = Number((config.conquest || {}).boostMaxWait);
    return Number.isFinite(value) && value > 0 ? value : 100;
}

/** 这只 creep 还想要的化合物（已经上过的、试过做不了的不再要） */
function wanted(creep) {
    const mem = creep.memory || {};
    const list = Array.isArray(mem.boosts) ? mem.boosts : [];
    if (!list.length || mem.boostDone) return [];
    const applied = new Set((creep.body || []).map((part) => part.boost).filter(Boolean));
    const skipped = new Set(Array.isArray(mem.boostSkip) ? mem.boostSkip : []);
    return list.filter((compound) => !applied.has(compound) && !skipped.has(compound));
}

/** 这个化合物能强化的部件类型（BOOSTS 表反查） */
function partTypeFor(compound) {
    if (typeof BOOSTS === 'undefined' || !BOOSTS) return null;
    for (const partType of Object.keys(BOOSTS)) {
        if (BOOSTS[partType] && BOOSTS[partType][compound]) return partType;
    }
    return null;
}

/** 房里装着这个化合物、且货与能量都够强化 parts 个部件的 lab；industry 选的 boost lab（labRoles.boost）优先，
 *  免得从反应三连的输入 lab 里抽走下一批反应的原料 */
function labFor(room, compound, parts) {
    const need = Math.max(1, parts) * MINERAL_PER_PART;
    const needEnergy = Math.max(1, parts) * ENERGY_PER_PART;
    const labs = room.find(FIND_MY_STRUCTURES).filter((s) => s.structureType === STRUCTURE_LAB);
    const roles = typeof Memory !== 'undefined' && Memory.rooms && Memory.rooms[room.name] && Memory.rooms[room.name].labRoles;
    const preferred = roles && roles.boost;
    if (preferred) labs.sort((a, b) => (b.id === preferred) - (a.id === preferred));
    for (const lab of labs) {
        const store = lab.store;
        if (!store) continue;
        if (Number(store[compound] || 0) < need) continue;
        if (Number(store[RESOURCE_ENERGY] || 0) < needEnergy) continue;
        return lab;
    }
    return null;
}

/** 下一项做得到的强化：{ compound, partType, parts, lab }，没有就 null */
function nextJob(creep) {
    const room = creep.room;
    if (!room || !room.controller || !room.controller.my) return null;
    const home = creep.memory && creep.memory.home;
    if (home && room.name !== home) return null;
    for (const compound of wanted(creep)) {
        const partType = partTypeFor(compound);
        if (!partType) continue;
        const parts = (creep.body || []).filter((part) => part.type === partType && !part.boost).length;
        if (!parts) continue;
        const lab = labFor(room, compound, parts);
        if (lab) return { compound, partType, parts, lab };
    }
    return null;
}

/** 还有想要且**做得到**的强化没做完（做不到的项不算，免得整队卡在家里）；等满 boostMaxWait 就整份放弃 */
function pending(creep) {
    const mem = creep.memory || {};
    if (!Array.isArray(mem.boosts) || !mem.boosts.length || mem.boostDone) return false;
    if (!nextJob(creep)) return false;
    if (mem.boostSince == null) mem.boostSince = Game.time;
    if (Game.time - mem.boostSince >= maxWait()) {
        mem.boostDone = true;
        return false;
    }
    return true;
}

/** 记下一次成功的强化（母房 Memory，保留最近 10 条）：被强化的 creep 只活 1500 tick，身体上的 boost 字段随它一起消失，
 *  「这一批强化到底做没做成」事后只能查这里（监控与私服生效断言都读它） */
function noteBoost(creep, compound, partType, parts) {
    if (typeof Memory === 'undefined') return;
    const home = (creep.memory && creep.memory.home) || (creep.room && creep.room.name);
    if (!home) return;
    Memory.rooms = Memory.rooms || {};
    const mem = Memory.rooms[home] || (Memory.rooms[home] = {});
    const log = Array.isArray(mem.boostLog) ? mem.boostLog : (mem.boostLog = []);
    log.unshift({ at: Game.time, creep: creep.name, role: creep.memory && creep.memory.role, compound, part: partType, parts, room: creep.room && creep.room.name });
    log.length = Math.min(log.length, 10);
}

/** 推进一步：走到 lab 旁 / 强化。返回 true 表示这一 tick 已经在做（走路或强化），调用方应原地别走 */
function apply(creep) {
    const job = nextJob(creep);
    if (!job) return false;
    const ret = job.lab.boostCreep(creep);
    if (ret === ERR_NOT_IN_RANGE) { movement.go(creep, job.lab, { range: 1, reusePath: 10 }); return true; }
    if (ret === OK) { noteBoost(creep, job.compound, job.partType, job.parts); return true; }
    // 其它错误（lab 未激活、货刚被搬走…）：这项记成做不了，下一 tick 评估清单里的下一项，不再原地重试同一个
    const mem = creep.memory;
    mem.boostSkip = (Array.isArray(mem.boostSkip) ? mem.boostSkip : []).concat([job.compound]);
    return false;
}

/** 角色入口：清单里还有做得到的强化就推进一步并返回 true（调用方本 tick 直接 return） */
function run(creep) {
    if (!creep.memory || !Array.isArray(creep.memory.boosts) || !creep.memory.boosts.length) return false;
    if (!pending(creep)) return false;
    return apply(creep);
}

module.exports = { wanted, partTypeFor, labFor, nextJob, pending, apply, run, noteBoost, MINERAL_PER_PART, ENERGY_PER_PART };

modules.brain:
'use strict';
/**
 * 外部大脑指令消费者。
 * 外部程序（scripts/brain）通过 HTTP API 把情报与规划写进 Memory.brain；游戏内只做三件事：
 *   1. 校验契约（version / issuedAt / ttlMs），坏指令整份忽略并记一次错误，绝不影响经济链；
