'use strict';
/**
 * bucket 吃紧时的 creep 降载（main.js 的 creep 循环调用）。
 *
 * 旧护栏（bucket 健康时照旧使用）：creep 循环超过 limit − cpuReserve 后只跳 broker 分数 < 20 的单位，而 harvester/hauler/upgrader
 * 一律照跑、其余角色分数几乎都 ≥ 20——线上 2026-10-08 cpuBy 合计 145–166 > limit 150 时 skippedCpu 全房 0，bucket 一路掉向 0，
 * 也没有任何东西看 Game.cpu.bucket。归零后每个超 limit 的 tick 被引擎整个掐断（movement.endTick 都不跑）。
 *
 * 降载模式（bucket < config.cpuShed.lowBucket / criticalBucket，或 Memory.cpuShedForce 手动强制）：
 *  - creep 循环上限压到 limit − lowReserve / criticalReserve，整 tick 落在 limit 以内，bucket 回涨；
 *  - 超上限后只跳"跳一 tick 也安全"的单位，按价值从低到高：scout、预定富余的 reserver → 空闲的搬运/建造单位、operator、
 *    矿物矿工 → （仅紧急）空车外矿运输工、在路上的 reserver；
 *  - 永不跳：本房源矿工（harvester）、upgrader、remoteMiner、防御/攻城/占领单位、每个房最后一只能跑的 hauler；
 *  - 同一只 creep 最多连续跳 maxConsecutive tick。
 * 被跳的 creep 这一 tick 不发任何动作，和旧护栏的跳过同一条路（markSkipped 'cpu'），不丢已发出的意图。
 *
 * tickLimit 硬停（所有模式都生效）：上面的上限只看 limit，从不看 Game.cpu.tickLimit。bucket≈0 时 tickLimit == limit，
 * 永不跳的单位照跑也能把 tick 推过 tickLimit——引擎会把整个 tick 掐掉（所有已发出的意图一起作废，movement.endTick 也不跑）。
 * 所以 getUsed 一旦超过 tickLimit − endReserve（循环之后的 move.end + flush + Memory 序列化）就不再跑任何 creep（永不跳的也停），
 * 收尾照常。永不跳的单位排在队列前面，硬停只砍尾巴。离硬停线还远（> hardStopArm）时不逐只读 getUsed，健康 bucket 下零开销。
 */
const config = require('config');
const utils = require('utils');
const taskBroker = require('task_broker');

const runtimeGlobal = typeof global !== 'undefined' ? global : {};
const runtime = runtimeGlobal.__cpuShedRuntime || (runtimeGlobal.__cpuShedRuntime = {
    streak: {},
    win: null,
});

function settings() {
    return config.cpuShed || {};
}

function emptyWindow() {
    return { ticks: 0, low: 0, crit: 0, forced: 0, skip: 0, roles: {}, hard: 0, cut: 0, hardEnd: 0 };
}

/** 硬停线 = tickLimit − endReserve；Memory.cpuShedForce.stop 在 stopUntil 之前覆盖它（私服验证：私服的 tickLimit 是整个 bucket，碰不到）。
 *  没有 tickLimit（模拟器/老私服/单测）返回 null = 不硬停 */
function hardStopLine(cpu, force, time) {
    if (force && Number(force.stopUntil) > time && force.stop !== null && force.stop !== undefined && Number.isFinite(Number(force.stop))) return Number(force.stop);
    const tickLimit = cpu && cpu.tickLimit;
    if (typeof tickLimit !== 'number' || !Number.isFinite(tickLimit)) return null;
    return tickLimit - (Number(settings().endReserve) || 0);
}

/** 本 tick 的模式：normal / low / critical。Memory.cpuShedForce = {mode, cap?, until} 在 until 之前强制（控制台预先降载、私服验证） */
function modeFor(cpu, force, time) {
    const cfg = settings();
    if (force && Number(force.until) > time && (force.mode === 'low' || force.mode === 'critical')) return force.mode;
    const bucket = cpu && cpu.bucket;
    if (typeof bucket !== 'number') return 'normal';   // 模拟器/老私服没有 bucket
    if (bucket < Number(cfg.criticalBucket)) return 'critical';
    if (bucket < Number(cfg.lowBucket)) return 'low';
    return 'normal';
}

function creepCap(cpu, mode, force, time) {
    const cfg = settings();
    const limit = Number(cpu && cpu.limit) || 0;
    if (mode === 'normal') return limit - (Number(config.cpuReserve) || 0);
    if (force && Number(force.until) > time && Number.isFinite(Number(force.cap)) && force.cap !== null) return Number(force.cap);
    return limit - (Number(mode === 'critical' ? cfg.criticalReserve : cfg.lowReserve) || 0);
}

/** tick 开头调用：模式、creep 循环上限，降载时再备好每房可跑 hauler 的计数 */
function begin() {
    const cpu = typeof Game !== 'undefined' ? Game.cpu : null;
    const force = typeof Memory !== 'undefined' && Memory ? Memory.cpuShedForce : null;
    const forced = !!(force && Number(force.until) > Game.time);
    if (force && !forced && typeof Memory !== 'undefined') delete Memory.cpuShedForce;   // 过期即清
    const mode = modeFor(cpu, forced ? force : null, Game.time);
    const ctx = { mode, active: mode !== 'normal', cap: creepCap(cpu, mode, forced ? force : null, Game.time), rank: {}, haulers: {} };
    // 硬停：离线还远就不逐只读 getUsed（armed=false），bucket 见底时 tickLimit 收到 limit 才 armed
    ctx.hardStop = hardStopLine(cpu, forced ? force : null, Game.time);
    const used = cpu && typeof cpu.getUsed === 'function' ? Number(cpu.getUsed()) || 0 : 0;
    ctx.armed = ctx.hardStop !== null && ctx.hardStop - used < (Number(settings().hardStopArm) || 0);
    ctx.stopped = false;
    const win = runtime.win || (runtime.win = emptyWindow());
    win.ticks++;
    if (mode === 'low') win.low++;
    if (mode === 'critical') win.crit++;
    if (forced) win.forced++;
    if (Game.time % 100 === 0) {
        for (const name of Object.keys(runtime.streak)) {
            if (!(runtime.streak[name].t >= Game.time - 5)) delete runtime.streak[name];
        }
    }
    return ctx;
}

function storeUsed(creep) {
    const store = creep && creep.store;
    if (!store) return 0;
    if (typeof store.getUsedCapacity === 'function') return Number(store.getUsedCapacity()) || 0;
    return Number(store[typeof RESOURCE_ENERGY === 'undefined' ? 'energy' : RESOURCE_ENERGY]) || 0;
}

/** reserver 站在自己的外矿房里、预定是我方且还剩 ≥ reserverComfort：跳一 tick 只少一 tick 的增量 */
function reservationComfortable(creep) {
    const remoteRoom = creep.memory && creep.memory.remoteRoom;
    if (!remoteRoom || !creep.room || creep.room.name !== remoteRoom) return false;
    const reservation = creep.room.controller && creep.room.controller.reservation;
    if (!reservation) return false;
    if (creep.owner && creep.owner.username && reservation.username !== creep.owner.username) return false;
    return Number(reservation.ticksToEnd) >= Number(settings().reserverComfort);
}

/** 正在执行"外矿变占领目标"的 reserver（roles/reserver.js claimDuty）有占领窗口，不跳 */
function onClaimDuty(creep) {
    const mem = typeof Memory !== 'undefined' && Memory.rooms && Memory.rooms[creep.memory.home];
    const target = mem && mem.expansion && mem.expansion.target;
    return !!target && target === creep.memory.remoteRoom;
}

/** 可跳等级：数字越小越先跳；null = 不可跳 */
function shedRank(creep, mode) {
    const memory = creep && creep.memory;
    const role = memory && memory.role;
    if (!role) return null;
    const critical = mode === 'critical';
    switch (role) {
    case 'scout':
        return 0;
    case 'reserver':
        if (onClaimDuty(creep)) return null;
        if (reservationComfortable(creep)) return 0;
        // 紧急时在路上的 reserver 也可以晚一 tick 到
        return critical && creep.room && creep.room.name !== memory.remoteRoom ? 2 : null;
    case 'operator':
    case 'mineralMiner':
    case 'labTech':
        return 1;
    case 'remoteHauler':
        if (storeUsed(creep) > 0) return null;
        if (taskBroker.wasIdle(creep)) return 1;
        return critical ? 2 : null;
    case 'hauler':
    case 'builder':
    case 'courier':
    case 'feeder':
        return taskBroker.wasIdle(creep) ? 1 : null;
    default:
        return null;
    }
}

/** 降载时的执行顺序：不可跳的保持 broker 顺序先跑，可跳的按等级从高到低排在后面——上限一到，剩下的正好是最该跳的 */
function arrange(queue, ctx) {
    if (!ctx || !ctx.active) return queue;
    const keep = [];
    const tiers = [[], [], []];
    for (const creep of queue || []) {
        const memory = creep && creep.memory;
        if (memory && memory.role === 'hauler' && !creep.spawning && !utils.isRetiring(memory) && memory.home) {
            ctx.haulers[memory.home] = (ctx.haulers[memory.home] || 0) + 1;
        }
        const rank = creep && !creep.spawning ? shedRank(creep, ctx.mode) : null;
        if (rank == null) { keep.push(creep); continue; }
        ctx.rank[creep.name] = rank;
        tiers[rank].push(creep);
    }
    return keep.concat(tiers[2], tiers[1], tiers[0]);
}

/** 降载模式下这只 creep 能不能跳（还没看 CPU）：可跳等级、连续跳过次数、房里最后一只能跑的 hauler */
function mayShed(creep, ctx) {
    if (!ctx || !ctx.active || !creep || ctx.rank[creep.name] == null) return false;
    const streak = runtime.streak[creep.name];
    const max = Number(settings().maxConsecutive) || 0;
    if (streak && streak.t === Game.time - 1 && streak.n >= max) return false;
    const memory = creep.memory || {};
    if (memory.role === 'hauler' && !((ctx.haulers[memory.home] || 0) > 1)) return false;
    return true;
}

function noteSkip(creep, ctx) {
    const memory = creep.memory || {};
    const streak = runtime.streak[creep.name];
    runtime.streak[creep.name] = { n: streak && streak.t === Game.time - 1 ? streak.n + 1 : 1, t: Game.time };
    if (memory.role === 'hauler' && ctx && memory.home) ctx.haulers[memory.home] = (ctx.haulers[memory.home] || 0) - 1;
    const win = runtime.win || (runtime.win = emptyWindow());
    win.skip++;
    win.roles[memory.role || '?'] = (win.roles[memory.role || '?'] || 0) + 1;
}

/** 循环里每只 creep 前问一次：越过硬停线就返回 true（调用方 break），记一次硬停 */
function hardStopNow(ctx) {
    if (!ctx || !ctx.armed || ctx.stopped) return !!(ctx && ctx.stopped);
    return Game.cpu.getUsed() > ctx.hardStop;
}

/** 记硬停：cut = 这一 tick 没跑的 creep 数。窗口遥测进 Memory.stats.shed（hard/cut），最近一次另记 Memory.cpuHardStop（运维直接看） */
function noteHardStop(ctx, cut) {
    if (!ctx) return;
    ctx.stopped = true;
    const win = runtime.win || (runtime.win = emptyWindow());
    win.hard++;
    win.cut += cut;
    if (typeof Memory !== 'undefined' && Memory) {
        const log = Memory.cpuHardStop || (Memory.cpuHardStop = { n: 0 });
        log.n = (Number(log.n) || 0) + 1;
        log.at = Game.time;
        log.cut = cut;
        log.line = Math.round(ctx.hardStop * 10) / 10;
    }
}

/** 硬停的 tick 收尾（movement.endTick 之后）调用：hardEnd == hard 说明每次硬停之后收尾都跑完了 */
function noteHardStopEnd(ctx) {
    if (!ctx || !ctx.stopped) return;
    const win = runtime.win || (runtime.win = emptyWindow());
    win.hardEnd++;
}

/** Memory.stats 采样（每 30 tick）：窗口内 low/critical/强制的 tick 数、跳过次数与按角色分布，然后清零 */
function digest() {
    const win = runtime.win || emptyWindow();
    runtime.win = emptyWindow();
    return { ticks: win.ticks, low: win.low, crit: win.crit, forced: win.forced, skip: win.skip, roles: win.roles,
        hard: win.hard, cut: win.cut, hardEnd: win.hardEnd };
}

module.exports = { begin, arrange, mayShed, noteSkip, digest, shedRank, modeFor, creepCap, hardStopLine, hardStopNow, noteHardStop, noteHardStopEnd };

modules.defense:
'use strict';
/**
 * 防御执行层（只对 NPC）：
 *   - 母房：塔压得住就交给塔；压不住（无塔/没能量/敌方治疗过高/核心建筑掉血）才要 defender。
 *   - 己方无塔房（开荒中的新房）与外矿：出现武装 Invader 就由最近的有 spawn 的母房出兵；外矿被 InvaderCore 占据则派清核心队。
 *   - 打得过才打：按敌情画像（hostileProfile：血量/伤害/治疗/风筝型/强化/到期 tick）和母房容量找最便宜的能赢的编组（planSquad：
 *     同时交换伤害、对方全部在射程内的悲观模型，我方击杀时间 × winMargin ≤ 对方击杀我方的时间）；风筝型（没有 ATTACK 的远程 Invader
 *     会拉开距离，近战追不上）只用远程组。找不到能赢的编组、或外矿不值这个价（remoteValueShare）就不出兵：外矿停到入侵者到期
 *     （Invader 不能离开房间，寿命 1500），记 defenseLog.skipped。线上 2026-09-05 W33S7 对 W33S6 的两只强化 Invader 连续单送 defender。
 *   - 不盲目续派：defender 阵亡（main.js 清理内存时 noteLoss）后，要再看到比阵亡更新的敌情画像才会再出兵。
 *   - 不可见的房用最近的画像：外矿记录的 threat（远程 creep / defender 观察写入）或外部大脑情报 Memory.map[房].hostileProfile；
 *     外部大脑还可以直接下 defense 指令（brain.get(home, 'defense') = {房: {action: 'fight'|'avoid', squad: {count, body, style}, until}}），
 *     指令在 until 之前优先于游戏内模型。只有情报计数、没有画像时不出兵（等远程 creep 或大脑看到成分）。
 * 需求结构与 remote/expansion 相同，由 spawn.run 合并；己方房的防御是 defense 档，外矿防御是 remoteMaintain 档（不抢母房生存的能量）。
 */
const config = require('config');
const brain = require('brain');
const { bodyCost, repeat, roomDistance } = require('utils');
const tower = require('tower');

const ARMED = ['attack', 'ranged_attack', 'heal', 'work', 'claim'];
const INTEL_FRESH_TICKS = 1500;
const ATTACK_POWER = 30;
const RANGED_ATTACK_POWER = 10;
const HEAL_POWER = 12;
const LIFE = typeof CREEP_LIFE_TIME === 'number' ? CREEP_LIFE_TIME : 1500;
// 强化倍率（BOOSTS 常量表；NPC Invader 用 UH/KO/LO/ZH/GO，中心区用 X 级）
const BOOSTS = {
    attack: { UH: 2, UH2O: 3, XUH2O: 4 },
    ranged_attack: { KO: 2, KHO2: 3, XKHO2: 4 },
    heal: { LO: 2, LHO2: 3, XLHO2: 4 },
    tough: { GO: 0.7, GHO2: 0.5, XGHO2: 0.3 },
};

function settings() {
    return Object.assign({ minCapacity: 260, idleTicks: 50, maxDefenders: 3, winMargin: 1.5, squadWait: 300, remoteValueShare: 0.5, maxOwnLosses: 2 },
        config.defense || {});
}

function activeParts(creep, type) {
    if (typeof creep.getActiveBodyparts === 'function') return creep.getActiveBodyparts(type);
    return (creep.body || []).filter((part) => (part.type || part) === type && part.hits !== 0).length;
}

const COMBAT = ['attack', 'ranged_attack', 'heal'];
const NPC_OWNERS = ['Invader', 'Source Keeper'];

/** 己方房里任何带 ARMED 部件的敌人都算（拆墙的 WORK、抢控制器的 CLAIM 都是攻击）；
 *  外矿（strict）里只算 NPC 与带战斗部件的玩家 creep：路过的玩家矿工/reserver 不是要出兵的威胁——
 *  外矿防御放开"最近母房"门之后，旧口径会对邻居（W35S8 的 Alepoldar）路过的 WORK/CLAIM creep 出兵 */
function isArmed(creep, strict) {
    const owner = creep && creep.owner && creep.owner.username;
    const parts = strict && NPC_OWNERS.indexOf(owner) < 0 ? COMBAT : ARMED;
    return parts.some((type) => activeParts(creep, type) > 0);
}

function armedHostiles(room) {
    const own = !!(room && room.controller && room.controller.my);
    return room.find(FIND_HOSTILE_CREEPS).filter((creep) => isArmed(creep, !own));
}

function invaderCore(room) {
    const type = typeof STRUCTURE_INVADER_CORE === 'undefined' ? 'invaderCore' : STRUCTURE_INVADER_CORE;
    return room.find(FIND_STRUCTURES).find((structure) => structure.structureType === type) || null;
}

/** 有 spawn 的己方房里离 roomName 最近的那个负责派兵（多母房时避免重复需求） */
function closestBase(roomName) {
    let best = null;
    let bestDistance = Infinity;
    for (const room of Object.values(Game.rooms || {})) {
        if (!room.controller || !room.controller.my || !room.find(FIND_MY_SPAWNS).length) continue;
        const distance = roomDistance(room.name, roomName);
        if (distance < bestDistance) { best = room.name; bestDistance = distance; }
    }
    return best;
}

// ---- 战力模型 ----

function partList(subject) {
    if (Array.isArray(subject)) return subject.map((part) => (part && part.type ? part : { type: part }));
    return (subject && subject.body) || [];
}

/** 单个 creep（或身体数组）的战力：血量（强化 TOUGH 按减伤折算成更多血）、每 tick 伤害（近战 30/远程 10 × 强化）、每 tick 治疗、
 *  风筝型（有远程无近战且能动：引擎里这种 Invader 会主动拉开到 3 格），是否强化 */
function creepProfile(subject) {
    // 活 creep 用它的 hits（部件血量之和）；身体数组按每部件 100。强化 TOUGH 的减伤折算成额外血量
    const live = !Array.isArray(subject) && subject && subject.hits != null;
    let hits = live ? Number(subject.hits) : 0;
    let dps = 0;
    let heal = 0;
    let attack = 0;
    let ranged = 0;
    let move = 0;
    let boosted = false;
    for (const part of partList(subject)) {
        if (!part || part.hits === 0) continue;
        const type = part.type;
        const mult = (part.boost && BOOSTS[type] && BOOSTS[type][part.boost]) || 1;
        if (part.boost) boosted = true;
        const partHits = part.hits == null ? 100 : part.hits;
        if (!live) hits += partHits;
        if (type === 'tough' && mult < 1) hits += partHits * (1 / mult - 1);
        if (type === 'attack') { dps += ATTACK_POWER * mult; attack++; }
        else if (type === 'ranged_attack') { dps += RANGED_ATTACK_POWER * mult; ranged++; }
        else if (type === 'heal') heal += HEAL_POWER * mult;
        else if (type === 'move') move++;
    }
    return { hits, dps, heal, kiter: ranged > 0 && attack === 0 && move > 0, boosted };
}

/** 一群敌人的画像（写进外矿记录 / 情报，房间不可见时也能评估）：until = 最晚到期的 tick */
function hostileProfile(hostiles) {
    const out = { at: Game.time, count: 0, hits: 0, dps: 0, heal: 0, kiters: false, boosted: false, until: Game.time };
    for (const hostile of hostiles || []) {
        const profile = creepProfile(hostile);
        out.count++;
        out.hits += profile.hits;
        out.dps += profile.dps;
        out.heal += profile.heal;
        if (profile.kiter) out.kiters = true;
        if (profile.boosted) out.boosted = true;
        const ttl = Number(hostile.ticksToLive) > 0 ? Number(hostile.ticksToLive) : LIFE;
        out.until = Math.max(out.until, Game.time + ttl);
    }
    out.hits = Math.round(out.hits);
    out.dps = Math.round(out.dps);
    out.heal = Math.round(out.heal);
    return out;
}

function squadProfile(bodies) {
    const out = { hits: 0, dps: 0, heal: 0 };
    for (const body of bodies || []) {
        const profile = creepProfile(body);
        out.hits += profile.hits;
        out.dps += profile.dps;
        out.heal += profile.heal;
    }
    return out;
}

/** 这组身体能不能赢：双方同时交换伤害、对方全部在射程内。我方净伤害 = 我方 dps − 对方治疗，对方净伤害 = 对方 dps − 我方治疗；
 *  我方击杀时间 × margin ≤ 对方击杀我方的时间（对方打不动我方 = 无穷）。没有敌人算赢。 */
function canBeat(bodies, enemy, margin) {
    if (!enemy || !enemy.count) return true;
    const ours = squadProfile(bodies);
    const factor = margin != null ? Number(margin) : settings().winMargin;
    const enemyNet = ours.dps - enemy.heal;
    if (enemyNet <= 0) return false;
    const killTime = enemy.hits / enemyNet;
    const ourNet = enemy.dps - ours.heal;
    const surviveTime = ourNet <= 0 ? Infinity : ours.hits / ourNet;
    return killTime * factor <= surviveTime;
}

// MOVE 排在最前面：受伤先掉的是机动，攻击/治疗部件留到最后
function meleeBody(attack) {
    return repeat('move', attack).concat(repeat('attack', attack));
}

function rangedBody(ranged, heal) {
    return repeat('move', ranged + heal).concat(repeat('ranged_attack', ranged), repeat('heal', heal));
}

/** 母房容量下所有候选身体（按成本升序）：近战 aA aM、远程 rR hH (r+h)M。style 限定只出近战或只出远程 */
function candidates(capacity, style) {
    const list = [];
    if (style !== 'ranged') {
        for (let attack = 2; attack <= 25; attack++) {
            const body = meleeBody(attack);
            const cost = bodyCost(body);
            if (cost > capacity) break;
            list.push({ style: 'melee', body, cost });
        }
    }
    if (style !== 'melee') {
        for (let ranged = 1; ranged <= 25; ranged++) {
            for (let heal = 0; heal <= Math.min(5, ranged); heal++) {
                const body = rangedBody(ranged, heal);
                if (body.length > 50) continue;
                const cost = bodyCost(body);
                if (cost > capacity) continue;
                list.push({ style: 'ranged', body, cost });
            }
        }
    }
    list.sort((left, right) => left.cost - right.cost || left.body.length - right.body.length);
    return list;
}

/** 最便宜的能赢的编组：1..maxDefenders 只同样的身体；风筝型在场只考虑远程。找不到返回 null */
function planSquad(capacity, enemy, cfg) {
    if (!enemy || !enemy.count) return null;
    const options = cfg || settings();
    const list = candidates(capacity, enemy.kiters ? 'ranged' : null);
    let best = null;
    for (let count = 1; count <= Math.max(1, Number(options.maxDefenders) || 1); count++) {
        for (const candidate of list) {
            const bodies = [];
            for (let index = 0; index < count; index++) bodies.push(candidate.body);
            if (!canBeat(bodies, enemy, options.winMargin)) continue;
            const total = candidate.cost * count;
            if (!best || total < best.total) best = { style: candidate.style, body: candidate.body, cost: candidate.cost, count, total };
            break;
        }
    }
    return best;
}

/** 编组到场要多少 tick：攒够总成本（母房 spawn 收入 EMA，没有就按每源 fallbackIncomePerSource）+ 逐只孵化（3 tick/部件）+ 走路（每房 50） */
function assemblyLead(plan, home, roomName, mem) {
    const sources = typeof home.find === 'function' ? home.find(FIND_SOURCES).length : 2;
    const fallback = (Number(config.spawnQueue && config.spawnQueue.fallbackIncomePerSource) || 5) * Math.max(1, sources);
    const ema = mem && mem.spawnIncome && Number(mem.spawnIncome.ema);
    const income = Math.max(0.5, ema > 0 ? ema : fallback);
    const spawnTicks = plan.count * plan.body.length * 3;
    const travel = Math.max(1, roomDistance(home.name, roomName)) * 50;
    return Math.ceil(plan.total / income + spawnTicks + travel);
}

/** 外矿值不值得打：编组总成本 ≤ 到场后入侵者剩余寿命内的期望产出 × remoteValueShare。
 *  返回 {ok, value, lead}。线上 2026-09-05：按"现在的剩余寿命"算出 fight，一只 1000 的 defender 刚孵出大脑就改成 avoid（攒 3000 要 240 tick） */
function worthFighting(plan, record, profile, cfg, home, roomName, mem) {
    if (!record) return { ok: true, value: Infinity, lead: 0 };
    const sources = Number(record.sourceCount) || (record.sources && record.sources.length) || 1;
    const lead = assemblyLead(plan, home, roomName, mem);
    const remaining = Math.max(0, Number(profile.until || 0) - Game.time - lead);
    const value = Math.round(sources * 10 * remaining * (Number(cfg.remoteValueShare) || 0.5));
    return { ok: plan.total <= value, value, lead };
}

/** 把看到的敌情写进外矿记录（remote.refreshVisible / defender 观察时调用）；没有武装敌人就清掉 */
function recordThreat(record, hostiles) {
    if (!record) return null;
    record.threat = hostiles && hostiles.length ? hostileProfile(hostiles) : null;
    return record.threat;
}

/** 房间不可见时可用的画像：外矿记录的 threat 或外部大脑情报 hostileProfile，取较新且未到期的 */
function storedProfile(roomName, record) {
    const own = record && record.threat && Number(record.threat.until) > Game.time ? record.threat : null;
    const info = Memory.map && Memory.map[roomName];
    const external = info && info.hostileProfile && Number(info.hostileProfile.until) > Game.time &&
        Game.time - Number(info.hostileProfile.at != null ? info.hostileProfile.at : info.at || 0) <= INTEL_FRESH_TICKS ? info.hostileProfile : null;
    if (own && external) return Number(own.at || 0) >= Number(external.at || 0) ? own : external;
    return own || external;
}

/** 某房的威胁：可见就看实体（带画像）；不可见用记录的画像 / 外部情报（近期）/ 外矿记录的停用原因 */
function threatIn(roomName, record) {
    const room = Game.rooms[roomName];
    // SK 外矿（remote.js record.sk，config.sk）：keeper 是常驻 NPC、由 skReaper 处理，不算要出兵的威胁——否则 planSquad 对着 5000 血的 keeper
    // 判"打不过"，把外矿停到它"到期"（keeper 不会到期）。别的敌人照常算
    const keeperRoom = !!(record && record.sk);
    if (room) {
        const hostiles = armedHostiles(room).filter((creep) => !(keeperRoom && creep.owner && creep.owner.username === 'Source Keeper'));
        const profile = hostiles.length ? hostileProfile(hostiles) : null;
        return { visible: true, hostiles, count: hostiles.length, core: !!invaderCore(room), ranged: !!(profile && profile.kiters),
            profile, seenAt: Game.time };
    }
    const info = Memory.map && Memory.map[roomName];
    const fresh = info && Game.time - Number(info.at || 0) <= INTEL_FRESH_TICKS;
    const profile = storedProfile(roomName, record);
    // scout 写的 armedHostiles 不分主人（keeper 也算），SK 外矿只认画像（record.threat 与大脑 intel 的 hostileProfile 都已排除 keeper）
    const count = profile ? Number(profile.count) || 0 : (fresh && !keeperRoom ? Number(info.armedHostiles || 0) : 0);
    const core = (fresh && !!info.invaderCore) || (record && record.suspendReason === 'invaderCore');
    // 停用原因 hostileCreep 只在冷却期（suspendedUntil）内算威胁；过期后不可见的房不再盲目派 defender
    const hostile = count > 0 || (record && record.suspendReason === 'hostileCreep' && Number(record.suspendedUntil || 0) > Game.time);
    return { visible: false, hostiles: [], count: hostile ? Math.max(1, count) : 0, core, ranged: !!(profile && profile.kiters),
        profile, seenAt: profile ? Number(profile.at || 0) : (fresh ? Number(info.at || 0) : 0) };
}

/** 清核心队 / 兜底身体 */
function defenderBody(capacity, style) {
    if (style === 'ranged') {
        const ranged = Math.max(1, Math.min(10, Math.floor(capacity * 0.55 / 200)));
        const heal = Math.max(capacity >= 700 ? 1 : 0, Math.min(5, Math.floor(capacity * 0.25 / 300)));
        const body = rangedBody(ranged, heal);
        return bodyCost(body) <= capacity ? body : rangedBody(1, 0);
    }
    const attack = Math.max(2, Math.min(20, Math.floor(capacity / 130)));
    return meleeBody(attack);
}

function demand(role, slot, body, memory, lead, priority, cls) {
    return { role, slot, body, memory: Object.assign({ role, slotKey: slot }, memory), lead, priority, cls: cls || 'defense' };
}

function suspendRecord(record, until, reason) {
    if (!record) return;
    if (record.suspendedUntil === Number.MAX_SAFE_INTEGER) return;
    record.suspendedUntil = Math.max(Number(record.suspendedUntil) || 0, Number(until) || 0);
    record.suspendReason = reason || record.suspendReason || 'hostileCreep';
}

function ownRoom(home, roomName) {
    if (roomName === home.name) return true;
    const room = Game.rooms[roomName];
    return !!(room && room.controller && room.controller.my);
}

/** 对某房的评估（无副作用）：{threat, plan, skip, wait}。plan = {style, body, count, source}；skip = {reason, until} 表示不出兵并可停用外矿；
 *  wait = 只有计数没有成分 / 阵亡后没再看到，等信息。 */
function evaluate(home, roomName, record, cfg, orders, mem) {
    const capacity = home.energyCapacityAvailable;
    const own = ownRoom(home, roomName);
    const threat = threatIn(roomName, record);
    const out = { threat, own, plan: null, skip: null, wait: false };
    if (roomName === home.name && threat.visible) {
        const towers = home.controller.level >= 3
            ? home.find(FIND_MY_STRUCTURES, { filter: (s) => s.structureType === STRUCTURE_TOWER }) : [];
        if (towers.length && tower.towersCanHold(home, towers, threat.hostiles)) return out;
    }
    if (threat.count <= 0) return out;
    const order = orders && orders[roomName] && typeof orders[roomName] === 'object' && Number(orders[roomName].until || 0) > Game.time
        ? orders[roomName] : null;
    if (order && order.action === 'avoid') {
        out.skip = { reason: 'brain:' + (order.reason || 'avoid'), until: Number(order.until) };
        return out;
    }
    // 上一只在这房阵亡之后没再看到新的敌情：不盲目续派（葫芦娃救爷爷）
    const loss = (mem && mem.defenseLog && mem.defenseLog.lastLoss) || null;
    if (loss && loss.room === roomName && Number(threat.seenAt || 0) <= Number(loss.at || 0)) { out.wait = true; return out; }
    if (order && order.action === 'fight' && order.squad && Array.isArray(order.squad.body) && order.squad.body.length &&
        bodyCost(order.squad.body) <= capacity) {
        const body = order.squad.body.slice();
        out.plan = { style: order.squad.style || (body.includes('attack') ? 'melee' : 'ranged'), body,
            count: Math.max(1, Math.min(Number(cfg.maxDefenders) || 1, Number(order.squad.count) || 1)), source: 'brain' };
        return out;
    }
    // 己方房连续阵亡上限：本房敌人一直可见，上面的"阵亡后没再看到敌情"门永远不闭（2026-09-06 W31S5 连送 7 只 2A2M 阵亡 6 只）。
    // 同一波敌人阵亡 maxOwnLosses 只后停到敌人到期，房间清场后 streak 归零（getDemands）；大脑 fight 指令在上面已越过
    const streak = own ? Number(roomLog(roomName).streak || 0) : 0;
    if (own && streak >= (Number(cfg.maxOwnLosses) || Infinity)) {
        out.skip = { reason: 'losses:' + streak, until: Number(threat.profile && threat.profile.until) || Game.time + CREEP_LIFE_TIME_FALLBACK };
        return out;
    }
    if (!threat.profile) { out.wait = true; return out; }   // 只有计数没有成分：等远程 creep 或大脑看到成分再决定
    const plan = planSquad(capacity, threat.profile, cfg);
    if (!plan) { out.skip = { reason: 'unwinnable', until: Number(threat.profile.until), capacity }; return out; }
    if (!own) {
        const worth = worthFighting(plan, record, threat.profile, cfg, home, roomName, mem);
        if (!worth.ok) {
            out.skip = { reason: 'notWorth:' + plan.total + '>' + worth.value, until: Number(threat.profile.until), lead: worth.lead };
            return out;
        }
    }
    out.plan = Object.assign({ source: 'model' }, plan);
    return out;
}

const CREEP_LIFE_TIME_FALLBACK = 1500;

/** 被防守房自己的 defenseLog（连续阵亡计数 streak 记在被防守房，不管 defender 由哪个母房孵） */
function roomLog(roomName) {
    if (typeof Memory === 'undefined' || !Memory.rooms) return {};
    const mem = Memory.rooms[roomName] || (Memory.rooms[roomName] = {});
    return mem.defenseLog || (mem.defenseLog = { spawned: 0 });
}

function remoteRecordOf(home, roomName) {
    const mem = Memory.rooms && Memory.rooms[home.name];
    return (mem && mem.remotes && mem.remotes[roomName]) || null;
}

/** 现在还想不想为 roomName 出兵（无副作用）：正在家里集结的 defender 用它判断该继续等还是退役 */
function planFor(home, roomName) {
    if (!home || !home.controller || !home.controller.my) return null;
    const cfg = settings();
    if (home.energyCapacityAvailable < cfg.minCapacity) return null;
    const mem = Memory.rooms && Memory.rooms[home.name] || null;
    const result = evaluate(home, roomName, remoteRecordOf(home, roomName), cfg, brain.get(home.name, 'defense', null), mem);
    if (result.plan) return result.plan;
    return !result.threat.count && result.threat.core ? { style: 'melee', count: 1, core: true } : null;
}

/** 母房需要为防御孵化的 creep 需求 */
function getDemands(home) {
    if (!home || !home.controller || !home.controller.my) return [];
    const cfg = settings();
    const capacity = home.energyCapacityAvailable;
    if (capacity < cfg.minCapacity) return [];
    const mem = Memory.rooms && (Memory.rooms[home.name] || (Memory.rooms[home.name] = {}));
    const logOf = () => (mem ? (mem.defenseLog || (mem.defenseLog = { spawned: 0 })) : { spawned: 0 });
    const orders = brain.get(home.name, 'defense', null);
    const demands = [];
    let priority = 0;
    const seen = new Set();
    const consider = (roomName, record) => {
        if (seen.has(roomName)) return;
        seen.add(roomName);
        // 己方无 spawn 的房（没有外矿记录）每个母房都会考虑一遍：只让最近的那个出兵。外矿只由拥有记录的母房考虑，不套这道门——
        // 以前外矿也要"本房是切比雪夫最近的有 spawn 房"，所属母房不是最近的那条外矿就没人防、大脑的 fight 指令也被丢掉
        // （线上 2026-09-11 8/17 条启用外矿无人防守，入侵一次停产 1300–1500 tick）
        if (!record && closestBase(roomName) !== home.name) return;
        // 不在编的外矿（remote.staffRemotes）没人在采，不值得出兵
        if (record && record.enabled && record.staffed === false) return;
        // safe mode 中的己方房：敌人打不了任何东西，defender 赶到也无事可做（2026-09-06 W31S8 开盾 18 tick 后仍孵了 2 只）
        const target = Game.rooms[roomName];
        if (target && target.controller && target.controller.my && target.controller.safeMode > 0) return;
        const result = evaluate(home, roomName, record, cfg, orders, mem);
        const threat = result.threat;
        if (threat.visible && record) recordThreat(record, threat.hostiles);
        // 己方房清场：连续阵亡计数归零（下一波敌人重新计）
        if (result.own && threat.visible && threat.count === 0) {
            const log = roomLog(roomName);
            if (log.streak !== 0) log.streak = 0;
        }
        const cls = result.own ? 'defense' : 'remoteMaintain';
        if (result.skip) {
            logOf().skipped = Object.assign({ room: roomName, at: Game.time, count: threat.count }, result.skip);
            suspendRecord(record, result.skip.until, 'hostileCreep');
            return;
        }
        if (result.plan) {
            for (let index = 0; index < result.plan.count; index++) {
                const slot = index === 0 ? 'defender:' + roomName : 'defender:' + roomName + ':' + index;
                demands.push(demand('defender', slot, result.plan.body,
                    { home: home.name, targetRoom: roomName, style: result.plan.style, squad: result.plan.count }, 50, priority++, cls));
            }
            return;
        }
        // keeper 房里的 invader core 是 stronghold（带塔/rampart），清核心队的近战 defender 打不动，不派（外矿保持 invaderCore 停用）
        if (!threat.count && threat.core && !(record && record.sk)) {
            demands.push(demand('defender', 'core:' + roomName, defenderBody(capacity, 'melee'),
                { home: home.name, targetRoom: roomName, style: 'melee' }, 50, priority++, cls));
        }
    };
    consider(home.name, null);
    for (const room of Object.values(Game.rooms || {})) {
        if (room.controller && room.controller.my && room.name !== home.name) consider(room.name, null);
    }
    const remotes = mem && mem.remotes || {};
    for (const [roomName, record] of Object.entries(remotes)) {
        if (record && (record.enabled || record.suspendReason === 'invaderCore' || record.suspendReason === 'hostileCreep')) consider(roomName, record);
    }
    return demands;
}

/** defender 死亡（不是主动退役）：记进母房 defenseLog，getDemands 据此在再次看到敌情前不续派。main.js 清理死亡 creep 内存时调用 */
function noteLoss(name, memory) {
    if (!memory || memory.role !== 'defender' || memory.retired) return false;
    const home = memory.home;
    if (!home || typeof Memory === 'undefined' || !Memory.rooms) return false;
    const mem = Memory.rooms[home] || (Memory.rooms[home] = {});
    const log = mem.defenseLog || (mem.defenseLog = { spawned: 0 });
    log.losses = (log.losses || 0) + 1;
    log.lastLoss = { at: Game.time, room: memory.targetRoom || home, name, slot: memory.slotKey || null };
    // 被防守房的连续阵亡计数（己方房的阵亡上限 maxOwnLosses 用它；房间清场后归零）
    const defended = roomLog(memory.targetRoom || home);
    defended.streak = (Number(defended.streak) || 0) + 1;
    console.log('[defense] ' + home + ' lost defender ' + name + ' in ' + (memory.targetRoom || home));
    return true;
}

module.exports = { getDemands, planFor, defenderBody, threatIn, armedHostiles, invaderCore, settings, creepProfile, hostileProfile,
    canBeat, planSquad, recordThreat, noteLoss, BOOSTS };

modules.demolition:
'use strict';
/** 拆迁调度：规划（轮子方案）确定后，与之冲突的工地和既有建筑在合适的时机拆掉。
 *  - 方案外的工地：立即移除（工地不值钱）。
 *  - 压在规划位上的道路/容器/墙：立即拆（它们不占 RCL 配额，只是挡路）。
 *  - 方案外、占 RCL 配额的结构（extension/塔/lab/link/storage/terminal…）：只在"拆掉后规划位能立刻放出替代工地"
 *    （配额已满且方案内仍有未建位）时拆，一次一个，替代工地建成前不拆下一个。
 *  - 方案外的 spawn：只有方案位上已有建成的 spawn 才拆（RCL7 前只有 1 个配额，拆了全房停摆）。塔同理，保留唯一的塔。
 *  - 方案外的 rampart：从不主动拆（不占位、不占配额），utils.needsRepair 不再维修它，任其衰减；盖在 spawn/塔/storage/terminal 上的例外。
 *  - 敌方遗留、占掉本房配额的结构（打下/占下的房里别人的 spawn/extension/塔…）：引擎 checkControllerAvailability 计数不分主人，
 *    它们让我们连工地都放不出来。只在「全房同类数 ≥ 配额且我们自己的 < 配额」时拆，不看方案、不受恢复期/能量门控
 *    （拆它不花我们任何东西，恰恰是走出恢复期的前提）；有敌对 creep 时 destroy 回 ERR_BUSY，照旧不拆。
 *  每房每 interval tick 评估一次、最多拆 1 个结构；房里有敌对 creep、恢复期或 spawn 能量低于 minEnergy 时不拆。 */
const config = require('config');
const layout = require('layout');
const wheelLayout = require('wheel_layout');
const { logErr, rampartProtectsCore, isRoomPhaseTick } = require('utils');

function settings() {
    return Object.assign({ interval: 25, minEnergy: 300, logSize: 20, batch: 4, keepStoredBelow: 0 }, config.demolition || {});
}

/** 常量可能在测试环境缺失：按名字取，缺了就用回退值 */
function constant(name, fallback) {
    return typeof global[name] !== 'undefined' ? global[name] : fallback;
}

function typeKey(structureType) {
    const keys = {
        [constant('STRUCTURE_SPAWN', 'spawn')]: 'spawn', [constant('STRUCTURE_EXTENSION', 'extension')]: 'extension',
        [constant('STRUCTURE_TOWER', 'tower')]: 'tower', [constant('STRUCTURE_STORAGE', 'storage')]: 'storage',
        [constant('STRUCTURE_LINK', 'link')]: 'link', [constant('STRUCTURE_TERMINAL', 'terminal')]: 'terminal',
        [constant('STRUCTURE_LAB', 'lab')]: 'lab', [constant('STRUCTURE_EXTRACTOR', 'extractor')]: 'extractor',
        [constant('STRUCTURE_OBSERVER', 'observer')]: 'observer', [constant('STRUCTURE_POWER_SPAWN', 'powerSpawn')]: 'powerSpawn',
        [constant('STRUCTURE_NUKER', 'nuker')]: 'nuker', [constant('STRUCTURE_FACTORY', 'factory')]: 'factory',
    };
    return keys[structureType] || null;
}

/** 从不拆的类型：controller / rampart（方案外任其衰减）/ 中立地物 */
const NEVER_TYPES = new Set(['STRUCTURE_CONTROLLER', 'STRUCTURE_RAMPART', 'STRUCTURE_KEEPER_LAIR', 'STRUCTURE_PORTAL', 'STRUCTURE_POWER_BANK', 'STRUCTURE_INVADER_CORE']
    .map((name) => constant(name, name.slice(10).toLowerCase())));

function posKey(pos) {
    return pos.x + '.' + pos.y;
}

/** 规划位索引：格 -> 该格规划的结构类型；类型 -> 规划位列表 */
function planIndex(plan) {
    const at = new Map();
    const byType = new Map();
    for (const entry of wheelLayout.plannedEntries(plan)) {
        const key = posKey(entry.pos);
        if (!at.has(key)) at.set(key, []);
        at.get(key).push(entry.type);
        if (!byType.has(entry.type)) byType.set(entry.type, []);
        byType.get(entry.type).push(entry.pos);
    }
    return { at, byType };
}

function plannedHere(index, structureType, pos) {
    const types = index.at.get(posKey(pos)) || [];
    return types.includes(structureType);
}

/** 这个格上的既有结构是否挡住了规划的其它结构（rampart 与谁都能共格，道路与容器可共格） */
function blocksPlan(index, structureType, pos) {
    const types = index.at.get(posKey(pos)) || [];
    return types.some((planned) => planned !== structureType && !wheelLayout.canOverlap(structureType, planned));
}

function holdReason(room, mem, cfg) {
    if (room.find(FIND_HOSTILE_CREEPS).length) return 'hostiles';
    if (mem.state && mem.state.recovering) return 'recovering';
    if (room.energyAvailable < cfg.minEnergy) return 'energy';
    return null;
}

function removeOffPlanSites(room, index, log) {
    let removed = 0;
    const rampartType = typeof STRUCTURE_RAMPART === 'undefined' ? 'rampart' : STRUCTURE_RAMPART;
    for (const site of room.find(FIND_MY_CONSTRUCTION_SITES)) {
        if (plannedHere(index, site.structureType, site.pos)) continue;
        // 外环推迟期间 layout 给 spawn/塔/storage/terminal 盖的 rampart 工地不在 plan.ramparts 里，但和 utils.needsRepair / offPlanRampart 同一规则：
        // 护核心的不算方案外（线上 2026-09-05 W33S7：layout 每 25 tick 放、这里每 25 tick 拆，(6,40)/(7,41)/(31,26) 来回拉锯）
        if (site.structureType === rampartType && rampartProtectsCore(room, site.pos.x, site.pos.y)) continue;
        if (typeof site.remove === 'function' && site.remove() === OK) {
            removed++;
            log({ type: site.structureType, x: site.pos.x, y: site.pos.y, reason: 'site-off-plan' });
        }
    }
    return removed;
}

/** 方案外、占配额的结构此刻能否拆：配额满 + 方案内还有未建位 + 没有同类工地在建（等它建成） */
function cappedReplaceable(room, index, structureType, allow) {
    const key = typeKey(structureType);
    if (!key || !(allow[key] > 0)) return false;
    const structures = room.find(FIND_STRUCTURES).filter((s) => s.structureType === structureType);
    const allSites = room.find(FIND_MY_CONSTRUCTION_SITES);
    const sites = allSites.filter((s) => s.structureType === structureType);
    // 按批替换：同类替代工地在建数达到 batch 才停手（拆一个等建成再拆下一个太慢：20 个 extension 要 1500+ tick）
    if (sites.length >= settings().batch) return false;
    // 工地名额满时拆了也放不出替代工地，容量白掉：等名额（零进度的路/rampart 工地会被 layout 让出，算作可用）
    if (freeSlots(room) <= 0) return false;
    if (structures.length + sites.length < allow[key]) return false;
    const planned = index.byType.get(structureType) || [];
    const unbuilt = planned.filter((pos) => !layout.structureAt(room, pos.x, pos.y, structureType) &&
        !room.lookForAt(LOOK_CONSTRUCTION_SITES, pos.x, pos.y).some((s) => s.structureType === structureType));
    return unbuilt.length > 0;
}

/** 可用工地名额：总名额减在建，零进度的路/rampart/墙工地最多 2 个可被 layout 让出，也算可用 */
function freeSlots(room) {
    const sites = room.find(FIND_MY_CONSTRUCTION_SITES);
    const lowTypes = new Set([constant('STRUCTURE_ROAD', 'road'), constant('STRUCTURE_RAMPART', 'rampart'), constant('STRUCTURE_WALL', 'constructedWall')]);
    const yieldable = sites.filter((s) => lowTypes.has(s.structureType) && !(s.progress > 0)).length;
    return (Number(config.maxSites) || 6) - sites.length + Math.min(2, yieldable);
}

function plannedUnbuiltCount(room, index, structureType) {
    return (index.byType.get(structureType) || []).filter((pos) => !layout.structureAt(room, pos.x, pos.y, structureType) &&
        !room.lookForAt(LOOK_CONSTRUCTION_SITES, pos.x, pos.y).some((s) => s.structureType === structureType)).length;
}

/** 方案内的源/controller 容器（矿容器除外）是否都已建成：是则方案外的旧容器已无用 */
function plannedContainersBuilt(room, index) {
    const plan = Memory.rooms && Memory.rooms[room.name] && Memory.rooms[room.name].plan;
    if (!plan || !plan.containers) return false;
    const keys = Object.keys(plan.containers).filter((key) => key !== 'mineral');
    if (!keys.length) return false;
    return keys.every((key) => {
        const pos = plan.containers[key];
        return pos && layout.structureAt(room, pos.x, pos.y, STRUCTURE_CONTAINER);
    });
}

function plannedBuiltCount(room, index, structureType) {
    return (index.byType.get(structureType) || []).filter((pos) => layout.structureAt(room, pos.x, pos.y, structureType)).length;
}

function pickTarget(room, index) {
    const allow = layout.allowance(room);
    const candidates = [];
    for (const structure of room.find(FIND_STRUCTURES)) {
        const type = structure.structureType;
        // 打下来的房里敌人留下的 rampart：引擎 move.js 只让 rampart 的主人（或 public rampart）踩上去，
        // 所以那一格对我们的 creep 是永久障碍——盖在规划位上就意味着那个工位永远站不了人。
        // 而 destroy() 只要求「房间控制器是我们的」，不要求结构归我们（引擎 structures.js / destroy-structure.js），
        // 拆得掉。demolition 过去两道门都把它挡在外面：NEVER_TYPES 排在 my === false 之前，
        // 而 NEVER_TYPES 的本意只是保护**我们自己的** rampart。按归属判断，不按类型。
        // （注：rampart 并不挡 createConstructionSite——引擎 utils.checkConstructionSite 明确豁免 rampart 和 road，
        //  所以这里修的是「站不上去」，不是「建不了」。）
        if (structure.my === false && (type === STRUCTURE_RAMPART || type === STRUCTURE_WALL) &&
            typeof structure.destroy === 'function' && (index.at.get(posKey(structure.pos)) || []).length > 0) {
            candidates.push({ structure, priority: 0, reason: 'hostile-blocking' });
            continue;
        }
        if (NEVER_TYPES.has(type)) continue;
        if (structure.my === false) continue;
        // storage / terminal 里还有东西就不拆：它们没有任何特判，会直接落进 cappedReplaceable
        // （RCL4+ allow.storage = 1，一个方案外的 storage 就满足配额条件）。拆掉是不可逆的，
        // 而这一格的方案位早晚会腾出来——先把货搬空再说。
        if ((type === STRUCTURE_STORAGE || type === STRUCTURE_TERMINAL) &&
            structure.store && structure.store.getUsedCapacity() > (settings().keepStoredBelow || 0)) continue;
        if (typeof structure.destroy !== 'function') continue;
        if (plannedHere(index, type, structure.pos)) continue;
        if (type === STRUCTURE_ROAD || type === STRUCTURE_CONTAINER || type === STRUCTURE_WALL) {
            if (blocksPlan(index, type, structure.pos)) candidates.push({ structure, priority: 0, reason: 'blocking' });
            else if (type === STRUCTURE_CONTAINER && plannedContainersBuilt(room, index)) candidates.push({ structure, priority: 3, reason: 'container-redundant' });
            continue;
        }
        if (type === STRUCTURE_SPAWN) {
            // 方案位上已有建成的 spawn 才拆旧的；否则这是唯一的 spawn
            if (plannedBuiltCount(room, index, STRUCTURE_SPAWN) >= 1) candidates.push({ structure, priority: 1, reason: 'spawn-replaced' });
            continue;
        }
        if (type === STRUCTURE_TOWER) {
            if (plannedBuiltCount(room, index, STRUCTURE_TOWER) >= 1) candidates.push({ structure, priority: 1, reason: 'tower-replaced' });
            // 唯一的塔：safe mode 可用（拆掉到新塔建成之间有兜底）且方案位可放时也直接替换
            else if (room.controller.safeModeAvailable > 0 && !room.controller.safeMode && plannedUnbuiltCount(room, index, STRUCTURE_TOWER) > 0 &&
                freeSlots(room) > 0) candidates.push({ structure, priority: 2, reason: 'tower-replace-safemode' });
            continue;
        }
        if (cappedReplaceable(room, index, type, allow)) candidates.push({ structure, priority: 2, reason: 'cap-replace' });
    }
    candidates.sort((a, b) => a.priority - b.priority || a.structure.id.localeCompare(b.structure.id));
    return candidates[0] || null;
}

/** 敌方遗留、正在占我们配额的结构：全房同类（不分主人，与引擎计数一致）已达配额、而我们自己的还没到。
 *  spawn 排最前（没有 spawn 的房只能靠外援维持），其余按 id 定序。 */
function hostileQuotaTarget(room) {
    const allow = layout.allowance(room);
    const total = {};
    const mine = {};
    const foreign = [];
    for (const structure of room.find(FIND_STRUCTURES)) {
        const key = typeKey(structure.structureType);
        if (!key) continue;
        total[key] = (total[key] || 0) + 1;
        if (structure.my === false) foreign.push(structure);
        else mine[key] = (mine[key] || 0) + 1;
    }
    // 引擎口径连工地一起数：我们的替代工地占着的名额也算"我们的"，多配额类型（extension）才能成批替换，而不是拆一个等建成再拆下一个
    for (const site of room.find(FIND_MY_CONSTRUCTION_SITES)) {
        const key = typeKey(site.structureType);
        if (!key) continue;
        total[key] = (total[key] || 0) + 1;
        mine[key] = (mine[key] || 0) + 1;
    }
    const spawnType = constant('STRUCTURE_SPAWN', 'spawn');
    const keepBelow = settings().keepStoredBelow || 0;
    const blocking = foreign.filter((structure) => {
        const key = typeKey(structure.structureType);
        const cap = allow[key] || 0;
        if (typeof structure.destroy !== 'function' || (total[key] || 0) < cap || (mine[key] || 0) >= cap) return false;
        // 存储型（storage/terminal/lab/factory/nuker/powerSpawn）里还有货就先不拆：没有 rampart 时可以直接取，拆成 ruin 500 tick 就烂掉。
        // spawn/extension/塔的零头能量不值得为它卡住配额
        const stored = structure.store && typeof structure.store.getUsedCapacity === 'function' ? structure.store.getUsedCapacity() : 0;
        const smallStore = key === 'spawn' || key === 'extension' || key === 'tower' || key === 'link';
        return smallStore || stored <= keepBelow;
    });
    blocking.sort((a, b) => (a.structureType === spawnType ? 0 : 1) - (b.structureType === spawnType ? 0 : 1) || a.id.localeCompare(b.id));
    return blocking[0] || null;
}

function run(room) {
    if (!room || !room.controller || !room.controller.my) return;
    const mem = Memory.rooms && Memory.rooms[room.name];
    if (!mem) return;
    const cfg = settings();
    if (!isRoomPhaseTick(room.name, cfg.interval)) return;
    const entries = mem.demolition || (mem.demolition = []);
    const log = (entry) => {
        entries.unshift(Object.assign({ t: Game.time }, entry));
        entries.length = Math.min(entries.length, cfg.logSize);
    };
    if (!room.find(FIND_HOSTILE_CREEPS).length) {
        try {
            const foreign = hostileQuotaTarget(room);
            if (foreign && foreign.destroy() === OK) {
                log({ type: foreign.structureType, x: foreign.pos.x, y: foreign.pos.y, reason: 'hostile-quota' });
                console.log('[demolition] ' + room.name + ' 拆除敌方遗留 ' + foreign.structureType + '@' + foreign.pos.x + ',' + foreign.pos.y + '（占满本房配额）');
                return;
            }
        } catch (error) {
            logErr('demolition hostile-quota ' + room.name, error);
        }
    }
    const plan = mem.plan;
    if (!plan || !plan.wheel) return;
    const hold = holdReason(room, mem, cfg);
    if (hold) return;
    let index;
    try {
        index = planIndex(plan);
        removeOffPlanSites(room, index, log);
        const target = pickTarget(room, index);
        if (!target) return;
        const ret = target.structure.destroy();
        if (ret === OK) {
            log({ type: target.structure.structureType, x: target.structure.pos.x, y: target.structure.pos.y, reason: target.reason });
            console.log('[demolition] ' + room.name + ' 拆除 ' + target.structure.structureType + '@' + target.structure.pos.x + ',' + target.structure.pos.y + ' (' + target.reason + ')');
        }
    } catch (error) {
        logErr('demolition ' + room.name, error);
    }
}

/** 方案外的 rampart：不维修（任其衰减）；盖在 spawn/塔/storage/terminal 上的不算方案外（与 utils.needsRepair 同一规则）。 */
function offPlanRampart(room, structure) {
    const mem = Memory.rooms && Memory.rooms[room.name];
    const plan = mem && mem.plan;
    if (!plan || !plan.wheel || !Array.isArray(plan.ramparts)) return false;
    if (rampartProtectsCore(room, structure.pos.x, structure.pos.y)) return false;
    return !plan.ramparts.some((pos) => pos.x === structure.pos.x && pos.y === structure.pos.y);
}

module.exports = { run, settings, planIndex, pickTarget, offPlanRampart };

modules.expansion:
'use strict';
/**
 * 扩张执行层：外部大脑在指令里给出 claim 目标，这里只负责把它变成孵化需求。
 *   claimer：[CLAIM, MOVE]，占下 controller 即退役；
 *   新房归我方后由轮子规划（layout.run → wheel_layout.generate）给出布局，spawn1 工地放在轮子的第一个 spawn 位；
 *   pioneer：builder 身体，去新房就地采能、建 spawn、升 controller，新房 spawn 建成后转为该房的 builder。
 * 指令里即便带了 spawnPos/plan 也不采用——布局唯一来源是轮子。
 * 没有指令、GCL 无余量、母房能量不足或正在恢复时不产生任何需求。
 * 大脑掉线一整天（config.expansion.autoClaimAfterMs）后退回 autoClaimTarget 的保守兜底，大脑一回来立刻让位。
 */
const config = require('config');
const brain = require('brain');
const retire = require('retire');
const movement = require('movement');
const { makeBody, roomDistance, creepsHomeRole, isRetiring, logErr } = require('utils');

function settings() {
    return Object.assign({ minCapacity: 650, minRcl: 3, pioneers: 2, pioneerBudget: 800,
        autoClaimAfterMs: 24 * 60 * 60 * 1000, autoClaimInterval: 1500, autoClaimRange: 2, autoClaimFreshFor: 20000 }, config.expansion || {});
}

function ownedRoomCount() {
    let n = 0;
    for (const room of Object.values(Game.rooms || {})) {
        if (room.controller && room.controller.my) n++;
    }
    return n;
}

function gclHeadroom() {
    const level = Game.gcl && Number(Game.gcl.level) || 0;
    return level - ownedRoomCount();
}

/** 已有己方房间还没建成 spawn：开荒未完成，同一时间只允许一个占领在途 */
function bootstrapInProgress(exceptRoom) {
    for (const room of Object.values(Game.rooms || {})) {
        if (!room.controller || !room.controller.my || room.name === exceptRoom) continue;
        if (!room.find(FIND_MY_SPAWNS).length) return room.name;
    }
    return null;
}

/** 别的母房已经在开荒这个房（指令或记忆）：不再重复接管——2026-09-06 线上 W33S8 按指令占 W31S8 后，
 *  W34S7/W35S7 各自"自愈"接管又各派 2 只 pioneer，一个新房挤了 7 只（W35S7 容量 900、4 跳远） */
function sponsoredByAnother(roomName, homeName) {
    for (const name in Memory.rooms || {}) {
        if (name === homeName) continue;
        const expansion = Memory.rooms[name] && Memory.rooms[name].expansion;
        if (expansion && expansion.target === roomName) return true;
    }
    return false;
}

/** 无人接管的孤儿房由离它最近、够格开荒（RCL/容量）的母房接管，同距离按房名；其余母房不凑 */
function closestSponsor(roomName) {
    const cfg = settings();
    let best = null;
    for (const room of Object.values(Game.rooms || {})) {
        if (!room.controller || !room.controller.my || room.name === roomName) continue;
        if (room.controller.level < cfg.minRcl || room.energyCapacityAvailable < cfg.minCapacity) continue;
        if (!room.find(FIND_MY_SPAWNS).length) continue;
        const distance = roomDistance(room.name, roomName);
        if (!best || distance < best.distance || (distance === best.distance && room.name < best.name)) best = { name: room.name, distance };
    }
    return best ? best.name : null;
}

/**
 * 这个房现在是不是某个母房正在采的外矿（记录启用）。
 * 自治兜底刻意**不**碰它们：外矿已经在产出，把它转成己方房要搭上 claimer + pioneer + 漫长的 RCL 爬升，
 * 期间还丢掉预定带来的 3000 档源容量——这是一笔要全账号视角才算得清的交易，该由外部大脑定价，
 * 不该由一个"大脑掉线了"的兜底盲目做。兜底只负责往**新地盘**长，不停摆就够了。
 * （overmind-absorb 私服 validation-We4zzV：没有这条闸时，兜底把 remote 场景正在采的 W50N49 直接占了，那条外矿记录当场消失）
 */
function isActiveRemote(roomName) {
    for (const name in Memory.rooms || {}) {
        const remotes = Memory.rooms[name] && Memory.rooms[name].remotes;
        const record = remotes && !Array.isArray(remotes) ? remotes[roomName] : null;
        if (record && record.enabled) return true;
    }
    return false;
}

/** 别的母房有开荒记录（Memory.rooms[*].expansion，不论来自指令还是兜底）：兜底一次只开一个房——
 *  大脑有全账号的 GCL/援建账，兜底没有，并行开荒的弱房会一起饿着 */
function expansionElsewhere(homeName) {
    for (const name in Memory.rooms || {}) {
        if (name === homeName) continue;
        const expansion = Memory.rooms[name] && Memory.rooms[name].expansion;
        if (expansion && expansion.target) return name;
    }
    return null;
}

/** 房间状态（normal/novice/respawn/closed）与母房不同就过不去（新手区/重生区的墙）；地图 API 不可用时放行 */
function sameRoomStatus(a, b) {
    const map = typeof Game !== 'undefined' && Game.map;
    if (!map || typeof map.getRoomStatus !== 'function') return true;
    const left = map.getRoomStatus(a);
    const right = map.getRoomStatus(b);
    return !left || !right || left.status === right.status;
}

/**
 * 兜底的候选门槛（比大脑 plan.usable_for_claim 更严）。cheap=true 是缓存期内的复核：只看会随时间变的情报/归属，
 * 不重算路线与母房资格（那两项每 autoClaimInterval 才在重扫时算一次）。named = 用户在锁里点名的房（不卡双源）。
 */
function autoClaimOk(home, roomName, named, cheap) {
    const cfg = settings();
    if (!roomName || roomName === home.name) return false;
    const info = Memory.map && Memory.map[roomName];
    if (!info || typeof info !== 'object' || info.unreachable) return false;
    if (!(info.at >= 0) || Game.time - info.at > cfg.autoClaimFreshFor) return false;   // 没有/太旧的情报不敢用
    if (!info.controllerId) return false;                                               // 高速路 / 无控制器房
    if (info.class === 'sk' || info.class === 'center' || info.class === 'highway') return false;
    if (info.owner || Number(info.level || 0) > 0) return false;   // 有主：那是攻占（conquest）的事，不是扩张
    if (Number(info.lairs || 0) > 0) return false;                 // SK 房
    if (!named && Number(info.sources || 0) < 2) return false;      // 单源房自治时不占（大脑可以，它有全局账）
    if (info.threat || Number(info.armedHostiles || 0) > 0 || info.invaderCore) return false;
    const me = home.controller && home.controller.owner && home.controller.owner.username;
    const reservation = info.reservation;
    if (reservation && reservation.username && reservation.username !== me && !reservation.mine) return false;   // 别人预定着：会打起来
    const visible = Game.rooms[roomName];
    if (visible && visible.controller && (visible.controller.my || visible.controller.owner)) return false;
    if (sponsoredByAnother(roomName, home.name)) return false;
    if (isActiveRemote(roomName)) return false;
    // 本母房去过、没到（arrivalState/noteStuck 记的失败）：兜底不重试，换下一个候选；到达会清掉记录
    const reach = homeMemory(home).claimReachability;
    if (reach && reach[roomName] && (Number(reach[roomName].failures) > 0 || reach[roomName].suspendedUntil > Game.time)) return false;
    if (cheap) return true;
    const distance = roomDistance(home.name, roomName);
    if (!(distance > 0) || distance > cfg.autoClaimRange) return false;
    if (closestSponsor(roomName) !== home.name) return false;   // 离它最近的够格母房来开（多个母房算出同一结论，不会互抢）
    if (!sameRoomStatus(home.name, roomName)) return false;
    // 不穿 SK/他人占领房也走得到：开荒后援建 creep 走默认避让，SK 环外的新房对它们就是孤岛（movement.safeRouteExists）
    try {
        if (!movement.safeRouteExists(home.name, roomName)) return false;
    } catch (error) {
        logErr('expansion.autoClaim route ' + roomName, error);
        return false;
    }
    return true;
}

/** 自治占领的 CPU 余量：bucket ≥ autoClaimMinBucket，且最近 autoClaimCpuSamples 条 Memory.stats 的 tick 用量均值 ≤ limit × autoClaimMaxCpuShare。
 *  还没有 stats（新号/刚上线）时只看 bucket */
function autoClaimCpu(cfg) {
    const bucket = Number(Game.cpu && Game.cpu.bucket);
    const minBucket = Math.max(0, Number(cfg.autoClaimMinBucket) || 0);
    const want = Math.max(1, Math.floor(Number(cfg.autoClaimCpuSamples) || 5));
    const stats = Array.isArray(Memory.stats) ? Memory.stats : [];
    const values = [];
    for (let i = stats.length - 1; i >= 0 && values.length < want; i--) {
        const used = stats[i] && Number(stats[i].cpu);
        if (Number.isFinite(used)) values.push(used);
    }
    const mean = values.length ? Math.round(values.reduce((a, b) => a + b, 0) / values.length * 10) / 10 : null;
    const share = Number(cfg.autoClaimMaxCpuShare);
    const line = Number.isFinite(share) && share > 0 ? Math.round((Number(Game.cpu && Game.cpu.limit) || 0) * share * 10) / 10 : Infinity;
    const ok = !(Number.isFinite(bucket) && bucket < minBucket) && !(mean != null && mean > line);
    return { ok, bucket: Number.isFinite(bucket) ? bucket : null, mean, line: Number.isFinite(line) ? line : null };
}

/**
 * 大脑掉线时的自治占领目标。只在 brain.offlineMs() ≥ autoClaimAfterMs（指令 ttl 到期后一整天）时才走这里；
 * 有可用指令（哪怕它这一轮没给本房 claim）或 Memory.brain 从没出现过都不会到这一步（见 claimTarget）。
 *
 * 候选来源，按大脑留下的意图优先：
 *   1. 最后一份指令里未到期的 <母房>.claim 锁：锁定的房（value.room），或锁定为 null = 这个母房不占；
 *   2. 未到期的账号级 claim.queue 锁（用户点名的占领清单，顺序即优先级）：只从清单里挑，不另起炉灶——GCL 是留给这些房的；
 *   3. 都没有：从 Memory.map 已有的侦察情报里挑，近的优先、同距离按房名。
 * 门槛见 autoClaimOk：双源（点名的房除外）、无主、无 keeper、无敌情、无他人预定、情报新鲜、不是在采的外矿、本房没去失败过、
 * 距离 ≤ autoClaimRange、本房是它最近的够格母房、不穿危险房也走得到。账号里别的母房有开荒在途时不挑。
 * 宁可不占也不占错：占错的代价是 claimer + 2 pioneer 的几千能量，外加一个长期拖后腿的弱房。
 * 结论缓存在 Memory.rooms[母房].autoClaim（room/from/at），每 autoClaimInterval tick 才重扫，缓存期内只复核已挑中的房。
 */
function autoClaimTarget(home) {
    const cfg = settings();
    if (!cfg.autoClaim) return null;
    const mem = homeMemory(home);
    const cache = mem.autoClaim;
    const interval = Math.max(100, Number(cfg.autoClaimInterval) || 1500);
    const fresh = !!cache && cache.at != null && Game.time >= cache.at && Game.time - cache.at < interval;
    if (fresh && cache.room) {
        if (autoClaimOk(home, cache.room, !!cache.named, true) && !expansionElsewhere(home.name)) return { room: cache.room, reason: 'autonomous' };
        // 缓存的目标不再合格（被占/被预定/去失败了…）：当场重扫，别带着坏目标等满一个间隔
    } else if (fresh) {
        return null;   // 上次也没挑出来，别每 tick 重扫
    }
    const note = (fields) => { mem.autoClaim = Object.assign({ at: Game.time, room: null }, fields); return null; };
    if (home.controller.level < cfg.minRcl || home.energyCapacityAvailable < cfg.minCapacity) return note({ why: 'home' });
    if (gclHeadroom() <= 0) return note({ why: 'gcl' });
    // CPU 闸：账号已经吃紧时不替掉线的大脑再加一个房（已在开荒的自治目标照常开完，见 config.expansion.autoClaimMinBucket）
    if (!(mem.expansion && mem.expansion.autonomous)) {
        const cpu = autoClaimCpu(cfg);
        if (!cpu.ok) {
            // 遥测（生效断言 expansion.autoClaimCpuGate）：mem.autoClaim 下一轮重扫会被覆盖，这里单独留一份
            const held = mem.autoClaimCpuHeld || (mem.autoClaimCpuHeld = { first: Game.time, n: 0 });
            held.n = (Number(held.n) || 0) + 1;
            Object.assign(held, { at: Game.time, bucket: cpu.bucket, mean: cpu.mean, line: cpu.line });
            return note({ why: 'cpu', bucket: cpu.bucket, mean: cpu.mean, line: cpu.line });
        }
    }
    // 账号里还有己方房没建成 spawn（不论谁在开荒、有没有人开）或别的母房有开荒记录：先把它开完，兜底一次只开一个房
    const busy = bootstrapInProgress(null) || expansionElsewhere(home.name);
    if (busy) return note({ why: 'busy:' + busy });
    let candidates;
    let from;
    const homeLock = brain.standingLock(home.name + '.claim');
    const queueLock = brain.standingLock('claim.queue');
    if (homeLock) {
        from = 'lock';
        const room = homeLock.value && typeof homeLock.value === 'object' ? homeLock.value.room : null;
        candidates = typeof room === 'string' ? [room] : [];
    } else if (queueLock && Array.isArray(queueLock.value)) {
        from = 'queue';
        candidates = queueLock.value.filter((room) => typeof room === 'string' && room);
    } else {
        from = 'map';
        candidates = Object.keys(Memory.map || {})
            .map((room) => ({ room, distance: roomDistance(home.name, room) }))
            .filter((entry) => entry.distance > 0 && entry.distance <= cfg.autoClaimRange)
            // 近的优先，同距离按房名（确定性：别的母房算出来的顺序一致，不会互抢）
            .sort((a, b) => a.distance - b.distance || (a.room < b.room ? -1 : a.room > b.room ? 1 : 0))
            .map((entry) => entry.room);
    }
    const named = from !== 'map';
    const room = candidates.find((name) => autoClaimOk(home, name, named, false)) || null;
    if (!room) return note({ from, why: 'none' });
    mem.autoClaim = { at: Game.time, room, from, named, distance: roomDistance(home.name, room) };
    // 遥测（生效断言 expansion.autoClaimOffline）：占下后缓存复核失败、重扫会记 busy:<目标> 覆盖 autoClaim，挑中的结论另留一份
    mem.autoClaimPicked = { room, from, at: Game.time, distance: mem.autoClaim.distance };
    return { room, reason: 'autonomous' };
}

function claimTarget(home) {
    const claim = brain.get(home.name, 'claim', null);
    if (claim && typeof claim === 'object' && typeof claim.room === 'string') {
        return claim.room === home.name ? null : claim;
    }
    // 有可用指令但这一轮没给本房 claim：那是大脑的决定，不自作主张；只有掉线够久才退回自治兜底
    const offline = brain.offlineMs();
    const cfg = settings();
    if (!cfg.autoClaim || offline == null || offline < Math.max(Number(cfg.autoClaimAfterMs) || 0, 1)) return null;
    const auto = autoClaimTarget(home);
    return auto && auto.room !== home.name ? auto : null;
}

/** 目标房轮子方案给出的 spawn1 位（还没规划时为 null） */
function wheelSpawnPos(roomName) {
    const plan = Memory.rooms && Memory.rooms[roomName] && Memory.rooms[roomName].plan;
    if (!plan || !plan.wheel || !Array.isArray(plan.spawns) || !plan.spawns[0]) return null;
    return { x: plan.spawns[0].x, y: plan.spawns[0].y };
}

function targetStatus(roomName) {
    const room = Game.rooms[roomName];
    if (!room) return { visible: false, mine: false, foreign: false, hasSpawn: false };
    const controller = room.controller;
    const mine = !!(controller && controller.my);
    const foreign = !!(controller && controller.owner && !controller.my);
    const hasSpawn = mine && room.find(FIND_MY_SPAWNS).length > 0;
    return { visible: true, mine, foreign, hasSpawn };
}

// 外矿 reserver 改任 claimer 时至少要有这么多寿命才够走到目标房（reserver 最长 600 tick）
const CLAIM_TRAVEL_LEAD = 100;

/** 母房已有带 CLAIM 部件、寿命够的 reserver 指向目标房（roles/reserver.js 会就地 claim）：不必再孵 claimer */
function claimCapableCreep(home, roomName) {
    for (const creep of creepsHomeRole(home.name, 'reserver')) {
        if (creep.spawning) continue;
        if (creep.memory.remoteRoom !== roomName) continue;
        if (!(creep.body || []).some((part) => part.type === CLAIM && part.hits !== 0)) continue;
        if (creep.ticksToLive != null && creep.ticksToLive <= CLAIM_TRAVEL_LEAD) continue;
        return creep;
    }
    return null;
}

/** bodyFor(budget)：预算不足满配时按预算缩身的身体（spawn 队列在宽限用完后调用）；不给则只能等满配 */
function demand(role, slot, body, memory, lead, priority, bodyFor) {
    return { role, slot, body, memory: Object.assign({ role, slotKey: slot }, memory), lead, priority, bodyFor };
}

function homeMemory(home) {
    Memory.rooms = Memory.rooms || {};
    Memory.rooms[home.name] = Memory.rooms[home.name] || {};
    return Memory.rooms[home.name];
}

/** 正在开荒的目标：优先指令里的 claim；指令撤掉后沿用母房记忆，直到新房建成 spawn */
function activeTarget(home) {
    const mem = homeMemory(home);
    const claim = claimTarget(home);
    // 没人管的孤儿房（己方、没 spawn、没有母房在开荒它）且本房是离它最近的够格母房：先把它开完，指令里的新目标往后排——
    // 以前是"有房在开荒就不接受第二个占领"，两个母房各开一房时互相封死（线上 W31S6/W31S8 的 pioneer 到寿命后再没补过）
    const orphan = bootstrapInProgress(home.name);
    const orphanIsMine = !!orphan && !sponsoredByAnother(orphan, home.name) && closestSponsor(orphan) === home.name;
    // 自治兜底挑的、还没占下的目标，兜底不再要它了（大脑回来了且没接着要这个房、或目标不再合格）：作废，在途 claimer/pioneer 退役——
    // 占哪个房是大脑的账，它在线时游戏内不替它多占一个
    if (mem.expansion && mem.expansion.autonomous && (!claim || claim.room !== mem.expansion.target) &&
        !targetStatus(mem.expansion.target).mine) {
        retireTravelers(home, mem.expansion.target);
        delete mem.expansion;
    }
    if (claim && claim.room !== home.name && !(orphanIsMine && orphan !== claim.room)) {
        // spawn 位只认目标房自己的轮子方案（归我方后才会生成）；指令里的 spawnPos/plan 一律忽略
        mem.expansion = { target: claim.room, spawnPos: wheelSpawnPos(claim.room),
            since: mem.expansion && mem.expansion.target === claim.room ? mem.expansion.since : Game.time };
        if (claim.reason === 'autonomous') mem.expansion.autonomous = true;
        return mem.expansion;
    }
    let remembered = mem.expansion;
    if (remembered && remembered.target === home.name) { delete mem.expansion; remembered = null; }
    if (!remembered || !remembered.target) {
        // 自愈：内存丢失/旧版本没记录时，接管任何己方还没 spawn 的房（spawnPos 取自它的 spawn 工地）
        const orphan = bootstrapInProgress(home.name);
        if (!orphan || sponsoredByAnother(orphan, home.name) || closestSponsor(orphan) !== home.name) return null;
        const site = Game.rooms[orphan].find(FIND_MY_CONSTRUCTION_SITES).find((s) => s.structureType === STRUCTURE_SPAWN);
        remembered = { target: orphan, spawnPos: site ? { x: site.pos.x, y: site.pos.y } : null, since: Game.time };
        mem.expansion = remembered;
    }
    const status = targetStatus(remembered.target);
    if (!status.mine || status.hasSpawn) {
        // 目标不再是我方（占领失败/被夺）或已建成 spawn：开荒结束
        delete mem.expansion;
        return null;
    }
    return remembered;
}

function stuckTicks() {
    return Math.max(1, Number((config.remote || {}).stuckTicks) || 60);
}

function liveTravelers(home, roomName, roles) {
    const want = roles || { claimer: true, pioneer: true, reserver: true };
    return Object.values(Game.creeps || {}).filter((c) => c.memory && c.memory.home === home.name &&
        (c.memory.targetRoom === roomName || c.memory.remoteRoom === roomName) &&
        want[c.memory.role] && !c.spawning && !isRetiring(c.memory));
}

function retireTravelers(home, roomName) {
    for (const creep of liveTravelers(home, roomName, { claimer: true, pioneer: true })) {
        creep.memory.retired = true;
        retire.retireAtSpawn(creep);
    }
}

function markUnreachable(home, roomName, reason) {
    const mem = homeMemory(home);
    const records = mem.claimReachability = mem.claimReachability || {};
    const cfg = settings();
    const record = records[roomName] = records[roomName] || { failures: 0 };
    if (!(record.suspendedUntil > Game.time)) {
        record.failures = Math.min((record.failures || 0) + 1, 20);
        record.suspendedUntil = Game.time + Math.min(cfg.unreachableMaxTicks, cfg.unreachableTicks * Math.pow(2, record.failures - 1));
        record.reason = reason || 'unreachable';
        delete record.startedAt;
    }
    retireTravelers(home, roomName);
    return record;
}

/** 去程连续 stuckTicks 格不动（墙封死、ERR_NO_PATH）：立刻记不可达并退役，不必等到 CLAIM 寿命耗尽。 */
function noteStuck(creep) {
    if (!creep || !creep.memory || !creep.pos) return false;
    const homeName = creep.memory.home;
    const roomName = creep.memory.targetRoom;
    if (!homeName || !roomName) return false;
    if (creep.room && creep.room.name === roomName) return false;
    if (isRetiring(creep.memory)) return false;
    const posKey = creep.pos.roomName + ':' + creep.pos.x + ':' + creep.pos.y;
    if (creep.memory._tp === posKey) creep.memory._ts = (creep.memory._ts || 0) + 1;
    else { creep.memory._tp = posKey; creep.memory._ts = 0; }
    if (creep.memory._ts < stuckTicks()) return false;
    creep.memory._ts = 0;
    const home = Game.rooms[homeName];
    if (!home) return false;
    markUnreachable(home, roomName, 'unreachable');
    return true;
}

/** 独立于每 tick 重建的 expansion；重复指令和切换目标不能抹掉失败历史。 */
function arrivalState(home, target) {
    const mem = homeMemory(home);
    const records = mem.claimReachability = mem.claimReachability || {};
    const roomName = target.target;
    const arrived = liveTravelers(home, roomName).some((c) => c.room && c.room.name === roomName);
    if (targetStatus(roomName).mine || arrived) {
        delete records[roomName];
        return { blocked: false, probing: false };
    }
    const cfg = settings();
    const record = records[roomName] = records[roomName] || { failures: 0 };
    if (record.suspendedUntil > Game.time) return { blocked: true, probing: true };
    // 只在确实孵出了 claimer 后计时，母房暂时没能量不能算不可达。退役中的不算在途。
    const traveler = liveTravelers(home, roomName, { claimer: true })[0];
    if (record.startedAt == null && traveler) record.startedAt = Game.time;
    if (record.startedAt != null && Game.time - record.startedAt >= cfg.arrivalTimeout) {
        markUnreachable(home, roomName, 'unreachable');
        return { blocked: true, probing: true };
    }
    return { blocked: false, probing: record.failures > 0 };
}

/** 母房为扩张要孵化的 creep 需求（与 remote.getDemands 同结构） */
function getDemands(home) {
    if (!home || !home.controller || !home.controller.my) return [];
    const cfg = settings();
    if (home.controller.level < cfg.minRcl || home.energyCapacityAvailable < cfg.minCapacity) return [];
    const target = activeTarget(home);
    if (!target) return [];
    const claim = { room: target.target, spawnPos: target.spawnPos };
    const status = targetStatus(claim.room);
    if (status.foreign) { delete homeMemory(home).expansion; return []; }
    if (!status.mine && gclHeadroom() <= 0) return [];
    if (status.hasSpawn) { delete homeMemory(home).expansion; return []; }
    // 不再因为"别的房也在开荒"就停手：每个母房只有一个开荒目标，多个母房并行开荒是允许的——
    // 2026-09-06 线上 W33S7 → W31S6 与 W33S8 → W31S8 同时开荒，这条门让两家互相封死，7 只 pioneer 到寿命后再没补过，spawn 工地停在 3240/12600
    const reachability = arrivalState(home, target);
    if (reachability.blocked) return [];
    const demands = [];
    let priority = 0;
    // memory.home 必须带上：spawn 的槽位计数按 home + slotKey 匹配，否则每攒够能量就再孵一只
    const memory = { home: home.name, targetRoom: claim.room, spawnPos: claim.spawnPos || null };
    if (!status.mine && !claimCapableCreep(home, claim.room)) {
        demands.push(demand('claimer', 'claimer:' + claim.room, ['claim', 'move'], memory, reachability.probing ? 0 : 100, priority++));
    }
    if (reachability.probing) return demands; // 冷却后只派 claimer，抵达后才恢复 pioneer
    const pioneerBody = makeBody('builder', Math.min(home.energyCapacityAvailable, cfg.pioneerBudget));
    for (let index = 0; index < cfg.pioneers; index++) {
        demands.push(demand('pioneer', 'pioneer:' + claim.room + ':' + index, pioneerBody, memory, 80, priority++,
            (budget) => makeBody('builder', Math.min(budget, cfg.pioneerBudget))));
    }
    return demands;
}

/** 每 tick 的开荒维护：目标房归我方且已有轮子方案后，确保 spawn1 工地在轮子给的位置上 */
function run(home) {
    if (!home || !home.controller || !home.controller.my) return;
    const target = activeTarget(home);
    if (!target || !target.target) return;
    // spawn 在 recovering / 全忙时不调 getDemands；已经派出的 claimer 仍要在这里计时，否则墙封死就无限续命。
    const reachability = arrivalState(home, target);
    if (reachability.blocked) retireTravelers(home, target.target);
    const room = Game.rooms[target.target];
    if (!room || !room.controller || !room.controller.my) return;
    if (room.find(FIND_MY_SPAWNS).length) return;
    const spawnPos = wheelSpawnPos(room.name) || target.spawnPos;
    if (!spawnPos) return;
    const hasSite = room.find(FIND_MY_CONSTRUCTION_SITES).some((site) => site.structureType === STRUCTURE_SPAWN);
    if (!hasSite) room.createConstructionSite(spawnPos.x, spawnPos.y, STRUCTURE_SPAWN);
}

module.exports = { run, getDemands, activeTarget, targetStatus, gclHeadroom, bootstrapInProgress, claimCapableCreep, settings, arrivalState, noteStuck, markUnreachable, autoClaimTarget, claimTarget };

modules.haul_stats:
'use strict';
/**
 * 运输饱和度遥测 v2（只观察、不改行为）：每只运输型 creep 每 tick 按"上一 tick 实际发生了什么"分类计数，
 * 按 母房 × 角色 累加，每 FLUSH_EVERY tick 并入 Memory.haulStats（累计值；A/B 与监控取两次读数的差分）。
 *
 * Screeps 的动作下一 tick 才结算，所以 tick T 开始时看到的位置/载货变化就是 T−1 那一 tick 的结果。
 * v1 计数（按净载货变化分类，保留以便与旧数据衔接）：
 *   idle / idleE / idleL / fat   没挪位且载货不变（空载 / 载货 / 其中被疲劳卡住）
 *   mvE / mvL / lf               挪了位、载货不变（空跑 / 载货行进，lf = Σ 载货率）
 *   ld / ul / ch                 载货增 / 减；同 tick 还挪了位的另记 ch
 *   in / out / cap / cu          装卸量；Σ 容量；所有挪位 tick 的 Σ 载货率
 *   dep / df                     出发（取货后第一个挪位 tick）次数与 Σ 出发装载率
 *   inS / outS / churn           从 storage 取 / 送回 storage / 取出又送回的量
 * v2 新增（净载货变化会把"同 tick 取 + 送"记成原地不动、把"在源旁涓流等货"记成取货，所以另按动作钩子与事件序列计）：
 *   ac / acm / ac0               有 OK 动作（transfer/withdraw/pickup）的 tick；其中同 tick 挪了位的；做了动作但载货没变的（被同 tick 抢先）
 *   ldT / ulT                    按动作钩子计的取货 / 投递 tick（同 tick 又取又送各记一次）
 *   tw / twE                     原地、没满、每 tick 增量不到容量 25% 的取货 tick（在源旁涓流等货）与其所得
 *   mvP / mvU                    空跑 tick 事后归类：下一个事件是连续 ≥ 3 tick 原地空闲 → 走去停车（mvP）；否则有效（mvU）
 *   abL / abE                    载货走了 ≥ 5 格下一个事件却是取货（半途换目标）/ 空载离开卸货点 ≥ 5 格又回到 2 格内、期间没取货（白跑）
 *   lgS / lgD / egS / egD        载货腿 / 空载腿的实际步数与起终点切比雪夫距离（绕路比 = S / D）
 *   dp8                          出发装载率 < 0.8 的次数
 *   idSt / idOv / idWa           空闲 tick 按母房当时的供给分：没货可取 / 全满 / 有货没人搬（最好的一处可取量 ≥ 半车且 spawn/ext/塔有缺口）
 *   lostAge / lostAgeOut / lostN 老死（最后一次看到时寿命将尽）时身上的能量、其中死在己方房外的、次数
 * 房级 _room：ticks；rfN / rfT / rfD（spawn+ext 从 < 90% 补到 ≥ 90% 的次数、耗时、缺口积分）；lkF / lsF（ctrl link / 任一源 link ≥ 780 的 tick）；spW（spawn 在等能量的 tick）
 * 外矿线 _lines[外矿房]（remoteHauler）：t idle tw ac acm dep df out cap lostAge
 * rs / ri：角色代码登记的原因（note）的 tick 数 / 其中 idle 的 tick 数（两版角色代码登记的原因不同，A/B 不直接比）。
 * 只统计连续两 tick 都观察到的样本（CPU 跳过、退役、刚孵出的那一 tick 不算）。
 */

const VERSION = 2;
const CARRIER_ROLES = { hauler: true, remoteHauler: true, feeder: true, courier: true, operator: true };
const FLUSH_EVERY = 30;
const COUNTERS = ['t', 'cap', 'idle', 'idleE', 'idleL', 'fat', 'mvE', 'mvL', 'lf', 'ld', 'ul', 'ch', 'in', 'out',
    'cu', 'dep', 'df', 'inS', 'outS', 'churn',
    'ac', 'acm', 'ac0', 'ldT', 'ulT', 'tw', 'twE', 'mvP', 'mvU', 'abL', 'abE', 'lgS', 'lgD', 'egS', 'egD', 'dp8',
    'idSt', 'idOv', 'idWa', 'lostAge', 'lostAgeOut', 'lostN'];
const ROOM_COUNTERS = ['ticks', 'rfN', 'rfT', 'rfD', 'lkF', 'lsF', 'spW'];
const LINE_COUNTERS = ['t', 'idle', 'tw', 'ac', 'acm', 'dep', 'df', 'out', 'cap', 'lostAge'];
const ROUNDED = { lf: true, cu: true, df: true };
const ACT = { transfer: 1, withdraw: 2, pickup: 4 };

const runtimeGlobal = typeof global !== 'undefined' ? global : {};
const runtime = runtimeGlobal.__haulStatsRuntime || (runtimeGlobal.__haulStatsRuntime = { last: {}, acc: {}, gcAt: 0 });
runtime.rooms = runtime.rooms || {};      // 房级累计（本窗口）
runtime.roomState = runtime.roomState || {};   // 房级跨 tick 状态（补能期）
runtime.lines = runtime.lines || {};
runtime.supply = runtime.supply || { tick: -1, rooms: {} };

function isCarrier(creep) {
    return !!(creep && creep.memory && CARRIER_ROLES[creep.memory.role]);
}

function usedOf(store) {
    if (!store) return 0;
    if (typeof store.getUsedCapacity === 'function') {
        const used = Number(store.getUsedCapacity());
        if (Number.isFinite(used)) return used;
    }
    let sum = 0;
    for (const key of Object.keys(store)) if (typeof store[key] === 'number') sum += store[key];
    return sum;
}

function capacityOf(creep) {
    const store = creep.store;
    if (store && typeof store.getCapacity === 'function') {
        const cap = Number(store.getCapacity());
        if (Number.isFinite(cap) && cap > 0) return cap;
    }
    const carry = typeof creep.getActiveBodyparts === 'function' ? creep.getActiveBodyparts(typeof CARRY === 'undefined' ? 'carry' : CARRY)
        : (creep.body || []).filter((part) => (part.type || part) === 'carry' && part.hits !== 0).length;
    return carry * 50;
}

function zeroed(keys) {
    const out = {};
    for (const key of keys) out[key] = 0;
    return out;
}

function bucketFor(home, role) {
    const room = runtime.acc[home] || (runtime.acc[home] = {});
    let bucket = room[role];
    if (!bucket) bucket = room[role] = Object.assign(zeroed(COUNTERS), { rs: {}, ri: {} });
    return bucket;
}

function lineFor(home, remoteRoom) {
    const lines = runtime.lines[home] || (runtime.lines[home] = {});
    return lines[remoteRoom] || (lines[remoteRoom] = zeroed(LINE_COUNTERS));
}

function storageType() {
    return typeof STRUCTURE_STORAGE === 'undefined' ? 'storage' : STRUCTURE_STORAGE;
}

function cheb(ax, ay, bx, by) {
    return Math.max(Math.abs(ax - bx), Math.abs(ay - by));
}

/** 目标分类：storage 单独计（倒腾检测），其余只区分建筑类型/掉落/creep */
function targetKind(target) {
    if (!target) return null;
    if (target.structureType) return target.structureType;
    if (target.resourceType != null && target.amount != null) return 'drop';
    if (target.deathTime != null || target.ticksToDecay != null) return 'tomb';
    if (target.body) return 'creep';
    return 'other';
}

/** 取送动作登记（本 tick 的状态上）：observe 在下一 tick 按载货变化把量记到 storage 进/出上，并记动作位掩码 */
function noteAction(creep, kind, target) {
    const state = creep && runtime.last[creep.name];
    if (!state || typeof Game === 'undefined' || state.t !== Game.time) return;
    const type = targetKind(target);
    if (kind === 'transfer') state.to = type;
    else state.from = type;
    state.act |= ACT[kind] || 0;
}

/** 房间当时的供给与缺口（每房每 tick 一次）：最好的一处可取量（源容器 / 源旁掉落 / storage 高于升级者底线的部分）、spawn+ext+塔的缺口 */
function roomSupply(room) {
    if (runtime.supply.tick !== Game.time) { runtime.supply.tick = Game.time; runtime.supply.rooms = {}; }
    const cached = runtime.supply.rooms[room.name];
    if (cached) return cached;
    const energyKey = typeof RESOURCE_ENERGY === 'undefined' ? 'energy' : RESOURCE_ENERGY;
    const findStructures = typeof FIND_STRUCTURES === 'undefined' ? 'structures' : FIND_STRUCTURES;
    const structures = typeof room.find === 'function' ? room.find(findStructures) || [] : [];
    const sources = typeof room.find === 'function' ? room.find(typeof FIND_SOURCES === 'undefined' ? 'sources' : FIND_SOURCES) || [] : [];
    const drops = typeof room.find === 'function' ? room.find(typeof FIND_DROPPED_RESOURCES === 'undefined' ? 'droppedResources' : FIND_DROPPED_RESOURCES) || [] : [];
    const nearSource = (pos) => pos && sources.some((source) => source.pos && cheb(source.pos.x, source.pos.y, pos.x, pos.y) <= 2);
    let supply = 0;
    let towerGap = 0;
    for (const s of structures) {
        const type = s.structureType;
        if (type === (typeof STRUCTURE_CONTAINER === 'undefined' ? 'container' : STRUCTURE_CONTAINER) && s.store && nearSource(s.pos)) {
            supply = Math.max(supply, Number(s.store[energyKey]) || 0);
        } else if (type === (typeof STRUCTURE_TOWER === 'undefined' ? 'tower' : STRUCTURE_TOWER) && s.my !== false && s.store &&
            typeof s.store.getFreeCapacity === 'function') {
            const free = Number(s.store.getFreeCapacity(energyKey)) || 0;
            if (free >= 300) towerGap += free;
        }
    }
    for (const drop of drops) if (drop.resourceType === energyKey && nearSource(drop.pos)) supply = Math.max(supply, Number(drop.amount) || 0);
    if (room.storage && room.storage.my !== false && room.storage.store) supply = Math.max(supply, (Number(room.storage.store[energyKey]) || 0) - 2000);
    const deficit = Math.max(0, (Number(room.energyCapacityAvailable) || 0) - (Number(room.energyAvailable) || 0)) + towerGap;
    const out = { supply, deficit };
    runtime.supply.rooms[room.name] = out;
    return out;
}

function linkEnergyAt(room, spot) {
    if (!spot || typeof room.lookForAt !== 'function') return null;
    const look = typeof LOOK_STRUCTURES === 'undefined' ? 'structure' : LOOK_STRUCTURES;
    const link = (room.lookForAt(look, spot.x, spot.y) || []).find((s) => s.structureType === (typeof STRUCTURE_LINK === 'undefined' ? 'link' : STRUCTURE_LINK));
    return link && link.store ? Number(link.store[typeof RESOURCE_ENERGY === 'undefined' ? 'energy' : RESOURCE_ENERGY]) || 0 : null;
}

/** 房级（每个有运输 creep 的母房每 tick 一次）：spawn+ext 补能期、link 满着的 tick、spawn 在等能量的 tick */
function roomTick(room) {
    const acc = runtime.rooms[room.name] || (runtime.rooms[room.name] = zeroed(ROOM_COUNTERS));
    const st = runtime.roomState[room.name] || (runtime.roomState[room.name] = { seen: -1, start: null, deficit: 0 });
    if (st.seen === Game.time) return;
    st.seen = Game.time;
    acc.ticks++;
    const capacity = Number(room.energyCapacityAvailable) || 0;
    const available = Number(room.energyAvailable) || 0;
    if (capacity > 0 && available < capacity * 0.9) {
        if (st.start == null) { st.start = Game.time; st.deficit = 0; }
        st.deficit += capacity - available;
    } else if (st.start != null) {
        acc.rfN++;
        acc.rfT += Game.time - st.start;
        acc.rfD += st.deficit;
        st.start = null;
        st.deficit = 0;
    }
    const mem = typeof Memory !== 'undefined' && Memory.rooms && Memory.rooms[room.name];
    const plan = mem && mem.plan;
    const linkSpots = plan && plan.links;
    if (linkSpots) {
        const ctrl = linkEnergyAt(room, linkSpots.ctrl);
        if (ctrl != null && ctrl >= 780) acc.lkF++;
        if (['src0', 'src1', 'src'].some((key) => { const e = linkEnergyAt(room, linkSpots[key]); return e != null && e >= 780; })) acc.lsF++;
    }
    const waiting = mem && mem.spawnWaiting;
    if (waiting && waiting.cost > 0 && Game.time - Number(waiting.at || 0) <= 5 && available < waiting.cost) acc.spW++;
}

/** 每只 creep 每 tick 在角色代码执行前调用一次：记下本 tick 开始时的状态，并给上一 tick 的活动分类 */
function observe(creep) {
    if (!isCarrier(creep) || creep.spawning || !creep.pos) return;
    const now = typeof Game !== 'undefined' ? Game.time : 0;
    const used = usedOf(creep.store);
    const prev = runtime.last[creep.name];
    const consecutive = !!prev && prev.t === now - 1 && prev.cap > 0;
    const home = (creep.memory && creep.memory.home) || creep.pos.roomName || '?';
    const role = creep.memory.role;
    const state = {
        t: now, x: creep.pos.x, y: creep.pos.y, r: creep.pos.roomName, e: used,
        cap: capacityOf(creep), fat: Number(creep.fatigue) || 0, why: null, to: null, from: null, act: 0,
        ttl: creep.ticksToLive == null ? null : Number(creep.ticksToLive), home, role,
        remote: role === 'remoteHauler' ? creep.memory.remoteRoom || null : null,
        // 货物来源（storage / other）跟着货走：空了就清
        src: used > 0 && prev ? prev.src || null : null, cls: null,
        tr: prev && prev.tr ? prev.tr : { run: 0, park: 0, idle: 0, leg: null, eleg: null },
    };
    runtime.last[creep.name] = state;
    const homeRoom = typeof Game !== 'undefined' && Game.rooms ? Game.rooms[home] : null;
    if (homeRoom) roomTick(homeRoom);
    if (!consecutive) { state.tr = { run: 0, park: 0, idle: 0, leg: null, eleg: null }; return; }
    const bucket = bucketFor(home, role);
    const line = state.remote ? lineFor(home, state.remote) : null;
    const tr = state.tr;
    const moved = prev.x !== state.x || prev.y !== state.y || prev.r !== state.r;
    const delta = used - prev.e;
    const fill = Math.min(1, prev.e / prev.cap);
    bucket.t++;
    bucket.cap += prev.cap;
    if (line) { line.t++; line.cap += prev.cap; }
    let idle = false;
    let cls;
    if (delta > 0) {
        cls = 'ld';
        bucket.ld++;
        bucket.in += delta;
        if (moved) bucket.ch++;
        const fromStorage = prev.from === storageType();
        if (fromStorage) bucket.inS += delta;
        // 混装：只要装过 storage 的货就按 storage 算（倒腾检测宁可多算）
        state.src = fromStorage || prev.src === 'storage' ? 'storage' : 'other';
        if (!moved && delta < prev.cap * 0.25 && used < prev.cap) {
            bucket.tw++;
            bucket.twE += delta;
            if (line) line.tw++;
        }
    } else if (delta < 0) {
        cls = 'ul';
        bucket.ul++;
        bucket.out -= delta;
        if (line) line.out -= delta;
        if (moved) bucket.ch++;
        if (prev.to === storageType()) {
            bucket.outS -= delta;
            if (prev.src === 'storage') bucket.churn -= delta;
        }
    } else if (moved) {
        cls = prev.e > 0 ? 'mvL' : 'mvE';
        if (prev.e > 0) { bucket.mvL++; bucket.lf += fill; } else bucket.mvE++;
    } else {
        cls = 'idle';
        idle = true;
        bucket.idle++;
        if (line) line.idle++;
        if (prev.e > 0) bucket.idleL++; else bucket.idleE++;
        if (prev.fat > 0) bucket.fat++;
        if (homeRoom) {
            const supply = roomSupply(homeRoom);
            if (supply.deficit <= 0) bucket.idOv++;
            else if (supply.supply >= prev.cap * 0.5) bucket.idWa++;
            else bucket.idSt++;
        }
    }
    // 动作钩子：有 OK 动作的 tick、其中同 tick 挪位的、做了却没变化的；取/送 tick 各自计
    const act = prev.act || 0;
    if (act) {
        bucket.ac++;
        if (line) line.ac++;
        if (moved) { bucket.acm++; if (line) line.acm++; }
        if (delta === 0) bucket.ac0++;
        if (act & (ACT.withdraw | ACT.pickup)) bucket.ldT++;
        if (act & ACT.transfer) bucket.ulT++;
    }
    if (moved) {
        bucket.cu += fill;
        // 出发：取货之后第一个挪了位的 tick（连续取货只算最后一次之后的出发）
        if (prev.cls === 'ld' && cls !== 'ld') {
            bucket.dep++;
            bucket.df += fill;
            if (fill < 0.8) bucket.dp8++;
            if (line) { line.dep++; line.df += fill; }
            tr.leg = { x: prev.x, y: prev.y, r: prev.r, steps: 0 };
        }
    }
    // 载货腿：出发 → 下一次投递（步数 vs 起终点距离）；半途又去取货且已走 ≥ 5 格 = 换了目标
    if (tr.leg) {
        if (moved && prev.e > 0) tr.leg.steps++;
        if (cls === 'ul' || (act & ACT.transfer)) {
            if (tr.leg.r === prev.r) { bucket.lgS += tr.leg.steps; bucket.lgD += cheb(tr.leg.x, tr.leg.y, prev.x, prev.y); }
            tr.leg = null;
        } else if (cls === 'ld' && tr.leg.steps >= 5) {
            bucket.abL++;
            tr.leg = null;
        }
    }
    // 空载腿：投空 → 下一次取货；空载走出 ≥ 5 格又回到起点 2 格内、期间没取货 = 白跑
    if (cls === 'ul' && used === 0) tr.eleg = { x: prev.x, y: prev.y, r: prev.r, steps: 0, far: 0 };
    else if (tr.eleg) {
        if (cls === 'mvE') {
            tr.eleg.steps++;
            if (state.r === tr.eleg.r) {
                const d = cheb(tr.eleg.x, tr.eleg.y, state.x, state.y);
                if (d > tr.eleg.far) tr.eleg.far = d;
                if (tr.eleg.far >= 5 && d <= 2) { bucket.abE++; tr.eleg = null; }
            } else tr.eleg.far = Math.max(tr.eleg.far, 50);
        } else if (cls === 'ld') {
            if (tr.eleg.r === prev.r) { bucket.egS += tr.eleg.steps; bucket.egD += cheb(tr.eleg.x, tr.eleg.y, prev.x, prev.y); }
            tr.eleg = null;
        }
    }
    // 空跑事后归类：一段空跑之后连续原地 ≥ 3 tick = 走去停车；接着取货 / 别的事 = 有效
    if (cls === 'mvE') {
        tr.run++;
        tr.idle = 0;
    } else if (idle && prev.e === 0) {
        if (tr.run > 0) { tr.park += tr.run; tr.run = 0; }
        tr.idle++;
        if (tr.idle >= 3 && tr.park > 0) { bucket.mvP += tr.park; tr.park = 0; }
    } else {
        if (tr.run + tr.park > 0) bucket.mvU += tr.run + tr.park;
        tr.run = 0;
        tr.park = 0;
        tr.idle = 0;
    }
    state.cls = cls;
    if (prev.why) {
        bucket.rs[prev.why] = (bucket.rs[prev.why] || 0) + 1;
        if (idle) bucket.ri[prev.why] = (bucket.ri[prev.why] || 0) + 1;
    }
}

/** 角色代码登记本 tick 的"为什么没在干活"（park / full / wait / retreat…）；observe 在下一 tick 把它记到分类上 */
function note(creep, why) {
    const state = creep && runtime.last[creep.name];
    if (state && typeof Game !== 'undefined' && state.t === Game.time && !state.why) state.why = why;
}

function mergeInto(target, source, keys) {
    for (const key of keys) target[key] = (Number(target[key]) || 0) + (Number(source[key]) || 0);
    for (const field of ['rs', 'ri']) {
        if (!source[field]) continue;
        const into = target[field] || (target[field] = {});
        for (const [key, value] of Object.entries(source[field] || {})) into[key] = (into[key] || 0) + value;
    }
    for (const key of Object.keys(ROUNDED)) if (key in target) target[key] = Math.round(target[key] * 100) / 100;
}

function ownedRoom(name) {
    const room = typeof Game !== 'undefined' && Game.rooms ? Game.rooms[name] : null;
    return !!(room && room.controller && room.controller.my);
}

/** 老死带货：上次看到时寿命已尽（≤ 离上次观察的 tick 数 + 1）且身上有货的死亡 creep */
function settleDeaths() {
    for (const name of Object.keys(runtime.last)) {
        if (Game.creeps && Game.creeps[name]) continue;
        const last = runtime.last[name];
        delete runtime.last[name];
        if (!last || !(last.e > 0) || last.ttl == null) continue;
        if (last.ttl > Game.time - last.t + 1) continue;   // 还有寿命却消失了：回收 / 战死，不算老死
        const bucket = bucketFor(last.home || last.r || '?', last.role || '?');
        bucket.lostAge += last.e;
        bucket.lostN++;
        if (!ownedRoom(last.r)) bucket.lostAgeOut += last.e;
        if (last.remote) lineFor(last.home || '?', last.remote).lostAge += last.e;
    }
}

function flush() {
    if (typeof Game === 'undefined' || typeof Memory === 'undefined') return;
    if (Game.time % FLUSH_EVERY !== 0) return;
    settleDeaths();
    const stats = Memory.haulStats && Memory.haulStats.v === VERSION ? Memory.haulStats : (Memory.haulStats = { v: VERSION, since: Game.time, rooms: {} });
    const window = {};
    for (const [home, roles] of Object.entries(runtime.acc)) {
        const room = stats.rooms[home] || (stats.rooms[home] = {});
        for (const [role, bucket] of Object.entries(roles)) {
            if (!bucket.t && !bucket.lostN) continue;
            mergeInto(room[role] || (room[role] = {}), bucket, COUNTERS);
            (window[home] || (window[home] = {}))[role] = { t: bucket.t, idle: bucket.idle, cap: bucket.cap, out: bucket.out };
        }
    }
    for (const [home, acc] of Object.entries(runtime.rooms)) {
        if (!acc.ticks) continue;
        const room = stats.rooms[home] || (stats.rooms[home] = {});
        mergeInto(room._room || (room._room = {}), acc, ROOM_COUNTERS);
    }
    for (const [home, lines] of Object.entries(runtime.lines)) {
        const room = stats.rooms[home] || (stats.rooms[home] = {});
        const into = room._lines || (room._lines = {});
        for (const [remoteRoom, line] of Object.entries(lines)) {
            if (!line.t && !line.lostAge) continue;
            mergeInto(into[remoteRoom] || (into[remoteRoom] = {}), line, LINE_COUNTERS);
        }
    }
    stats.t = Game.time;
    stats.last = window;
    runtime.acc = {};
    runtime.rooms = {};
    runtime.lines = {};
}

/** 只记录的原型包装：运输型 creep 的 transfer/withdraw/pickup 返回 OK 时登记目标类型与动作位（每个全局只装一次，原样返回） */
function installActionHooks() {
    if (typeof Creep === 'undefined' || !Creep.prototype) return;
    const okCode = typeof OK === 'undefined' ? 0 : OK;
    for (const kind of ['transfer', 'withdraw', 'pickup']) {
        const flag = '__haulStatsHook_' + kind;
        const original = Creep.prototype[kind];
        if (typeof original !== 'function' || original[flag]) continue;
        const hooked = function (target, ...rest) {
            const result = original.call(this, target, ...rest);
            if (result === okCode && isCarrier(this)) {
                try { noteAction(this, kind, target); } catch (error) { /* 遥测不影响动作 */ }
            }
            return result;
        };
        hooked[flag] = true;
        Creep.prototype[kind] = hooked;
    }
}
installActionHooks();

module.exports = { observe, note, noteAction, flush, isCarrier, installActionHooks, CARRIER_ROLES, COUNTERS, ROOM_COUNTERS, LINE_COUNTERS, VERSION, _runtime: runtime };

modules.industry:
'use strict';
/** 保守后期服务：只在明确配置且储备充足时运行实验室/工厂/Power Spawn，绝不自动交易或发起攻击性行为。 */
const config = require('config');

const DEFAULTS = {
    storageReserve: 200000,
    terminalReserve: 50000,
    powerStorageReserve: 300000,
    statusKey: 'industryState',
};

function roomMem(room) {
    if (!Memory.rooms) Memory.rooms = {};
    if (!Memory.rooms[room.name]) Memory.rooms[room.name] = {};
    return Memory.rooms[room.name];
}

function industryConfig() {
    return (config && config.industry) || {};
}

function reserve(name) {
    const cfg = industryConfig();
    if (typeof cfg[name] === 'number') return cfg[name];
    return DEFAULTS[name];
}

function used(store, resource) {
    if (!store) return 0;
    if (typeof store.getUsedCapacity === 'function') {
        const value = store.getUsedCapacity(resource);
        if (typeof value === 'number') return value;
    }
    return store[resource] || 0;
}

function free(store, resource) {
    if (!store || typeof store.getFreeCapacity !== 'function') return 0;
    const value = store.getFreeCapacity(resource);
    return typeof value === 'number' ? value : 0;
}

function countMy(room, type) {
    return room.find(FIND_MY_STRUCTURES, { filter: (s) => s.structureType === type }).length;
}

function myStructures(room, type) {
    return room.find(FIND_MY_STRUCTURES, { filter: (s) => s.structureType === type });
}

function getById(id) {
    if (!id || !Game.getObjectById) return null;
    return Game.getObjectById(id) || null;
}

function normalizeObserve(cfg) {
    if (!cfg) return null;
    if (typeof cfg === 'string') return [cfg];
    if (Array.isArray(cfg)) return cfg.filter((x) => typeof x === 'string' && x);
    if (typeof cfg.roomName === 'string') return [cfg.roomName];
    if (Array.isArray(cfg.rooms)) return cfg.rooms.filter((x) => typeof x === 'string' && x);
    return null;
}

function normalizeReaction(cfg) {
    if (!cfg || typeof cfg !== 'object') return null;
    const inputs = Array.isArray(cfg.inputs) ? cfg.inputs : Array.isArray(cfg.sourceLabs) ? cfg.sourceLabs : null;
    const outputs = Array.isArray(cfg.outputs) ? cfg.outputs : Array.isArray(cfg.outputLabs) ? cfg.outputLabs : null;
    if (!inputs || inputs.length < 2 || !outputs || !outputs.length) return null;
    return {
        inputs: inputs.slice(0, 2),
        outputs: outputs.filter(Boolean),
    };
}

function normalizeProduct(cfg) {
    if (!cfg) return null;
    if (typeof cfg === 'string') return { resource: cfg };
    if (typeof cfg !== 'object') return null;
    if (typeof cfg.resource !== 'string' || !cfg.resource) return null;
    return {
        resource: cfg.resource,
        factoryId: cfg.factoryId || cfg.id || null,
    };
}

function storageEnergy(room) {
    return room.storage ? used(room.storage.store, RESOURCE_ENERGY) : 0;
}

function terminalEnergy(room) {
    return room.terminal ? used(room.terminal.store, RESOURCE_ENERGY) : 0;
}

function canSpend(room) {
    const storageOk = storageEnergy(room) >= reserve('storageReserve');
    const terminal = room.terminal;
    const terminalOk = !!terminal && terminalEnergy(room) >= reserve('terminalReserve');
    return storageOk && terminalOk;
}

function canProcessPower(room) {
    return canSpend(room) && storageEnergy(room) >= reserve('powerStorageReserve');
}

function runObserver(room, mem, state) {
    const observer = myStructures(room, STRUCTURE_OBSERVER)[0];
    const targets = normalizeObserve(mem.industry && (mem.industry.observe || mem.industry.observer));
    state.observer = {
        present: !!observer,
        configured: !!(targets && targets.length),
    };
    if (!observer || !targets || !targets.length || typeof observer.observeRoom !== 'function') return;
    const idx = (mem._industryObserveIdx || 0) % targets.length;
    const target = targets[idx];
    const ret = observer.observeRoom(target);
    state.observer.target = target;
    state.observer.result = ret;
    if (ret === OK) mem._industryObserveIdx = (idx + 1) % targets.length;
}

/** lab 里装着的那种矿物（Store 里唯一的非能量资源）；空的返回 null */
function labMineral(lab) {
    const store = lab && lab.store;
    if (!store) return null;
    for (const key of Object.keys(store)) {
        if (key === RESOURCE_ENERGY) continue;
        if (typeof store[key] === 'number' && store[key] > 0) return key;
    }
    return null;
}

function chebyshev(a, b) {
    return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
}

/** 按几何关系推导 lab 分工：两个装着不同矿物的输入 lab + 一个与它们**都**在切比雪夫 2 以内的输出 lab
 *  （引擎 processor/intents/labs/run-reaction.js 的硬条件：|dx| > 2 || |dy| > 2 直接拒绝），
 *  且 REACTIONS 里这对矿物有产物。输出 lab 里若已装着别的矿物则不能收，跳过。
 *  没有这条推导时 runLabs 需要人手把三个 lab 的 id 填进 Memory —— 于是 labs 建好了也永远不反应。 */
function deriveReaction(labs) {
    if (typeof REACTIONS === 'undefined' || !REACTIONS) return null;
    const loaded = labs.filter((lab) => labMineral(lab));
    for (const a of loaded) {
        const typeA = labMineral(a);
        for (const b of loaded) {
            if (b === a) continue;
            const typeB = labMineral(b);
            if (!typeB || typeB === typeA) continue;
            const product = REACTIONS[typeA] && REACTIONS[typeA][typeB];
            if (!product) continue;
            for (const out of labs) {
                if (out === a || out === b) continue;
                if (chebyshev(out.pos, a.pos) > 2 || chebyshev(out.pos, b.pos) > 2) continue;
                const outType = labMineral(out);
                if (outType && outType !== product) continue;
                return { inputs: [a.id, b.id], outputs: [out.id], product };
            }
        }
    }
    return null;
}

// ---- 矿物链（移植 overmind-absorb 7f4ab27 / 2d97ab4，重建在当前 main 上）----
// 链条原本断在这一环：矿物（brain 的 mineral 计划挖进 terminal/storage、hauler 打捞进 terminal）躺在库里，
// industry 认得出 lab 分工，但没有任何角色往 lab 里装货——deriveReaction 要求矿物已经在 lab 里，于是 labs 永远不反应。
// 这里给出「哪个 lab 装什么、产物从哪收回」（labPlan），roles/labTech 照着搬；反应选择按目标 boost 化合物自底向上找
// 「现在就做得起的那一步」（Overmind 的 Abathur），做不了才退回库存里能配的一对。
const BASE_MINERALS = ['H', 'O', 'Z', 'K', 'U', 'L', 'X'];

function num(value, fallback) {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
}

function labSettings() {
    const cfg = industryConfig();
    return {
        minBatch: Math.max(1, num(cfg.labMinBatch, 500)),
        fill: Math.max(1, num(cfg.labFill, 1000)),
        boostTargets: Array.isArray(cfg.boostTargets) ? cfg.boostTargets : [],
        boostGoal: Math.max(1, num(cfg.boostGoal, 3000)),
        boostStock: Math.max(1, num(cfg.labBoostStock, 1000)),
    };
}

function addStock(out, store) {
    if (!store) return;
    for (const key of Object.keys(store)) {
        if (key === RESOURCE_ENERGY) continue;
        const amount = store[key];
        if (typeof amount === 'number' && amount > 0) out[key] = (out[key] || 0) + amount;
    }
}

/** 房里可用的矿物库存（己方 terminal + storage，不含能量） */
function mineralStock(room) {
    const out = {};
    for (const holder of [room.terminal, room.storage]) {
        if (holder && holder.my !== false) addStock(out, holder.store);
    }
    return out;
}

function byId(a, b) {
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/** 几何上可用的 lab 三连：输出 lab 与两个输入都在切比雪夫 2 以内（引擎 run-reaction.js 的硬条件）；按 id 排序，选择稳定 */
function labTriple(labs) {
    const sorted = labs.slice().sort(byId);
    for (const out of sorted) {
        const near = sorted.filter((lab) => lab !== out && chebyshev(out.pos, lab.pos) <= 2);
        if (near.length >= 2) return { inputs: [near[0].id, near[1].id], outputs: [out.id] };
    }
    return null;
}

/** 产物 → [输入 A, 输入 B]；REACTIONS 是常量表，进程内算一次（认表本身：单测会换掉 global.REACTIONS） */
let reverseCache = null;
let reverseCacheFor = null;
function reverseReactions() {
    if (typeof REACTIONS === 'undefined' || !REACTIONS) return {};
    if (reverseCache && reverseCacheFor === REACTIONS) return reverseCache;
    const out = {};
    for (const a of Object.keys(REACTIONS)) {
        for (const b of Object.keys(REACTIONS[a] || {})) {
            const product = REACTIONS[a][b];
            if (!product || out[product]) continue;
            out[product] = a <= b ? [a, b] : [b, a];   // 定序，选择才稳定
        }
    }
    reverseCache = out;
    reverseCacheFor = REACTIONS;
    return out;
}

/**
 * 为了做出 target，现在这一步该反应什么：自顶向下拆，某个输入库存不够就先去做那个输入；
 * 拆到基础矿还不够就这一支做不了（那是矿脉/终端调剂的事）。返回 {a, b, product}，product 多半是链条上更靠下的中间体。
 */
function nextReactionFor(target, stock, minBatch, depth) {
    if (!target || (depth || 0) > 6) return null;
    const recipe = reverseReactions()[target];
    if (!recipe) return null;                              // 基础矿：没有反应能做出它
    const missing = recipe.filter((input) => num(stock[input], 0) < minBatch);
    if (!missing.length) return { a: recipe[0], b: recipe[1], product: target };
    for (const input of missing) {
        if (BASE_MINERALS.indexOf(input) >= 0) continue;   // 缺基础矿：只能靠矿脉/调剂
        const deeper = nextReactionFor(input, stock, minBatch, (depth || 0) + 1);
        if (deeper) return deeper;
    }
    return null;
}

/** 还想做的目标化合物：config.industry.boostTargets 里库存不到 boostGoal 的第一个 */
function wantedTarget(stock, cfg) {
    const targets = Array.isArray(cfg.boostTargets) ? cfg.boostTargets : [];
    const goal = Math.max(1, num(cfg.boostGoal, 3000));
    for (const target of targets) {
        if (num(stock[target], 0) < goal) return target;
    }
    return null;
}

/** 机会主义配对：库存里两种各 ≥ minBatch、REACTIONS 有产物的一对（按名字排序，选择稳定） */
function pickPair(stock, minBatch) {
    if (typeof REACTIONS === 'undefined' || !REACTIONS) return null;
    const types = Object.keys(stock).filter((type) => stock[type] >= minBatch).sort();
    for (let i = 0; i < types.length; i++) {
        for (let j = i + 1; j < types.length; j++) {
            const product = REACTIONS[types[i]] && REACTIONS[types[i]][types[j]];
            if (product) return { a: types[i], b: types[j], product };
        }
    }
    return null;
}

function rolesValid(roles, labsById) {
    if (!roles || !Array.isArray(roles.inputs) || roles.inputs.length !== 2 || !Array.isArray(roles.outputs) || !roles.outputs.length) return false;
    const inputs = roles.inputs.map((id) => labsById[id]);
    if (inputs.some((lab) => !lab) || inputs[0] === inputs[1]) return false;
    return roles.outputs.every((id) => labsById[id] && roles.inputs.indexOf(id) < 0 &&
        inputs.every((input) => chebyshev(input.pos, labsById[id].pos) <= 2));
}

/** lab 分工（输入两个 + 输出 + 一个 boost lab），存进 Memory.rooms[房].labRoles 保持跨 tick 稳定：
 *  每 tick 重新推导时，装货中途（一个输入有货、另一个还空）会让 deriveReaction 换一组输出、取送计划来回翻。
 *  人手配置（Memory.rooms[房].industry.reaction）优先；否则先按 lab 里已有的矿物推导，再退回纯几何三连。 */
function labRoles(room, mem, labs) {
    const labsById = {};
    for (const lab of labs) labsById[lab.id] = lab;
    const configured = normalizeReaction(mem.industry && mem.industry.reaction);
    let roles = null;
    let fresh = false;
    if (configured && rolesValid(configured, labsById)) {
        roles = { inputs: configured.inputs, outputs: configured.outputs, configured: true };
    } else if (mem.labRoles && rolesValid(mem.labRoles, labsById)) {
        roles = mem.labRoles;
    } else {
        const derived = deriveReaction(labs);
        const picked = derived ? { inputs: derived.inputs, outputs: derived.outputs } : labTriple(labs);
        if (!picked) { delete mem.labRoles; return null; }
        roles = { inputs: picked.inputs, outputs: picked.outputs, at: Game.time };
        fresh = true;
    }
    // boost lab：三连之外的一个 lab（按 id 第一个）。src/boost.js 一类的强化逻辑找的是「装着这个化合物的 lab」，
    // 没有专门的 boost lab，做出来的化合物只会被收回 terminal
    const used = roles.inputs.concat(roles.outputs);
    if (!roles.boost || !labsById[roles.boost] || used.indexOf(roles.boost) >= 0) {
        const spare = labs.filter((lab) => used.indexOf(lab.id) < 0).sort(byId)[0];
        roles.boost = spare ? spare.id : null;
        fresh = true;
    }
    if (!roles.configured && fresh) mem.labRoles = roles;
    return roles;
}

/** 本房 labTech 手里正搬着的矿物也算库存：取货那一 tick terminal 少了、lab 还没到，不算会让反应选择来回翻 */
function carriedStock(room, out) {
    const kind = typeof FIND_MY_CREEPS !== 'undefined' ? FIND_MY_CREEPS : null;
    if (kind == null || typeof room.find !== 'function') return;
    for (const creep of room.find(kind) || []) {
        if (creep && creep.memory && creep.memory.role === 'labTech') addStock(out, creep.store);
    }
}

/** 这一批做什么：两个输入都装着能反应的矿物、输出 lab 收得下 ⇒ 接着做（不中途换）；否则按目标化合物的反应链选下一步，
 *  链上这一步做不了时退回机会主义配对。lab 里的货与搬运中的货都算库存。 */
function chooseReaction(room, mem, roles, labsById, cfg) {
    const inputs = roles.inputs.map((id) => labsById[id]);
    const output = labsById[roles.outputs[0]];
    const ta = labMineral(inputs[0]);
    const tb = labMineral(inputs[1]);
    const outType = labMineral(output);
    const saved = mem.labRoles && mem.labRoles.step;
    const stock = mineralStock(room);
    for (const lab of inputs) addStock(stock, lab.store);
    carriedStock(room, stock);
    if (ta && tb && ta !== tb && typeof REACTIONS !== 'undefined' && REACTIONS && REACTIONS[ta] && REACTIONS[ta][tb]) {
        const product = REACTIONS[ta][tb];
        if (!outType || outType === product) {
            return { a: ta, b: tb, product, target: saved && saved.product === product ? saved.target || null : null, continued: true, stock };
        }
    }
    const boost = roles.boost && labsById[roles.boost];
    const targetStock = Object.assign({}, stock);
    if (boost) addStock(targetStock, boost.store);
    const target = wantedTarget(targetStock, cfg);
    let step = target ? nextReactionFor(target, stock, cfg.minBatch, 0) : null;
    let stepTarget = step ? target : null;
    if (!step) step = pickPair(stock, cfg.minBatch);
    if (!step) return null;
    // 已经装着其中一种的输入 lab 就装那一种：换位置意味着先把它清空
    let a = step.a;
    let b = step.b;
    if (ta === b || tb === a) { a = step.b; b = step.a; }
    if (!roles.configured && mem.labRoles) mem.labRoles.step = { product: step.product, target: stepTarget, at: Game.time };
    return { a, b, product: step.product, target: stepTarget, continued: false, stock };
}

function storeOf(lab, type) {
    return lab && lab.store ? num(lab.store[type], 0) : 0;
}

/** labTech 的取送计划（每房每 tick 只算一次）：
 *  wants  [{labId, mineral, amount}]：从 terminal/storage 取货装进 lab
 *  drains [{labId, mineral, amount}]：从 lab 收回 terminal（产物攒够一批、输入装错了货、输出装着别的产物）
 *  industry 本身不动 creep，roles/labTech 与 spawn.labTechTarget 都读它。 */
const planCache = { time: -1, rooms: {} };
function labPlan(room) {
    if (!room) return null;
    if (planCache.time !== Game.time) { planCache.time = Game.time; planCache.rooms = {}; }
    if (Object.prototype.hasOwnProperty.call(planCache.rooms, room.name)) return planCache.rooms[room.name];
    const plan = computeLabPlan(room);
    planCache.rooms[room.name] = plan;
    return plan;
}

function computeLabPlan(room) {
    const labs = myStructures(room, STRUCTURE_LAB);
    if (labs.length < 3) return null;
    const mem = roomMem(room);
    const roles = labRoles(room, mem, labs);
    if (!roles) return null;
    const labsById = {};
    for (const lab of labs) labsById[lab.id] = lab;
    const cfg = labSettings();
    const reaction = chooseReaction(room, mem, roles, labsById, cfg);
    const wants = [];
    const drains = [];
    const need = {};
    if (reaction) {
        need[roles.inputs[0]] = reaction.a;
        need[roles.inputs[1]] = reaction.b;
    }
    for (const id of roles.inputs) {
        const lab = labsById[id];
        const held = labMineral(lab);
        const type = need[id];
        if (held && held !== type) { drains.push({ labId: id, mineral: held, amount: storeOf(lab, held) }); continue; }
        if (!type) continue;
        const have = storeOf(lab, type);
        const available = num(reaction.stock[type], 0) - have;
        // 降到 minBatch 以下才补、一次补到 fill：每次都补零头会让 labTech 为几十单位来回孵
        if (have < cfg.minBatch && available > 0) wants.push({ labId: id, mineral: type, amount: cfg.fill - have });
    }
    for (const id of roles.outputs) {
        const lab = labsById[id];
        const held = labMineral(lab);
        if (!held) continue;
        const amount = storeOf(lab, held);
        // 产物攒够一批收回（输出满了反应会停）；装着的不是这一批的产物：整个清掉，否则新反应永远开不了工
        if (amount >= cfg.minBatch || !reaction || held !== reaction.product) drains.push({ labId: id, mineral: held, amount });
    }
    const boostWant = boostLabJob(room, roles, labsById, cfg, reaction, wants, drains);
    return {
        product: reaction ? reaction.product : null,
        target: reaction ? reaction.target : null,
        continued: !!(reaction && reaction.continued),
        configured: !!roles.configured,
        inputs: roles.inputs.slice(),
        outputs: roles.outputs.slice(),
        output: roles.outputs[0],
        boost: roles.boost || null,
        boostLab: boostWant,
        need,
        wants,
        drains,
        drain: drains[0] || null,
    };
}

/** boost lab（移植 overmind-absorb 019c5b1）：产物做出来后被收回 terminal，而强化要的是「已经装着这个化合物的 lab」——
 *  没有任何代码往那种 lab 里装货，做出来的化合物只会躺在 terminal 里。目标化合物库存攒够 labBoostStock 就把一份装进
 *  三连之外的 boost lab（plan.wants 多一条，labTech 不用改）；装着别的东西（不在 boostTargets 里）先清掉；用掉一半再补。 */
function boostLabJob(room, roles, labsById, cfg, reaction, wants, drains) {
    const lab = roles.boost && labsById[roles.boost];
    if (!lab) return null;
    const stock = reaction ? reaction.stock : (() => { const out = mineralStock(room); carriedStock(room, out); return out; })();
    const held = labMineral(lab);
    if (held && cfg.boostTargets.indexOf(held) < 0) {
        drains.push({ labId: lab.id, mineral: held, amount: storeOf(lab, held) });
        return null;
    }
    let want = null;
    if (held) {
        const have = storeOf(lab, held);
        if (have < cfg.boostStock / 2 && num(stock[held], 0) > 0) want = { labId: lab.id, mineral: held, amount: cfg.boostStock - have, boost: true };
    } else {
        const compound = cfg.boostTargets.find((type) => num(stock[type], 0) >= cfg.boostStock);
        if (compound) want = { labId: lab.id, mineral: compound, amount: cfg.boostStock, boost: true };
    }
    if (want) wants.push(want);
    return want;
}

function runLabs(room, mem, state, spendAllowed) {
    const labs = myStructures(room, STRUCTURE_LAB);
    // 储备闸关着（线上大多数房 storage≈0）：反应不会跑、labTech 也不会孵，不为它算取送计划（每 5 tick × 每个有 lab 的房）
    // boost lab 的 id 照记（2026-10-13 复审）：task_broker.labEnergyWant 只认 industryState.labs.boostLab，它的补能闸（富余且 ≥ terminalFillStorageAbove）
    // 比储备闸松——storage 5–10 万时储备闸关着、补能闸开着，丢了 id 就没人给已装好化合物的 boost lab 补能量，boostCreep 半路断粮。
    // labRoles 只读/写 Memory 里的分工（分工有效时不扫库存、不选反应），比整份计划便宜得多
    if (!spendAllowed) {
        let boostLab = null;
        if (labs.length >= 3) {
            const roles = labRoles(room, roomMem(room), labs);
            boostLab = roles && roles.boost ? roles.boost : null;
        }
        state.labs = { present: labs.length, configured: false, derived: null, target: null, product: null, active: false, gated: true, boostLab };
        return;
    }
    const plan = labPlan(room);
    // 两个输入都装着这一批的料才算「配置好了」；装货中途、或输入装错了货都不发 runReaction
    const ready = !!plan && !!plan.product && plan.inputs.every((id) => {
        const lab = getById(id);
        return lab && labMineral(lab) === plan.need[id];
    });
    state.labs = {
        present: labs.length,
        configured: ready,
        derived: plan && plan.continued && !plan.configured ? { product: plan.product, output: plan.output } : null,
        // 这一步是在为哪个目标化合物服务（反应链）；机会主义配对没有 target
        target: plan ? plan.target : null,
        product: plan ? plan.product : null,
        wants: plan ? plan.wants.length : 0,
        drains: plan ? plan.drains.length : 0,
        // boost lab 的 id：task_broker 只给它补能量（boostCreep 每部件 20 能量，反应本身不耗能）
        boostLab: plan ? plan.boost : null,
        active: false,
    };
    if (!ready) return;
    const inputA = getById(plan.inputs[0]);
    const inputB = getById(plan.inputs[1]);
    if (!inputA || !inputB || inputA.room !== room || inputB.room !== room) {
        state.labs.error = 'missing-input';
        return;
    }
    for (const id of plan.outputs) {
        const output = getById(id);
        if (!output || output.room !== room || typeof output.runReaction !== 'function') continue;
        if (output.cooldown > 0) continue;
        const held = labMineral(output);
        if (held && held !== plan.product) continue;
        const ret = output.runReaction(inputA, inputB);
        state.labs.active = true;
        state.labs.lastOutput = output.id;
        state.labs.result = ret;
        if (ret === OK) return;
    }
}

function runFactory(room, mem, state, spendAllowed) {
    const factories = myStructures(room, STRUCTURE_FACTORY);
    const product = normalizeProduct(mem.industry && mem.industry.product);
    state.factory = {
        present: factories.length,
        configured: !!product,
        active: false,
    };
    if (!spendAllowed || !product || !factories.length) return;
    const factory = (product.factoryId && getById(product.factoryId)) || factories[0];
    if (!factory || factory.room !== room || typeof factory.produce !== 'function') {
        state.factory.error = 'missing-factory';
        return;
    }
    if (factory.cooldown > 0) {
        state.factory.cooldown = factory.cooldown;
        return;
    }
    const ret = factory.produce(product.resource);
    state.factory.active = true;
    state.factory.resource = product.resource;
    state.factory.result = ret;
}

function runPowerSpawn(room, state, spendAllowed) {
    const powerSpawn = myStructures(room, STRUCTURE_POWER_SPAWN)[0];
    const powerKey = typeof RESOURCE_POWER === 'string' ? RESOURCE_POWER : 'power';
    state.powerSpawn = {
        present: !!powerSpawn,
        active: false,
    };
    if (!spendAllowed || !powerSpawn || typeof powerSpawn.processPower !== 'function') return;
    const energy = used(powerSpawn.store, RESOURCE_ENERGY);
    const power = used(powerSpawn.store, powerKey);
    state.powerSpawn.energy = energy;
    state.powerSpawn.power = power;
    if (energy < 50 || power < 1) return;
    const ret = powerSpawn.processPower();
    state.powerSpawn.active = true;
    state.powerSpawn.result = ret;
}

function sample(room, mem) {
    const extractor = myStructures(room, STRUCTURE_EXTRACTOR)[0];
    const mineral = room.find(FIND_MINERALS)[0] || null;
    const nuker = myStructures(room, STRUCTURE_NUKER)[0];
    const powerKey = typeof RESOURCE_POWER === 'string' ? RESOURCE_POWER : 'power';
    const ghodiumKey = typeof RESOURCE_GHODIUM === 'string' ? RESOURCE_GHODIUM : 'ghodium';
    return {
        at: Game.time,
        rcl: room.controller ? room.controller.level : 0,
        storageEnergy: storageEnergy(room),
        terminalEnergy: terminalEnergy(room),
        storageReserve: reserve('storageReserve'),
        terminalReserve: reserve('terminalReserve'),
        powerStorageReserve: reserve('powerStorageReserve'),
        spendingUnlocked: canSpend(room),
        terminal: room.terminal ? {
            cooldown: room.terminal.cooldown || 0,
            energy: used(room.terminal.store, RESOURCE_ENERGY),
            free: free(room.terminal.store),
        } : null,
        extractor: extractor ? {
            cooldown: extractor.cooldown || 0,
            mineralType: mineral && mineral.mineralType,
            mineralAmount: mineral && mineral.mineralAmount,
        } : null,
        labs: { present: countMy(room, STRUCTURE_LAB) },
        factory: { present: countMy(room, STRUCTURE_FACTORY) },
        observer: { present: countMy(room, STRUCTURE_OBSERVER) },
        powerSpawn: {
            present: countMy(room, STRUCTURE_POWER_SPAWN),
            energy: powerSpawnEnergy(room),
            power: powerSpawnPower(room, powerKey),
        },
        nuker: nuker ? {
            cooldown: nuker.cooldown || 0,
            energy: used(nuker.store, RESOURCE_ENERGY),
            ghodium: used(nuker.store, ghodiumKey),
        } : null,
    };
}

function powerSpawnEnergy(room) {
    const powerSpawn = myStructures(room, STRUCTURE_POWER_SPAWN)[0];
    return powerSpawn ? used(powerSpawn.store, RESOURCE_ENERGY) : 0;
}

function powerSpawnPower(room, powerKey) {
    const powerSpawn = myStructures(room, STRUCTURE_POWER_SPAWN)[0];
    return powerSpawn ? used(powerSpawn.store, powerKey) : 0;
}

function run(room) {
    try {
        if (!room || !room.controller || !room.controller.my || room.controller.level < 6) return;
        const mem = roomMem(room);
        const state = sample(room, mem);
        const spendAllowed = state.spendingUnlocked;
        runObserver(room, mem, state);
        runLabs(room, mem, state, spendAllowed);
        runFactory(room, mem, state, spendAllowed);
        runPowerSpawn(room, state, canProcessPower(room));
        mem[DEFAULTS.statusKey] = state;
    } catch (e) {
        const mem = room && room.name ? roomMem(room) : null;
        if (mem) {
            mem[DEFAULTS.statusKey] = {
                at: Game.time,
                error: (e && e.message) || String(e),
            };
        }
    }
}

module.exports = { run, deriveReaction, canSpend, labPlan, labRoles, mineralStock, pickPair, nextReactionFor, wantedTarget, reverseReactions, labTriple, BASE_MINERALS };

modules.layout:
'use strict';
/** 房间布局：规划只来自轮子（vendor/wheels/layout-2.1.0，经 wheel_layout.generate 在游戏内跑一次），
 *  本模块按 RCL 配额逐步放置工地。规划结果缓存在 Memory.rooms[name].plan（wheel: true）。 */
const config = require('config');
const utils = require('utils');
const { creepsHome, creepsHomeRole } = utils;
const wheelLayout = require('wheel_layout');
const brain = require('brain');
const { planPath, unpackPath, isWall, occupied, bestAdjacent, logErr } = utils;

function addTaken(taken, spot) {
    if (spot && spot.x != null && spot.y != null) taken.add(spot.x + '.' + spot.y);
}

function sameIds(left, right) {
    if (!Array.isArray(left) || left.length !== right.length) return false;
    for (let i = 0; i < right.length; i++) if (left[i] !== right[i]) return false;
    return true;
}

function sourceAnchor(room, plan) {
    if (plan && plan.anchor) return plan.anchor;
    const spawn = room.find(FIND_MY_SPAWNS).slice()
        .sort((a, b) => a.pos.x - b.pos.x || a.pos.y - b.pos.y || String(a.id).localeCompare(String(b.id)))[0];
    return spawn ? spawn.pos : { x: 25, y: 25 };
}

function sourcesByAnchor(room, anchor) {
    return room.find(FIND_SOURCES).slice().sort((a, b) => {
        const aDistance = (a.pos.x - anchor.x) ** 2 + (a.pos.y - anchor.y) ** 2;
        const bDistance = (b.pos.x - anchor.x) ** 2 + (b.pos.y - anchor.y) ** 2;
        return aDistance - bDistance || String(a.id).localeCompare(String(b.id)) || a.pos.x - b.pos.x || a.pos.y - b.pos.y;
    });
}

function remapHarvesterSources(room, previousIds, nextIds) {
    if (!nextIds.length) return;
    const memories = [];
    const seen = new Set();
    for (const creep of creepsHomeRole(room.name, 'harvester')) {
        memories.push(creep.memory);
        seen.add(creep.name);
    }
    for (const spawn of room.find(FIND_MY_SPAWNS)) {
        if (!spawn.spawning || seen.has(spawn.spawning.name) || !Memory.creeps) continue;
        const memory = Memory.creeps[spawn.spawning.name];
        if (memory && memory.home === room.name && memory.role === 'harvester') memories.push(memory);
    }
    const records = memories.map((memory) => {
        let nextIdx = -1;
        if (memory.sourceId) nextIdx = nextIds.indexOf(memory.sourceId);
        if (nextIdx < 0 && memory.sourceId && previousIds && previousIds.length) {
            const previousIdx = previousIds.indexOf(memory.sourceId);
            if (previousIdx >= 0) nextIdx = nextIds.indexOf(previousIds[previousIdx]);
        }
        if (nextIdx < 0 && Number.isInteger(memory.sourceIdx)) {
            const previousId = previousIds && previousIds[memory.sourceIdx];
            nextIdx = previousId ? nextIds.indexOf(previousId) : memory.sourceIdx;
            if (nextIdx >= nextIds.length) nextIdx = -1;
        }
        return { memory, nextIdx };
    });
    const coverage = Array(nextIds.length).fill(0);
    for (const record of records) if (record.nextIdx >= 0) coverage[record.nextIdx]++;
    const leastCovered = () => {
        let best = 0;
        for (let index = 1; index < coverage.length; index++) {
            if (coverage[index] < coverage[best]) best = index;
        }
        coverage[best]++;
        return best;
    };
    for (const record of records) {
        const memory = record.memory;
        const nextIdx = record.nextIdx >= 0 ? record.nextIdx : leastCovered();
        const sourceId = nextIds[nextIdx];
        if (memory.sourceId !== sourceId) memory.sourceId = sourceId;
        if (memory.sourceIdx !== nextIdx) memory.sourceIdx = nextIdx;
    }
}

function harvesterIdentityNeedsRemap(memory, nextIds) {
    if (!memory || memory.role !== 'harvester') return false;
    const sourceId = memory.sourceId;
    const sourceIdx = Number.isInteger(memory.sourceIdx) ? memory.sourceIdx : -1;
    return !sourceId || nextIds.indexOf(sourceId) < 0 || sourceIdx < 0 || nextIds[sourceIdx] !== sourceId;
}

function needsHarvesterRemap(room, nextIds) {
    if (!nextIds.length) return false;
    for (const creep of creepsHome(room.name)) {
        if (harvesterIdentityNeedsRemap(creep.memory, nextIds)) return true;
    }
    const seen = new Set(Object.keys(Game.creeps || {}));
    for (const spawn of room.find(FIND_MY_SPAWNS)) {
        if (!spawn.spawning || seen.has(spawn.spawning.name) || !Memory.creeps) continue;
        const memory = Memory.creeps[spawn.spawning.name];
        if (memory && memory.home === room.name && harvesterIdentityNeedsRemap(memory, nextIds)) return true;
    }
    return false;
}

// 源顺序的每房每 tick 缓存。同一 tick 里 resolveSources 被调很多遍：每只矿工一次（roles/harvester）、spawn 四处、
// links、layout，每次都是 find(FIND_SOURCES) + 排序 + Set 构造，外加 needsHarvesterRemap 把本房 creep 与 spawn 扫一遍；
// 源的位置一辈子不变。函数的副作用（remapHarvesterSources、写回 mem.sources / plan.sourceIds）在 tick 内是幂等的——
// 第一次跑完 sameIds 就成立，后面的调用本来也什么都不做，所以缓存不改变行为。
// 命中要求同一个 room / mem / plan 对象：wheel 规划试算候选方案、或 mem.plan 当 tick 被换掉时照常重算
// （单测会在同一 Game.time 里重建房间，对象身份也挡住了串用）。
const sourceOrderCache = { tick: -1, rooms: {} };
// 进程内累计 [调用, 命中]：main.sampleStats 按窗口取差值写进 Memory.stats.cache.srcOrder
const sourceOrderCounters = { calls: 0, hits: 0 };

/** 将 sourceIdx 固定到持久化 ID：plan.sourceIds 优先，旧布局由 mem.sources 迁移生成。
 *  无效/缺失 ID 会被可见源按稳定坐标顺序补齐，并同步回两处内存。 */
function resolveSources(room, mem, plan) {
    mem = mem || (Memory.rooms && Memory.rooms[room.name]) || {};
    plan = plan || mem.plan || null;
    sourceOrderCounters.calls++;
    // 只缓存"用本房自己方案"的调用；传别的 plan 进来时照常重算
    const cacheable = !plan || plan === mem.plan;
    const now = typeof Game !== 'undefined' ? Game.time : 0;
    if (sourceOrderCache.tick !== now) { sourceOrderCache.tick = now; sourceOrderCache.rooms = {}; }
    const cached = cacheable ? sourceOrderCache.rooms[room.name] : null;
    if (cached && cached.room === room && cached.mem === mem && cached.plan === plan) {
        sourceOrderCounters.hits++;
        return cached.ordered;
    }
    const fallback = sourcesByAnchor(room, sourceAnchor(room, plan));
    const visible = {};
    for (const source of fallback) visible[source.id] = source;

    const memoryIds = Array.isArray(mem.sources) ? mem.sources : [];
    const planIds = plan && Array.isArray(plan.sourceIds) ? plan.sourceIds : [];
    const preferred = planIds.length ? [planIds, memoryIds] : [memoryIds];
    const ordered = [];
    const seen = new Set();
    const addIds = (ids) => {
        for (const id of ids) {
            if (seen.has(id) || !visible[id]) continue;
            seen.add(id);
            ordered.push(visible[id]);
        }
    };
    for (const ids of preferred) addIds(ids);
    for (const source of fallback) {
        if (seen.has(source.id)) continue;
        seen.add(source.id);
        ordered.push(source);
    }

    if (ordered.length) {
        const ids = ordered.map((source) => source.id);
        const sourceOrderChanged = !sameIds(mem.sources, ids);
        if (sourceOrderChanged || needsHarvesterRemap(room, ids)) {
            remapHarvesterSources(room, memoryIds.length ? memoryIds : ids, ids);
            mem.sources = ids.slice();
        }
        if (plan && !sameIds(plan.sourceIds, ids)) plan.sourceIds = ids.slice();
    }
    if (cacheable) sourceOrderCache.rooms[room.name] = { room, mem, plan, ordered };
    return ordered;
}

/** 源顺序缓存的进程内累计计数（[调用, 命中] 的来源） */
function sourceOrderStats() {
    return { calls: sourceOrderCounters.calls, hits: sourceOrderCounters.hits };
}

function collectPlannedTaken(plan, includeContainers = true) {
    const taken = new Set();
    if (includeContainers) Object.values(plan.containers || {}).forEach((spot) => addTaken(taken, spot));
    ['storage', 'terminal'].forEach((key) => addTaken(taken, plan[key]));
    ['towers', 'spawn2', 'spawn3', 'labs', 'misc', 'ext'].forEach((key) => {
        for (const spot of plan[key] || []) addTaken(taken, spot);
    });
    for (const spot of plan.spawns || []) addTaken(taken, spot);
    Object.values(plan.structures || {}).forEach((spot) => addTaken(taken, spot));
    Object.values(plan.links || {}).forEach((spot) => addTaken(taken, spot));
    return taken;
}

function linkSpot(plan, key) {
    if (!plan || !plan.links) return null;
    if (key === 'src0') return plan.links.src0 || plan.links.src || null;
    return plan.links[key] || null;
}

function chebyshev(a, b) {
    return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
}

const stationCache = { time: -1, rooms: {} };

/** 升级者的 storage 站位（向 Kalgen 学的：升级者静止在 storage 旁直接取能，不要控制器容器/控制器 link）：
 *  storage 已建成时，与 storage 相邻、控制器射程 3 内、不是墙也不是规划结构位、没有不可通行建筑的格；
 *  非道路格优先，其次贴规划 link 的、离控制器近的。没有这样的格（W34S7 的 storage 离控制器 5 格）返回 []，升级者退回容器/ctrl link 站位。 */
function upgraderStorageStations(room, plan) {
    const storage = room && room.storage;
    const controller = room && room.controller;
    if (!storage || storage.my === false || !storage.pos || !controller || !controller.pos) return [];
    if (stationCache.time !== Game.time) { stationCache.time = Game.time; stationCache.rooms = {}; }
    const cacheKey = room.name + '|' + (storage.id || '');
    if (stationCache.rooms[cacheKey]) return stationCache.rooms[cacheKey];
    plan = plan || {};
    const blocked = new Set();
    const mark = (spot) => { if (spot && spot.x != null && spot.y != null) blocked.add(spot.x + '.' + spot.y); };
    for (const key of ['ext', 'spawns', 'spawn2', 'spawn3', 'towers', 'labs', 'misc', 'structures']) {
        const list = Array.isArray(plan[key]) ? plan[key] : (plan[key] ? [plan[key]] : []);
        for (const spot of list) mark(spot);
    }
    mark(plan.storage);
    mark(plan.terminal);
    for (const spot of Object.values(plan.links || {})) mark(spot);
    for (const spot of Object.values(plan.containers || {})) mark(spot);
    const roads = new Set();
    for (const packed of Object.values(plan.roads || {})) {
        if (typeof packed === 'string' && packed) for (const p of unpackPath(packed)) roads.add(p.x + '.' + p.y);
    }
    const linkSpots = Object.values(plan.links || {}).filter((spot) => spot && spot.x != null);
    const builtLinkSpots = linkSpots.filter((spot) => {
        const link = structureAt(room, spot.x, spot.y, STRUCTURE_LINK);
        return link && link.my !== false;
    });
    const walkable = new Set([STRUCTURE_ROAD, STRUCTURE_RAMPART, STRUCTURE_CONTAINER]);
    const spots = [];
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const x = storage.pos.x + dx;
        const y = storage.pos.y + dy;
        if (x < 1 || x > 48 || y < 1 || y > 48) continue;
        const ctrlDist = chebyshev({ x, y }, controller.pos);
        if (ctrlDist > 3) continue;
        if (isWall(room, x, y)) continue;
        const key = x + '.' + y;
        if (blocked.has(key)) continue;
        const here = room.lookForAt(LOOK_STRUCTURES, x, y) || [];
        if (here.some((s) => !walkable.has(s.structureType))) continue;
        const road = roads.has(key) || here.some((s) => s.structureType === STRUCTURE_ROAD);
        const nearLinks = linkSpots.filter((spot) => chebyshev(spot, { x, y }) <= 1).length;
        // 已建成的 link 相邻（RCL5 的 ctrl link 由源 link 免费供能）：站在它旁边 storage 空着也能喝 link，优先级高于只是规划里有 link 的格
        const builtLinks = builtLinkSpots.filter((spot) => chebyshev(spot, { x, y }) <= 1).length;
        spots.push({ x, y, road, nearLinks, builtLinks, ctrlDist });
    }
    // 贴着已建成的 link 排第一（哪怕是道路格）：不贴 link 的站位只能喝 storage，ctrl link 喝不空整条 link 链就堵死，
    // 源头产出全靠 hauler 手搬（线上 W31S5/W31S8：选中的站位 0/55、2/48 采样贴着 ctrl link）；站在路上挡一格，移动库会绕开干活的 creep
    spots.sort((a, b) => (b.builtLinks - a.builtLinks) || (a.road - b.road) || (b.nearLinks - a.nearLinks) || (a.ctrlDist - b.ctrlDist) || (a.y - b.y) || (a.x - b.x));
    stationCache.rooms[cacheKey] = spots;
    return spots;
}

/** 升级者是否由 storage 供能（有 storage 站位）：为真时控制器容器不再喂、hauler 往返不再算控制器段 */
function controllerFedByStorage(room, plan) {
    return upgraderStorageStations(room, plan).length > 0;
}

/** 升级者站位——roles/upgrader 的走位与 movement 的工位判定共用这一份定义（两边各推一遍曾经分叉：交通解算把站在 storage 旁的升级者当闲人推开）。
 *  storage 建成且有相邻站位时以 storage 为锚（storageFed，spots 为站位列表）；否则首选站点是规划容器位（或工作位），能量锚点为已建成的
 *  ctrl link > 容器；容器/link 都没建时 anchor 为 null，升级者贴 controller 3 格内即可 */
function upgraderStation(room, plan) {
    plan = plan || {};
    const storageSpots = upgraderStorageStations(room, plan);
    if (storageSpots.length) {
        return { pos: { x: storageSpots[0].x, y: storageSpots[0].y }, container: null, anchor: room.storage, spots: storageSpots, storageFed: true };
    }
    const c = plan.containers && plan.containers.ctrl;
    const spot = c || (plan.workPositions && plan.workPositions.ctrl);
    if (!spot) return null;
    const container = c ? structureAt(room, c.x, c.y, STRUCTURE_CONTAINER) : null;
    const linkPos = linkSpot(plan, 'ctrl');
    const link = linkPos ? structureAt(room, linkPos.x, linkPos.y, STRUCTURE_LINK) : null;
    return { pos: { x: spot.x, y: spot.y }, container, anchor: (link && link.my) ? link : container || null, spots: null, storageFed: false };
}

/** 站在锚点 1 格内且 controller 3 格内即可工作：多个升级者共用一个锚点，不必抢同一格 */
function atUpgraderStation(pos, station, controller) {
    const anchor = station.anchor ? station.anchor.pos : station.pos;
    return chebyshev(pos, anchor) <= 1 && chebyshev(pos, controller.pos) <= 3;
}

function compatibleSourceLink(room, source, container, anchor, taken, current) {
    if (!source) return current || null;
    const fixed = current && (structureAt(room, current.x, current.y, STRUCTURE_LINK) ||
        siteAt(room, current.x, current.y, STRUCTURE_LINK));
    if (current && (!container || chebyshev(current, container) <= 1 || fixed)) return current;
    if (current) taken.delete(current.x + '.' + current.y);
    const candidates = [];
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const x = source.pos.x + dx;
        const y = source.pos.y + dy;
        const key = x + '.' + y;
        if (x < 1 || x > 48 || y < 1 || y > 48 || isWall(room, x, y)) continue;
        if (container && chebyshev({ x, y }, container) > 1) continue;
        if (taken.has(key) || occupied(room, x, y)) continue;
        candidates.push({ x, y, d: (x - anchor.x) ** 2 + (y - anchor.y) ** 2 });
    }
    candidates.sort((a, b) => a.d - b.d);
    return candidates.length ? { x: candidates[0].x, y: candidates[0].y } : current || null;
}

function adjacentContainer(room, target, anchor, taken) {
    if (!target) return null;
    const candidates = [];
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const x = target.x + dx;
        const y = target.y + dy;
        if (x < 1 || x > 48 || y < 1 || y > 48) continue;
        const key = x + '.' + y;
        if (taken && taken.has(key)) continue;
        if (!structureAt(room, x, y, STRUCTURE_CONTAINER) && !siteAt(room, x, y, STRUCTURE_CONTAINER)) continue;
        candidates.push({ x, y, d: anchor ? (x - anchor.x) ** 2 + (y - anchor.y) ** 2 : 0 });
    }
    candidates.sort((left, right) => left.d - right.d || left.y - right.y || left.x - right.x);
    return candidates.length ? { x: candidates[0].x, y: candidates[0].y } : null;
}

function existingContainer(room, target, preferred, anchor, taken) {
    if (!target || typeof room.find !== 'function') return null;
    const preferredKey = preferred && preferred.x != null && preferred.y != null ?
        preferred.x + '.' + preferred.y : null;
    const candidates = room.find(FIND_STRUCTURES).filter((structure) => {
        if (structure.structureType !== STRUCTURE_CONTAINER) return false;
        if (structure.my === false || !structure.pos) return false;
        if (structure.pos.x < 1 || structure.pos.x > 48 || structure.pos.y < 1 || structure.pos.y > 48) return false;
        if (chebyshev(structure.pos, target) > 1) return false;
        const key = structure.pos.x + '.' + structure.pos.y;
        return !taken || !taken.has(key);
    });
    candidates.sort((left, right) => {
        const leftKey = left.pos.x + '.' + left.pos.y;
        const rightKey = right.pos.x + '.' + right.pos.y;
        const leftPreferred = leftKey === preferredKey ? 0 : 1;
        const rightPreferred = rightKey === preferredKey ? 0 : 1;
        if (leftPreferred !== rightPreferred) return leftPreferred - rightPreferred;
        const leftTarget = chebyshev(left.pos, target);
        const rightTarget = chebyshev(right.pos, target);
        if (leftTarget !== rightTarget) return leftTarget - rightTarget;
        const leftAnchor = anchor ? Math.abs(left.pos.x - anchor.x) + Math.abs(left.pos.y - anchor.y) : 0;
        const rightAnchor = anchor ? Math.abs(right.pos.x - anchor.x) + Math.abs(right.pos.y - anchor.y) : 0;
        return leftAnchor - rightAnchor || left.pos.y - right.pos.y || left.pos.x - right.pos.x;
    });
    return candidates.length ? { x: candidates[0].pos.x, y: candidates[0].pos.y } : null;
}

function duplicateContainerSite(room, target, previous, adopted) {
    if (!target || typeof room.find !== 'function') return null;
    const preferredKey = previous && previous.x != null && previous.y != null ?
        previous.x + '.' + previous.y : null;
    const adoptedKey = adopted && adopted.x != null && adopted.y != null ?
        adopted.x + '.' + adopted.y : null;
    const sites = room.find(FIND_MY_CONSTRUCTION_SITES).filter((site) => {
        if (site.structureType !== STRUCTURE_CONTAINER || !site.pos) return false;
        if (chebyshev(site.pos, target) > 1) return false;
        const key = site.pos.x + '.' + site.pos.y;
        return key !== adoptedKey;
    });
    sites.sort((left, right) => {
        const leftKey = left.pos.x + '.' + left.pos.y;
        const rightKey = right.pos.x + '.' + right.pos.y;
        const leftTotal = Math.max(0, Number(left.progressTotal) || 0);
        const rightTotal = Math.max(0, Number(right.progressTotal) || 0);
        const leftRatio = leftTotal ? (Math.max(0, Number(left.progress) || 0) / leftTotal) : 0;
        const rightRatio = rightTotal ? (Math.max(0, Number(right.progress) || 0) / rightTotal) : 0;
        const leftPreferred = leftKey === preferredKey ? 0 : 1;
        const rightPreferred = rightKey === preferredKey ? 0 : 1;
        return rightRatio - leftRatio || (Number(right.progress) || 0) - (Number(left.progress) || 0) ||
            leftPreferred - rightPreferred;
    });
    return sites.length ? sites[0] : null;
}

function canAdoptExistingContainer(site) {
    if (!site) return true;
    const progress = Math.max(0, Number(site.progress) || 0);
    const total = Math.max(0, Number(site.progressTotal) || 0);
    if (!total) return true;
    return progress <= total - progress;
}

function removeDuplicateContainerSite(site) {
    if (!site || typeof site.remove !== 'function') return false;
    const result = site.remove();
    return result == null || result === OK;
}

function compatibleWorkSpot(spot, target, container) {
    if (!spot || spot.x == null || spot.y == null || !target || target.x == null || target.y == null ||
        chebyshev(spot, target) > 1) return false;
    return !container || chebyshev(spot, container) <= 1;
}

function validContainerSpot(room, target, spot, taken) {
    if (!target || !spot || spot.x == null || spot.y == null || chebyshev(target, spot) > 1) return false;
    if (spot.x < 1 || spot.x > 48 || spot.y < 1 || spot.y > 48 || isWall(room, spot.x, spot.y)) return false;
    if (taken && taken.has(spot.x + '.' + spot.y)) return false;
    if (structureAt(room, spot.x, spot.y, STRUCTURE_CONTAINER) ||
        siteAt(room, spot.x, spot.y, STRUCTURE_CONTAINER)) return true;
    return !occupied(room, spot.x, spot.y);
}

function normalizeContainers(room, plan, sources, anchor) {
    const previous = plan.containers || {};
    if (!plan.workPositions || typeof plan.workPositions !== 'object' || Array.isArray(plan.workPositions)) {
        plan.workPositions = {};
    }
    const workPositions = plan.workPositions;
    const taken = collectPlannedTaken(plan);
    const otherTaken = collectPlannedTaken(plan, false);
    for (const spot of Object.values(previous)) {
        if (spot && !otherTaken.has(spot.x + '.' + spot.y)) taken.delete(spot.x + '.' + spot.y);
    }

    const targets = [];
    for (let index = 0; index < sources.length; index++) {
        targets.push(['src' + index, sources[index] && sources[index].pos]);
    }
    targets.push(['ctrl', room.controller && room.controller.pos]);

    const normalized = Object.assign({}, previous);
    for (const [key, target] of targets) {
        if (!target) continue;
        let spot = previous[key];
        const built = existingContainer(room, target, spot, anchor, taken);
        const duplicate = duplicateContainerSite(room, target, spot, built);
        if (built && duplicate) {
            if (canAdoptExistingContainer(duplicate) && removeDuplicateContainerSite(duplicate)) {
                spot = built;
            } else {
                // 已投入过半（或无法确认删除成功）的重复工地优先保留，避免丢弃进度。
                spot = { x: duplicate.pos.x, y: duplicate.pos.y };
            }
        } else if (built) {
            spot = built;
        } else if (!validContainerSpot(room, target, spot, taken)) {
            spot = adjacentContainer(room, target, anchor, taken) || bestAdjacent(target, room, anchor, taken);
        }
        if (spot) {
            normalized[key] = spot;
            if (!compatibleWorkSpot(workPositions[key], target, spot)) {
                workPositions[key] = { x: spot.x, y: spot.y };
            }
            addTaken(taken, spot);
        } else {
            delete normalized[key];
            delete workPositions[key];
        }
    }
    plan.containers = normalized;
    return taken;
}

function normalizeLinkPlan(room, plan) {
    if (!plan) return null;
    if (plan.wheel) {
        plan.links = plan.links || {};
        if (!plan.links.src0 && plan.links.src) plan.links.src0 = plan.links.src;
        if (plan.links.src0 && !plan.links.src) plan.links.src = plan.links.src0;
        return plan.links;
    }
    const spawn0 = room.find(FIND_MY_SPAWNS)[0];
    const anchor = plan.anchor || (spawn0 && spawn0.pos) || { x: 25, y: 25 };
    const sources = resolveSources(room, roomMem(room), plan);
    plan.links = plan.links || {};
    if (!plan.links.src0 && plan.links.src) plan.links.src0 = plan.links.src;
    const taken = normalizeContainers(room, plan, sources, anchor);
    const ensure = (key, targetPos) => {
        if (!targetPos) return;
        if (plan.links[key]) {
            addTaken(taken, plan.links[key]);
            return;
        }
        const spot = bestAdjacent(targetPos, room, anchor, taken);
        if (!spot) return;
        plan.links[key] = spot;
        addTaken(taken, spot);
    };
    // ctrl link 放在 upgrader 站位（容器/工作位）旁：controller 常在墙洞里，其相邻格可能只有站位这一格
    const ctrlStation = (plan.containers && plan.containers.ctrl) || (plan.workPositions && plan.workPositions.ctrl) ||
        (room.controller && room.controller.pos);
    ensure('ctrl', ctrlStation);
    if (sources[0]) {
        const sourceSpot = plan.workPositions && plan.workPositions.src0 || plan.containers && plan.containers.src0;
        plan.links.src0 = compatibleSourceLink(room, sources[0], sourceSpot,
            anchor, taken, plan.links.src0);
        addTaken(taken, plan.links.src0);
        plan.links.src = plan.links.src0;
    }
    if (sources[1]) {
        const sourceSpot = plan.workPositions && plan.workPositions.src1 || plan.containers && plan.containers.src1;
        plan.links.src1 = compatibleSourceLink(room, sources[1], sourceSpot,
            anchor, taken, plan.links.src1);
        addTaken(taken, plan.links.src1);
    }
    ensure('store', room.storage ? room.storage.pos : plan.storage);
    return plan.links;
}

function roomMem(room) {
    if (!Memory.rooms[room.name]) Memory.rooms[room.name] = {};
    return Memory.rooms[room.name];
}
function structureAt(room, x, y, type) {
    return room.lookForAt(LOOK_STRUCTURES, x, y).find((s) => s.structureType === type) || null;
}
function siteAt(room, x, y, type) {
    return room.lookForAt(LOOK_CONSTRUCTION_SITES, x, y).find((s) => s.structureType === type) || null;
}
function countType(room, type) {
    return room.find(FIND_STRUCTURES).filter((s) => s.structureType === type).length +
        room.find(FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === type).length;
}
/** 各结构在当前 RCL 的配额（对齐 CONTROLLER_STRUCTURES 常量表） */
function allowance(room) {
    const L = room.controller.level;
    const seq = (arr) => arr[Math.min(L, arr.length - 1)];
    return {
        spawn: seq([0, 1, 1, 1, 1, 1, 1, 2, 3]),
        extension: seq([0, 0, 5, 10, 20, 30, 40, 50, 60]),
        tower: seq([0, 0, 0, 1, 1, 2, 2, 3, 6]),
        storage: L >= 4 ? 1 : 0,
        link: seq([0, 0, 0, 0, 0, 2, 3, 4, 6]),
        terminal: L >= 6 ? 1 : 0,
        lab: seq([0, 0, 0, 0, 0, 0, 3, 6, 10]),
        extractor: L >= 6 ? 1 : 0,
        observer: L >= 8 ? 1 : 0,
        powerSpawn: L >= 8 ? 1 : 0,
        nuker: L >= 8 ? 1 : 0,
        factory: L >= 7 ? 1 : 0,
        container: 5,
        road: 2500,
        rampart: L >= 2 ? 2500 : 0,
    };
}

/** 沿规划路径放道路工地，每次最多 n 个 */
function placeRoads(room, plan, budget) {
    let placed = 0;
    const seen = new Set();
    const anchor = plan.anchor || { x: 25, y: 25 };
    const tiles = [];
    for (const str of Object.values(plan.roads || {})) {
        if (!str) continue;
        for (const p of unpackPath(str)) {
            const posKey = p.x + '.' + p.y;
            if (seen.has(posKey)) continue;
            seen.add(posKey);
            tiles.push(p);
        }
    }
    // 轮子给的是整张路网（无序）：从核心向外铺，核心区的路先通
    tiles.sort((a, b) => chebyshev(a, anchor) - chebyshev(b, anchor));
    for (const p of tiles) {
        if (structureAt(room, p.x, p.y, STRUCTURE_ROAD) || siteAt(room, p.x, p.y, STRUCTURE_ROAD)) continue;
        if (trySite(room, p, STRUCTURE_ROAD)) placed++;
        if (placed >= budget) return placed;
    }
    return placed;
}

function structuresCanShare(existingType, plannedType) {
    if (existingType === plannedType) return false;
    if (plannedType === STRUCTURE_RAMPART) return existingType !== STRUCTURE_WALL;
    if (existingType === STRUCTURE_RAMPART) return plannedType !== STRUCTURE_WALL;
    return (existingType === STRUCTURE_ROAD && plannedType === STRUCTURE_CONTAINER) ||
        (existingType === STRUCTURE_CONTAINER && plannedType === STRUCTURE_ROAD);
}

// place() 单轮上下文：本轮记录的冲突（拆迁调度 demolition.js 负责在合适时机清掉阻挡物）
let blockedThisRun = null;
const REPORT_BLOCKED_TYPES = new Set([STRUCTURE_ROAD, STRUCTURE_RAMPART, STRUCTURE_WALL, STRUCTURE_CONTAINER]);

/** 规划点被别的结构占住：记录到 Memory.rooms.*.layoutBlocked，供拆迁调度与监控读取 */
function handleBlocked(room, spot, type, blockers) {
    if (REPORT_BLOCKED_TYPES.has(type)) return;
    const by = blockers.map((structure) => structure.structureType);
    if (blockedThisRun) blockedThisRun.push({ x: spot.x, y: spot.y, type, by: by.length === 1 ? by[0] : by.join('/') });
}

function trySite(room, spot, type) {
    if (!spot) return false;
    if (type !== STRUCTURE_EXTRACTOR && isWall(room, spot.x, spot.y)) return false;
    const structures = room.lookForAt(LOOK_STRUCTURES, spot.x, spot.y);
    // 这个规划位上已经建成了它自己：这是"完成"，不是"被挡住"。放置循环会把 plan.ext 整个走一遍，
    // 所以每个建好的 extension 都会走到这里——过去它们全被记成 layoutBlocked，监控每轮报
    // 「方案位被旧建筑占住 20 处 extension@25,36<-extension」，其实一处冲突都没有。
    if (structures.some((structure) => structure.structureType === type)) return false;
    const blockers = structures.filter((structure) => !structuresCanShare(structure.structureType, type));
    if (blockers.length) {
        handleBlocked(room, spot, type, blockers);
        return false;
    }
    if (room.lookForAt(LOOK_CONSTRUCTION_SITES, spot.x, spot.y).length > 0) return false;
    return room.createConstructionSite(spot.x, spot.y, type) === OK;
}

function pending(room, type) {
    return room.find(FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === type).length;
}

/** 工地限流与漂移清理：容器在建 ≤ sitePace.containers（进度高的保留），道路只清漂移（在建数由放置端 sitePace.roads 限制，
 *  删规划内的道路工地只会丢进度），重规划后不在规划点上的移除。
 *  必须在计算 budget 之前执行——否则工地满时直接 return，清理永远轮不到，名额被死锁。 */
function sitePace() {
    return Object.assign({ roads: 8, ramparts: 6, walls: 2, containers: 2 }, config.sitePace || {});
}

function trimSites(room, plan) {
    const planned = {};
    const containerSpots = Object.assign({}, plan.containers || {});
    if (room.controller.level < 6) delete containerSpots.mineral;   // RCL6 前矿容器不算规划内，已有工地一并清掉
    planned[STRUCTURE_CONTAINER] = new Set(Object.values(containerSpots).filter(Boolean).map((p) => p.x + '.' + p.y));
    const roadSet = new Set();
    for (const key of Object.keys(plan.roads || {})) {
        const str = plan.roads && plan.roads[key];
        if (str) for (const p of unpackPath(str)) roadSet.add(p.x + '.' + p.y);
    }
    planned[STRUCTURE_ROAD] = roadSet;
    for (const type of [STRUCTURE_CONTAINER, STRUCTURE_ROAD]) {
        const sites = room.find(FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === type)
            .sort((a, b) => b.progress - a.progress);
        let keep = 0;
        const keepMax = type === STRUCTURE_ROAD ? Infinity : sitePace().containers;
        for (const s of sites) {
            const key = s.pos.x + '.' + s.pos.y;
            const progress = Math.max(0, Number(s.progress) || 0);
            const total = Math.max(0, Number(s.progressTotal) || 0);
            const highProgress = total > 0 && progress > total - progress;
            // 已投入过半的规划工地例外保留，即使当前在建数超过上限，避免丢失建设进度。
            if (planned[type].has(key) && highProgress) continue;
            if (keep < keepMax && planned[type].has(key)) { keep++; continue; }
            if (typeof s.remove === 'function') s.remove();
        }
    }
    // 外环推迟期间（RCL < rampartRingMinRcl）：零进度的裸地 rampart 工地清掉，把名额还给 extension/storage 和外矿/新房；
    // 盖在核心建筑上的保留，已有进度的保留（RCL 降级时不丢进度）
    if (!ringAllowed(room, plan)) {
        const core = new Set(coreRampartSpots(room).map((p) => p.x + '.' + p.y));
        for (const s of room.find(FIND_MY_CONSTRUCTION_SITES).slice()) {
            if (s.structureType !== STRUCTURE_RAMPART || (Number(s.progress) || 0) > 0) continue;
            if (core.has(s.pos.x + '.' + s.pos.y)) continue;
            if (typeof s.remove === 'function') s.remove();
        }
    }
    // 路要等 config.roadsMinRcl：门槛只挡新放的不够，存量也要还回去——3503001 上线后 W33S3/W31S5 仍各挂 24 条零进度的路，
    // 全账号停在 98。有进度的保留（RCL 降级时不丢进度）。遥测 Memory.rooms[房].roadsTrimmed
    if (room.controller.level < Math.max(1, Number(config.roadsMinRcl) || 1)) {
        let trimmed = 0;
        for (const s of room.find(FIND_MY_CONSTRUCTION_SITES).slice()) {
            if (s.structureType !== STRUCTURE_ROAD || (Number(s.progress) || 0) > 0) continue;
            if (typeof s.remove === 'function' && s.remove() === OK) trimmed++;
        }
        if (trimmed) {
            const mem = roomMem(room);
            mem.roadsTrimmed = (Number(mem.roadsTrimmed) || 0) + trimmed;
            mem.roadsTrimmedAt = Game.time;
        }
    }
}

/** 工地上限是每个玩家 100（所有房间 + 外矿 + 扩张共用）：母房只用到 100 − globalSiteReserve，
 *  给外矿容器/道路（remote.js 在 ≥100 时停放）和新房 spawn 工地（expansion.js 不检查 ERR_FULL）留名额 */
function globalSiteBudget() {
    const limit = typeof MAX_CONSTRUCTION_SITES === 'number' ? MAX_CONSTRUCTION_SITES : 100;
    const reserve = Math.max(0, Number(config.globalSiteReserve) || 0);
    const count = Game.constructionSites ? Object.keys(Game.constructionSites).length : 0;
    return Math.max(0, limit - reserve - count);
}

/** 扣掉留给外矿容器工地的 remoteContainerSiteReserve 后全局还剩几个名额：每房保底也只能放到这条线——remote.js 撤路腾出的名额
 *  下一轮 infraTick 才用得上，这 11 tick 里保底房会把它抢走（线上 2026-09-06 W32S8 撤了 5 条路仍放不出容器） */
function globalSiteHeadroom() {
    const limit = typeof MAX_CONSTRUCTION_SITES === 'number' ? MAX_CONSTRUCTION_SITES : 100;
    const reserve = Math.max(0, Number(config.remoteContainerSiteReserve) || 0);
    const count = Game.constructionSites ? Object.keys(Game.constructionSites).length : 0;
    return Math.max(0, limit - reserve - count);
}

/** rampart 建成只花 1 能量，但从 1 血开始衰减、全靠塔维修到 rampartTargetHits：没有塔或塔能量不足时不放新 rampart 工地（防线等塔） */
function rampartsAllowed(room) {
    const minEnergy = Math.max(0, Number(config.rampartTowerEnergy) || 0);
    const towers = room.find(FIND_MY_STRUCTURES, { filter: (s) => s.structureType === STRUCTURE_TOWER });
    return towers.some((t) => t.store && Number(t.store[RESOURCE_ENERGY] || 0) >= minEnergy);
}

/** 房养不养得起 min-cut 外环：每格 rampart 每 tick 衰减 RAMPART_DECAY_AMOUNT/RAMPART_DECAY_TIME = 3 血，
 *  84 格 = 252 血/tick；塔在射程 20 外只有 20 血/能量 ⇒ 12.6 能量/tick（builder 100 血/能量只要 2.5，
 *  但外环刚建成时比值 0.001%，塔按"离目标比例最低"选目标，会一直填它）。收入够不到
 *  config.rampartRingMinIncome 就先不铺——半圈 rampart 挡不住人却要付全额维护，而铺满外环的"填血"成本
 *  （84 格 × 目标血量 ÷ 100 血/能量）也要从同一份收入里出（线上 2026-09-09 W33S7 收入 8–30/tick，
 *  外环目标 30 万/格 = 25M 血 ≈ 25 万能量）。收入样本不足（新房）时视为不允许。 */
function rampartRingAffordable(room, mem) {
    const need = Math.max(0, Number(config.rampartRingMinIncome) || 0);
    if (!(need > 0)) return true;
    const track = mem && mem.spawnIncome;
    const samples = Math.max(1, Number((config.spawnQueue || {}).incomeSamples) || 200);
    return !!track && Number(track.n) >= samples && Number(track.ema || 0) >= need;
}

/** min-cut 外环（plan.ramparts，全是裸地）只在 RCL ≥ config.rampartRingMinRcl 且收入养得起时放；
 *  之前只给核心建筑盖 rampart（见 config 注释里的依据） */
function ringAllowed(room, plan) {
    const minRcl = Math.max(1, Number(config.rampartRingMinRcl) || 1);
    if (!(plan && Array.isArray(plan.ramparts) && plan.ramparts.length && room.controller.level >= minRcl)) return false;
    return rampartRingAffordable(room, roomMem(room));
}

/** 核心建筑（spawn/塔/storage/terminal）的位置：外环推迟期间 rampart 只盖这些 */
function coreRampartSpots(room) {
    return room.find(FIND_MY_SPAWNS).map((s) => s.pos)
        .concat(room.find(FIND_MY_STRUCTURES, { filter: (s) => s.structureType === STRUCTURE_TOWER || s.structureType === STRUCTURE_STORAGE || s.structureType === STRUCTURE_TERMINAL }).map((s) => s.pos));
}

/** 房里还有没有能建工地的 creep（builder/pioneer，含孵化中、不含退役中）：没有的话工地只会挂着占全局名额 */
function hasBuilder(room) {
    for (const creep of creepsHome(room.name)) {
        const memory = creep.memory;
        if (memory.role !== 'builder' && memory.role !== 'pioneer') continue;
        if (memory.retired || memory.bodyUpgradeRetiring) continue;
        return true;
    }
    return false;
}

/** 死房判定：房里有工地却连续 config.deadRoom.afterTicks 没有 builder/pioneer。builderSeenAt 首次见到房间时从现在起算（部署/重生后不误判）；
 *  没有工地的房不计时——没工地就不会有 builder 目标，否则新 RCL 解锁后永远放不出第一个工地 */
function deadRoom(room, mem) {
    const settings = config.deadRoom || {};
    const after = Math.max(0, Number(settings.afterTicks) || 0);
    if (!after) return false;
    if (hasBuilder(room) || mem.builderSeenAt == null || room.find(FIND_MY_CONSTRUCTION_SITES).length === 0) mem.builderSeenAt = Game.time;
    return Game.time - mem.builderSeenAt >= after;
}

/** 死房只留 keep 个进度最高的工地（spawn 工地永远保留：新房/重生靠它；源/控制器容器工地也保留：
 *  静态矿工没 CARRY 建不了容器，恢复完全靠 builder 建这些工地。88fe9e7 两个死房各 27–30 个工地占满全局名额，
 *  裁掉路/extension 是对的，但把容器工地一起裁掉就再也采不起来）。 */
function trimDeadRoomSites(room) {
    const keep = Math.max(0, Number((config.deadRoom || {}).keep) || 0);
    const sites = room.find(FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType !== STRUCTURE_SPAWN &&
        s.structureType !== STRUCTURE_CONTAINER)
        .sort((a, b) => (Number(b.progress) || 0) - (Number(a.progress) || 0));
    let removed = 0;
    for (const site of sites.slice(keep)) {
        if (typeof site.remove === 'function' && site.remove() === OK) removed++;
    }
    return removed;
}

/** 死房仍补缺失的核心容器工地：place() 在 deadRoom 时直接 return，否则容器被裁掉后永远放不回来。 */
function placeCoreContainerSites(room, mem) {
    const plan = mem && mem.plan;
    if (!plan || !plan.containers) return 0;
    let placed = 0;
    for (const key of ['src0', 'src1', 'ctrl']) {
        if (plan.containers[key] && trySite(room, plan.containers[key], STRUCTURE_CONTAINER)) placed++;
    }
    return placed;
}

/** 房里一个我们的 spawn 都没有（新占的房、或刚拆掉占配额的敌方 spawn）：spawn 工地排在一切之前、死房也放。
 *  否则按常规顺序它排在容器/道路/extension 之后，名额被前面吃光就永远轮不到，房间只能靠外援 pioneer 吊着。 */
function placeFirstSpawn(room, plan) {
    if (!plan || !Array.isArray(plan.spawns) || !plan.spawns.length) return false;
    if (room.find(FIND_MY_SPAWNS).length || pending(room, STRUCTURE_SPAWN) > 0) return false;
    if ((allowance(room).spawn || 0) - countType(room, STRUCTURE_SPAWN) <= 0) return false;
    for (const spot of plan.spawns) {
        if (trySite(room, spot, STRUCTURE_SPAWN)) return true;
    }
    return false;
}

function place(room, mem) {
    const plan = mem.plan;
    if (!plan) return;
    if (placeFirstSpawn(room, plan)) mem.layoutFirstSpawn = Game.time;
    if (deadRoom(room, mem)) {
        const removed = trimDeadRoomSites(room);
        const containers = placeCoreContainerSites(room, mem);
        if (removed || containers) mem.layoutDeadTrim = { at: Game.time, removed, containers };
        return;
    }
    blockedThisRun = [];
    let fullPass = false;
    try {
        fullPass = placeSites(room, mem, plan) !== false;
    } finally {
        // 工地名额满时本轮没有尝试放置，冲突记录保留上一轮的结果，不要误删
        if (fullPass) {
            if (blockedThisRun.length) mem.layoutBlocked = blockedThisRun;
            else delete mem.layoutBlocked;
        }
        blockedThisRun = null;
    }
}

/** 高优先结构（extension/塔/storage/spawn/link/terminal/lab）配额未满且有方案位可放，但名额被零进度的路/rampart/墙工地占满：
 *  让出最多 2 个零进度低优先工地（迁移期拆掉 extension 后替代工地才放得出来）。 */
/** 高优先结构（extension/塔/storage/terminal/lab/spawn）配额未满且方案位空着、可放的数量 */
function highPriorityNeeds(room, plan, allow) {
    const highTypes = [
        ['extension', STRUCTURE_EXTENSION, plan.ext || []],
        ['tower', STRUCTURE_TOWER, plan.towers || []],
        ['storage', STRUCTURE_STORAGE, plan.storage ? [plan.storage] : []],
        ['terminal', STRUCTURE_TERMINAL, plan.terminal ? [plan.terminal] : []],
        ['lab', STRUCTURE_LAB, plan.labs || []],
        ['spawn', STRUCTURE_SPAWN, plan.spawns || []],
        // link 位（src 是 src0 的别名，去重）：名额被零进度的路/rampart 占满时 link 也该让位放出
        ['link', STRUCTURE_LINK, ['ctrl', 'src0', 'src1', 'store', 'aux0', 'aux1'].map((key) => linkSpot(plan, key)).filter(Boolean)],
    ];
    let needs = 0;
    for (const [key, type, spots] of highTypes) {
        const remaining = (allow[key] || 0) - countType(room, type);
        if (remaining <= 0) continue;
        const free = spots.filter((spot) => spot && !structureAt(room, spot.x, spot.y, type) && !siteAt(room, spot.x, spot.y, type) &&
            !room.lookForAt(LOOK_STRUCTURES, spot.x, spot.y).some((s) => !structuresCanShare(s.structureType, type))).length;
        needs += Math.min(remaining, free);
    }
    return needs;
}

function yieldLowPrioritySites(room, plan, allow) {
    if (highPriorityNeeds(room, plan, allow) <= 0) return false;
    const lowTypes = new Set([STRUCTURE_ROAD, STRUCTURE_RAMPART, STRUCTURE_WALL]);
    let freed = 0;
    for (const site of room.find(FIND_MY_CONSTRUCTION_SITES).slice()) {
        if (freed >= 2) break;
        if (!lowTypes.has(site.structureType) || (site.progress || 0) > 0 || typeof site.remove !== 'function') continue;
        if (site.remove() === OK) freed++;
    }
    return freed > 0;
}

/** 方案里还没建成、也没在建的道路格数（含外矿路段的母房段）：道路是唯一会因为衰减而永久消失的规划结构 */
function missingRoadTiles(room, plan) {
    if (!plan || !plan.roads) return 0;
    const seen = new Set();
    let missing = 0;
    for (const str of Object.values(plan.roads)) {
        if (!str) continue;
        for (const p of unpackPath(str)) {
            const key = p.x + '.' + p.y;
            if (seen.has(key)) continue;
            seen.add(key);
            if (structureAt(room, p.x, p.y, STRUCTURE_ROAD) || siteAt(room, p.x, p.y, STRUCTURE_ROAD)) continue;
            missing++;
        }
    }
    return missing;
}

/** 工地名额满、方案里却有路没建成：让出最多 2 个零进度的 rampart/wall 工地给路。
 *  rampart 工地只有 1 点进度（建成就 1 血，之后全靠塔维修，是维修负担不是建造负担），而一条衰减到 0 的路要 300–1500 能量重建；
 *  工地名额是每玩家 100 的全局资源，名额被几十个零进度外环 rampart 占满时路永远补不回来。
 *  线上 2026-09-09 W33S7：40/40 名额 = terminal + 3 lab + 36 外环 rampart，方案里 89 格路只剩 61 格、34 格消失后无法重建。
 *  让出后下一次 layout.run 会按既有顺序（容器 → link → 道路）把路工地放出来，外环等名额富余时再回来。 */
function yieldRampartSitesForRoads(room, plan) {
    if (missingRoadTiles(room, plan) <= 0) return false;
    // 核心建筑（spawn/塔/storage/terminal）上的 rampart 工地保留：那是真正的防护，不是外环占位
    const core = new Set(coreRampartSpots(room).map((p) => p.x + '.' + p.y));
    let freed = 0;
    for (const site of room.find(FIND_MY_CONSTRUCTION_SITES).slice()) {
        if (freed >= 2) break;
        if (site.structureType !== STRUCTURE_RAMPART && site.structureType !== STRUCTURE_WALL) continue;
        if ((site.progress || 0) > 0 || typeof site.remove !== 'function') continue;
        if (core.has(site.pos.x + '.' + site.pos.y)) continue;
        if (site.remove() === OK) freed++;
    }
    return freed > 0;
}

function placeSites(room, mem, plan) {
    normalizeLinkPlan(room, plan);
    const allow = allowance(room);
    trimSites(room, plan);
    const own = room.find(FIND_MY_CONSTRUCTION_SITES).length;
    // 每房保底 siteFloorPerRoom：全局名额被外矿路/别的房占满时本房仍可放到保底数（引擎 100 上限放不下就 ERR_FULL，trySite 返回 false）
    const floor = Math.max(0, Number(config.siteFloorPerRoom) || 0);
    // 保底不吃外矿容器的保留名额（globalSiteHeadroom）
    let budget = Math.min(config.maxSites - own, Math.max(globalSiteBudget(), Math.min(floor - own, globalSiteHeadroom())));
    // site.remove() 下一 tick 才生效：让出名额后本轮不再放置，否则按"虚"名额又放一批路/rampart（线上曾堆到 21 个 rampart 工地）
    if (budget <= 0 && yieldLowPrioritySites(room, plan, allow)) { mem.layoutYield = Game.time; return false; }
    // 高优先结构不缺、但方案里的路没建成：把零进度的 rampart/wall 工地让给路（见 yieldRampartSitesForRoads）
    if (budget <= 0 && yieldRampartSitesForRoads(room, plan)) { mem.layoutYield = Game.time; return false; }
    if (budget <= 0) return false;
    const types = {
        spawn: STRUCTURE_SPAWN,
        extension: STRUCTURE_EXTENSION,
        tower: STRUCTURE_TOWER,
        storage: STRUCTURE_STORAGE,
        link: STRUCTURE_LINK,
        terminal: STRUCTURE_TERMINAL,
        lab: STRUCTURE_LAB,
        extractor: STRUCTURE_EXTRACTOR,
        observer: STRUCTURE_OBSERVER,
        powerSpawn: STRUCTURE_POWER_SPAWN,
        nuker: STRUCTURE_NUKER,
        factory: STRUCTURE_FACTORY,
        container: STRUCTURE_CONTAINER,
        road: STRUCTURE_ROAD,
        rampart: STRUCTURE_RAMPART,
        wall: STRUCTURE_WALL,
    };
    const keys = {};
    for (const key in types) keys[types[key]] = key;
    const need = (value) => {
        const key = allow[value] != null ? value : keys[value];
        if (!key || allow[key] == null) return 0;
        return Math.max(0, allow[key] - countType(room, types[key]));
    };

    // 优先级：源容器 → link → storage → terminal → 道路 → extension → 塔 → 提取器 → lab → 额外 spawn → RCL7/8 杂项 → rampart
    // （storage/terminal 提前见下方 oneOffBeforeRoads；关掉时退回旧顺序：塔之后才放）
    // 道路垫底：路网数十格且配额近乎无限，排在前面会占满 maxSites 并在每次空位释放时抢先补位，
    // 高价值结构永远排不上（RCL2 放不出 extension 工地的根因）。容器/道路在建各限 2 个。
    let cPending = pending(room, STRUCTURE_CONTAINER);
    // 矿容器要等 extractor（RCL6）：提前放只会花 5000 能量建一个没人用的容器
    const containerKeys = ['src0', 'src1', 'ctrl']; // Mineral miners carry their own output.
    for (const key of containerKeys) {
        if (need('container') <= 0 || budget <= 0) break;
        // 在建配额只限控制器/矿容器：源容器是收入的根（线上 W33S7 容器衰减后 src0 的工地被 src1 + ctrl 两个在建挡住放不出来）
        if (key !== 'src0' && key !== 'src1' && cPending >= sitePace().containers) break; // 给 extension 等高优先结构留名额
        if (plan.containers[key] && trySite(room, plan.containers[key], STRUCTURE_CONTAINER)) { budget--; cPending++; }
    }
    // link 先于道路与 extension：RCL5+ 一座 link（5000）把一个源或控制器的运输整段交给 link，顶得上几只 hauler；配额只有 2–6 个占不了多少名额。
    // 基准 W34S7（d03395d 分叉）：RCL6 全程 20k tick 房内 10 个名额全是 extension 工地，link 工地到分叉后 24k tick 才放出。
    // RCL5 ctrl+src0，RCL6 加 src1，RCL7 再补 storage。legacy src 仅作为 src0 兼容别名。
    if (need('link') > 0 && budget > 0) {
        // extension 还缺时至少给它留 1 个名额：让位机制一次只腾 2 个，link 与 ext 各得 1，否则 ext 永远排不上
        let linkBudget = need('extension') > 0 ? budget - 1 : budget;
        for (const key of ['ctrl', 'src0', 'src1', 'store', 'aux0', 'aux1']) {
            if (need('link') <= 0 || linkBudget <= 0) break;
            const spot = linkSpot(plan, key);
            if (trySite(room, spot, STRUCTURE_LINK)) { budget--; linkBudget--; }
        }
    }
    // 一次性的 storage / terminal 排在道路与 extension **之前**（config.construction.oneOffBeforeRoads）。
    // 依据（overmind-absorb 55183d1 + 924a8c8；docs/benchmarks/2026-09-07-layout-order-ab-round10.md）：0→RCL8 基准 t=1.16M、
    // 六个房已 RCL7 时全账号 terminal 0 座。terminal 正好在 RCL6 解锁，而同一刻 extension 上限 30→40 多出 10 个名额，
    // 两个窗口完全重合：道路 + 新 extension 把这一轮的名额吃光，terminal 要等 extension 全部建完才排得上（晚几万 tick）。
    // 1 个名额换一整条子系统（storage：物流与升级供给；terminal：industry.canSpend 与跨房能量的前提），与 link 提前同理。
    // 只提前 storage/terminal：lab/factory/nuker 仍走下面的奢侈门槛（utils.luxuryAllowed），提取器仍等大脑的矿物方案。
    // 提前放不会把 builder 从 extension 上拉走：builder.sitePriority 里 terminal 与 extension 同为默认档 10、
    // 同档按剩余进度从小到大（extension 3000 先于 terminal 10 万）；无 storage 时 storage 本来就排在道路前（storageBeforeRoads）。
    // extension 还缺时至少给它留 1 个名额（与 link 同一套让位规则）：拆迁/让位腾出的名额必须放得出替代 extension
    const oneOffFirst = (config.construction || {}).oneOffBeforeRoads !== false;
    // 本 tick 早轮已放出的一次性建筑：room.find / lookForAt 与 createConstructionSite 的运行时检查都只看 tick 开头的对象，
    // 兜底轮按旧快照 need() 仍缺、同格再放也拿到 OK（处理器才丢掉重复）——白花一个名额，还写一条假的 oneOffLeftover（2026-10-14 复审）
    const oneOffPlaced = new Set();
    const placeOneOffs = (early) => {
        let oneOffBudget = early && need('extension') > 0 ? budget - 1 : budget;
        for (const [key, type] of [['storage', STRUCTURE_STORAGE], ['terminal', STRUCTURE_TERMINAL]]) {
            if (need(key) <= 0 || oneOffBudget <= 0 || !plan[key]) continue;
            if (oneOffPlaced.has(key)) {
                // 遥测：兜底轮还有名额、旧快照里仍缺，旧代码会在这里同格重放（生效断言 layout.oneOffSameTickDedupe）
                mem.oneOffDeduped = { at: Game.time, type: key, budget: oneOffBudget };
                continue;
            }
            if (!trySite(room, plan[key], type)) continue;
            oneOffPlaced.add(key);
            budget--; oneOffBudget--;
            // 遥测：提前放出时 extension 还缺几个（生效断言 layout.oneOffBeforeRoads 看 extNeed > 0 时 terminal 照样放出）
            if (early) mem.oneOffAhead = { at: Game.time, type: key, extNeed: need('extension'), level: room.controller.level };
            // 遥测：提前开着、却是兜底轮放出的（留给 extension 的名额没人用；生效断言 layout.oneOffLeftover）
            else if (oneOffFirst) mem.oneOffLeftover = { at: Game.time, type: key, extNeed: need('extension'), level: room.controller.level };
        }
    };
    if (oneOffFirst) placeOneOffs(true);
    // 道路优先：路网决定 hauler 的运力（有路 MOVE 减半），先于 extension 放（每轮/在建数受 sitePace.roads 限制）；
    // 但 RCL < config.roadsMinRcl 的新房建不动路（只有 pioneer/builder 在建 spawn 与 extension），放了也是零进度占死全账号名额
    if (budget > 0 && room.controller.level >= Math.max(1, Number(config.roadsMinRcl) || 1)) {
        const rPendingFirst = pending(room, STRUCTURE_ROAD);
        let roadBudget = Math.min(budget, sitePace().roads - rPendingFirst);
        // 上一轮刚让出名额：这轮留给配额未满的高优先结构，路网不得抢先补位（旧代码只是靠名额富余才碰巧放得出替代 extension）
        if (mem.layoutYield != null && Game.time - mem.layoutYield <= config.layoutInterval * 3) {
            roadBudget = Math.min(roadBudget, budget - Math.min(budget, highPriorityNeeds(room, plan, allow)));
        }
        if (roadBudget > 0) budget -= placeRoads(room, plan, roadBudget);
    }
    delete mem.layoutYield;
    if (need('extension') > 0 && budget > 0) {
        let missing = need('extension');
        for (const spot of plan.ext || []) {
            if (missing <= 0 || budget <= 0) break;
            if (trySite(room, spot, STRUCTURE_EXTENSION)) { missing--; budget--; }
        }
    }
    if (need('tower') > 0 && budget > 0) {
        let missing = need('tower');
        for (const spot of plan.towers || []) {
            if (missing <= 0 || budget <= 0) break;
            if (trySite(room, spot, STRUCTURE_TOWER)) { missing--; budget--; }
        }
    }
    // 兜底轮（提前开着也要跑）：提前那一轮给 extension 留的 1 个名额，若 extension 方案位放不出（被挡等拆迁 / 方案位不够）、
    // 塔也不缺，就在这里给 storage/terminal——旧顺序本来就把塔之后剩下的名额给它们，提前只该更早、不能更晚（2026-10-13 复审）
    placeOneOffs(false);
    // 奢侈建筑（lab/factory/nuker/powerSpawn；terminal 不设门槛）等 storage 过了经济门槛再放（utils.luxuryAllowed）
    const luxuryOk = utils.luxuryAllowed(room);
    if (!luxuryOk && need('lab') > 0) {
        // 遥测：奢侈建筑因 storage 没过门槛而没放工地
        mem.luxuryHeld = { at: Game.time, storage: room.storage ? Number(room.storage.store[RESOURCE_ENERGY] || 0) : 0 };
    }
    if (need('extractor') > 0 && budget > 0) {
        const mineralPlan = brain.get(room.name, 'mineral', null);
        if (mineralPlan && mineralPlan.build && mineralPlan.pos &&
            trySite(room, mineralPlan.pos, STRUCTURE_EXTRACTOR)) budget--;
    }
    if (luxuryOk && need('lab') > 0 && budget > 0) {
        let missing = need('lab');
        for (const spot of plan.labs || []) {
            if (missing <= 0 || budget <= 0) break;
            if (trySite(room, spot, STRUCTURE_LAB)) { missing--; budget--; }
        }
    }
    if (need('spawn') > 0 && budget > 0) {
        // 没有任何 spawn（刚占下的房）时先放蓝图/规划指定的 spawn1；wheel 布局的 spawns 也在这里
        const first = (plan.wheel || !room.find(FIND_MY_SPAWNS).length) && plan.spawns ? plan.spawns : [];
        const spawnPositions = first.concat(plan.spawn2 || [], plan.spawn3 || []);
        for (const spot of spawnPositions) {
            if (need('spawn') <= 0 || budget <= 0) break;
            if (trySite(room, spot, STRUCTURE_SPAWN)) budget--;
        }
    }
    if (room.controller.level >= 7 && budget > 0) {
        const miscTypes = [STRUCTURE_FACTORY, STRUCTURE_OBSERVER, STRUCTURE_NUKER, STRUCTURE_POWER_SPAWN];
        const structureKeys = {};
        structureKeys[STRUCTURE_FACTORY] = 'factory';
        structureKeys[STRUCTURE_OBSERVER] = 'observer';
        structureKeys[STRUCTURE_NUKER] = 'nuker';
        structureKeys[STRUCTURE_POWER_SPAWN] = 'powerSpawn';
        for (const t of miscTypes) {
            if (need(t) <= 0 || budget <= 0) continue;
            if (utils.luxuryStructure(t) && !luxuryOk) continue;
            const planned = plan.structures && plan.structures[structureKeys[t]];
            if (planned && trySite(room, planned, t)) { budget--; continue; }
            for (const spot of plan.misc || []) {
                if (need(t) <= 0 || budget <= 0) break;
                if (trySite(room, spot, t)) budget--;
            }
        }
    }
    // 完整 min-cut 防线分批落地（有塔且塔能量充足才放，见 rampartsAllowed；RCL ≥ rampartRingMinRcl 才放外环，见 ringAllowed）；
    // 外环推迟期间或旧计划没有 perimeter 时只保护核心建筑。
    if (room.controller.level >= 2 && budget > 0 && rampartsAllowed(room)) {
        if (ringAllowed(room, plan)) {
            let placed = 0;
            for (const spot of plan.ramparts) {
                if (placed >= sitePace().ramparts || budget <= 0) break;
                if (structureAt(room, spot.x, spot.y, STRUCTURE_RAMPART) || siteAt(room, spot.x, spot.y, STRUCTURE_RAMPART)) continue;
                if (trySite(room, spot, STRUCTURE_RAMPART)) { placed++; budget--; }
            }
        } else if (room.controller.level >= 3) {
            const cores = coreRampartSpots(room);
            let n = 0;
            for (const pos of cores) {
                if (n >= 2 || budget <= 0) break;
                if (structureAt(room, pos.x, pos.y, STRUCTURE_RAMPART) || siteAt(room, pos.x, pos.y, STRUCTURE_RAMPART)) continue;
                if (room.createConstructionSite(pos.x, pos.y, STRUCTURE_RAMPART) === OK) { n++; budget--; }
            }
        }
    }
    if (room.controller.level >= 2 && budget > 0 && plan.walls && plan.walls.length) {
        let placed = 0;
        for (const spot of plan.walls) {
            if (placed >= sitePace().walls || budget <= 0) break;
            if (structureAt(room, spot.x, spot.y, STRUCTURE_WALL) || siteAt(room, spot.x, spot.y, STRUCTURE_WALL)) continue;
            if (trySite(room, spot, STRUCTURE_WALL)) { placed++; budget--; }
        }
    }
}

/** 没有轮子方案的房：bucket 够且不在重试冷却期时跑一次轮子。旧的 d1 蓝图/过渡布局一律作废——轮子是唯一规划来源。 */
function maybeGenerateWheelPlan(room, mem) {
    if (!wheelLayout.shouldGenerate(mem)) return false;
    return wheelLayout.generate(room, mem).ok;
}

/** 前三个 lab 必须能真的反应。
 *  runReaction 要求两个输入 lab 都在输出 lab 的切比雪夫 2 以内（引擎
 *  processor/intents/labs/run-reaction.js：|dx| > 2 || |dy| > 2 直接拒绝；docs/game/resources.md
 *  同样写着 "within the range of 2 squares"）。RCL6 只给 3 个 lab 名额，而轮子给的 lab 列表是任意顺序：
 *  用我们自己的三个固定件验算，W34S7 的前三个两两距离 3/4/1（没有合法输出 lab）、样例房同样失败，
 *  三个方案里却都存在可用三连——纯排序问题，不是规划器能力问题。
 *  已经可用就不动（保持稳定，不打乱已建成的顺序）。 */
function normalizeLabPlan(plan) {
    const labs = plan && plan.labs;
    if (!Array.isArray(labs) || labs.length < 3) return;
    const cheb = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
    const reactable = (list) => list.some((out, i) => list.every((other, k) => k === i || cheb(out, other) <= 2));
    if (reactable(labs.slice(0, 3))) return;
    // 选"两格内邻居最多"的那个当输出 lab：后续 RCL7/8 加 lab 时它还能继续当输出
    let best = null;
    for (const out of labs) {
        const near = labs.filter((other) => other !== out && cheb(out, other) <= 2);
        if (near.length >= 2 && (!best || near.length > best.near.length)) best = { out, near };
    }
    if (!best) return;   // 方案里根本没有合法三连：保持原样，别把顺序搅乱
