'use strict';
/** 建造工：建工地 → 修破损 → 无事时升级（storage 富余才升，避免抢升级工的能量） */
const config = require('config');
const layout = require('layout');
const movement = require('movement');
const taskBroker = require('task_broker');
const { findCached, logErr, needsRepair, criticallyDamaged, energySurplus, creepsHomeRole, compareRepairTargets, isRetiring, spawnWaitingFor, siteWanted } = require('utils');

const runtimeGlobal = typeof global !== 'undefined' ? global : {};
const fallbackBudgetState = runtimeGlobal.__roleEnergyFallbackBudget ||
    (runtimeGlobal.__roleEnergyFallbackBudget = { tick: -1, rooms: {} });

function damagedStructure(room) {
    // 只修真正值得修的（rampart 按 RCL 目标封顶），按相对目标的血量比例从低到高
    const usable = findCached(room, FIND_STRUCTURES).filter((s) => needsRepair(room, s));
    return usable.length ? usable.sort((a, b) => compareRepairTargets(room, a, b))[0] : null;
}

/** 危急结构（utils.criticallyDamaged：容器/道路烂到 0 就消失，重建 300–5000 能量）：每 tick 每房只扫一次。
 *  有工地在建时 builder 永远在建造，普通维修轮不到它——只有"会消失的"才插队到建造之前。
 *  线上 2026-09-09 W33S7：60 条路全在衰减（16 条 < 500 血）、40 个工地没完，塔停在储备线上一次也修不动，
 *  于是道路只能靠衰减到 0 再从工地重建（300–1500 能量），而维修 100 血只要 1 能量。 */
const criticalCache = { time: -1, rooms: {} };
function criticalList(room) {
    if (criticalCache.time !== Game.time) { criticalCache.time = Game.time; criticalCache.rooms = {}; }
    if (criticalCache.rooms[room.name] !== undefined) return criticalCache.rooms[room.name];
    const list = findCached(room, FIND_STRUCTURES).filter((s) => criticallyDamaged(room, s));
    criticalCache.rooms[room.name] = list;
    return list;
}

/** 控制器/仓库 link 能借给 builder 的余量：低于 linkKeepAt + 这个数就不动它（那是升级者的缓冲）。
 *  一车 250 能量 = 升级者 25 tick 的量，留 250 的余量意味着借完还有 25 tick 缓冲，源 link 会在这期间补上。 */
function linkDrawMargin() {
    return Math.max(100, Number(config.linkDrawMargin) || 250);
}

/** builder 的取能点（按路径距离取**最近**的一个）。旧写法是"先容器、容器都没有才 storage、再 spawn/ext"——
 *  顺序与距离无关：线上 W33S7 的 builder 走 20 格去源容器取 170 能量，而身边的 storage 有 276、控制器 link 有 799。
 *  时间才是 builder 的瓶颈（6 WORK 建 30 进度/tick，一车 176 能量只要 6 tick 就建完，来回 40 格白扔 40 tick）。
 *  候选：
 *   - 非控制器容器 ≥50（控制器容器要 ≥ ctrlShare 满，缓冲留给升级者）
 *   - storage ≥50（reserve 只约束升级者，builder 拿的是仓里闲置的部分）
 *   - 控制器 link / 仓库 link ≥ linkKeepAt + linkDrawMargin：RCL6 没有 store link 时升级者吃不满的源收入
 *     全堵在 link 里（线上 W33S7 三座 link 常年 800/800），那部分能量只有升级者能用，而升级者只要 10/tick */
/** spawn 队头正在攒能量、而现有能量不够（utils.spawnWaitingFor）：这时 builder 不跟 spawn 抢能量。
 *  线上 2026-09-11 W33S7：队头 core:builder:1（1350）等了 400–670 tick、挡住 hauler 与外矿换代，
 *  同一时间 builder 从 ctrl link、源容器和 spawn/ext 余量取能去建 terminal——spawn 攒不起来，ETA 永远兑现不了。
 *  饥饿时 builder 只拿 storage 里 spawn 缺口以外的部分、已经溢出的源容器，以及 hauler 投递。 */
function spawnHungry(room) {
    const hungry = spawnWaitingFor(room);
    if (hungry) {
        // 遥测：builder 为 spawn 让路的 tick 数（每 tick 每房记一次）
        const mem = Memory.rooms[room.name];
        if (mem && (!mem.builderHunger || mem.builderHunger.at !== Game.time)) {
            mem.builderHunger = { at: Game.time, n: (Number(mem.builderHunger && mem.builderHunger.n) || 0) + 1 };
        }
    }
    return hungry;
}

function spawnShortfall(room) {
    const waiting = (Memory.rooms[room.name] || {}).spawnWaiting;
    return waiting && waiting.cost > 0 ? Math.max(0, waiting.cost - room.energyAvailable) : 0;
}

function energySourceFor(creep, room, ctrlShare) {
    const linkKeep = Math.max(0, Number(config.linkKeepAt) || 0) + linkDrawMargin();
    const hungry = spawnHungry(room);
    const shortfall = hungry ? spawnShortfall(room) : 0;
    // 源容器"溢出"线：hauler 跟不上时容器会涨过它，那部分 builder 拿走不影响 spawn 的补给
    const overflowAt = Math.max(0, Number((config.hauling || {}).sourceLinkOverflow) || 1500);
    const candidates = findCached(room, FIND_STRUCTURES).filter((s) => {
        if (!s || !s.store || s.my === false) return false;
        const energy = Number(s.store[RESOURCE_ENERGY] || 0);
        if (energy < 50) return false;
        if (s.structureType === STRUCTURE_CONTAINER) {
            if (isControllerContainer(room, s)) return energy >= s.store.getCapacity(RESOURCE_ENERGY) * ctrlShare;
            return !hungry || energy >= overflowAt;
        }
        if (s.structureType === STRUCTURE_STORAGE) return !hungry || energy - shortfall >= 50;
        if (s.structureType === STRUCTURE_LINK) {
            if (hungry) return false;
            // 只借收货端的 link（ctrl / store），不动源 link——那是链路的发送端，抽它等于掐断升级者的供给
            const plan = (Memory.rooms[room.name] || {}).plan;
            if (!plan || !plan.links) return false;
            const spot = layout.linkSpot(plan, 'ctrl') || {};
            const storeSpot = layout.linkSpot(plan, 'store') || {};
            const isReceiver = (s.pos.x === spot.x && s.pos.y === spot.y) || (s.pos.x === storeSpot.x && s.pos.y === storeSpot.y);
            return isReceiver && energy >= linkKeep;
        }
        return false;
    });
    return creep.pos.findClosestByPath(candidates) || null;
}

/** controller 供能容器（规划位；无规划时以贴近 controller 且不贴 source 判断）——builder 不得抽取 */
function isControllerContainer(room, structure) {
    if (!structure || structure.structureType !== STRUCTURE_CONTAINER) return false;
    const plan = (Memory.rooms[room.name] || {}).plan;
    const planned = plan && plan.containers && plan.containers.ctrl;
    if (planned) return structure.pos.x === planned.x && structure.pos.y === planned.y;
    if (!room.controller || !structure.pos.inRangeTo(room.controller.pos, 2)) return false;
    return !findCached(room, FIND_SOURCES).some((source) =>
        Math.max(Math.abs(source.pos.x - structure.pos.x), Math.abs(source.pos.y - structure.pos.y)) <= 1);
}

/** 危急结构里挑这只 builder 该去修的：**先修伸手就够得着的**，再去全局最危急的那一个。
 *  只看全局比例会让两只都在危急线附近的结构把 builder 来回拽——一次维修只花 1–2 tick、走开再回来要 20+ tick，
 *  而修一 tick 后排名就翻转（线上 W33S7 2026-09-10：swamp 路 (31,25) 19.6% 与矿物容器 (19,40) 19.0% 相距 20 格，
 *  builder 一直在路上）。自我收敛：修到危急线以上它就不再是危急结构，下一 tick 自然重新评估，
 *  所以"就近先修"不会把更危急的远处目标永久饿死。 */
function criticalNear(creep, room) {
    const list = criticalList(room);
    if (!list.length) return null;
    let here = null;
    for (const structure of list) {
        if (!creep.pos.inRangeTo(structure.pos, 3)) continue;
        if (!here || compareRepairTargets(room, structure, here) < 0) here = structure;
    }
    if (here) return here;
    return list.slice().sort((a, b) => compareRepairTargets(room, a, b))[0];
}

/** 危急结构开修之后接着修（滞回）：修到普通维修线 towerRepairBelow（或手里能量用完）才回去建造。
 *  以前修到危急线（criticalRepairShare 20%）以上一点就走，衰减几百 tick 又跌回来——线上 W33S7 方案内道路 54/89 条停在 20–30%
 *  （9 条贴着 20–21.6%）、W33S8 49/80 条，builder 在工地和同一批路之间来回拉扯，每次只修 1–2 tick、往返 20+ tick。
 *  目标记在 creep.memory.repairId；遥测 Memory.rooms[房].builderRepairHold（危急线以上仍接着修的 tick 数） */
function repairHold(creep, room) {
    const id = creep.memory.repairId;
    if (!id) return null;
    const target = Game.getObjectById(id);
    const line = Number(config.towerRepairBelow) || 0.6;
    if (!target || !target.pos || target.pos.roomName !== room.name || target.structureType === STRUCTURE_RAMPART ||
        target.structureType === STRUCTURE_WALL || !(target.hits < target.hitsMax * line)) {
        delete creep.memory.repairId;
        return null;
    }
    if (!criticallyDamaged(room, target)) {
        const mem = Memory.rooms[room.name];
        if (mem && (!mem.builderRepairHold || mem.builderRepairHold.at !== Game.time)) {
            mem.builderRepairHold = { at: Game.time, n: (Number(mem.builderRepairHold && mem.builderRepairHold.n) || 0) + 1, id: target.id };
        }
    }
    return target;
}

function samePosition(left, right) {
    return !!left && !!right && left.x === right.x && left.y === right.y;
}

/** 工地优先级（与 task_broker 的建造权重一致）：塔（替换旧塔后的无塔窗口要短）> 源/控制器容器 > 无 storage 时的 storage 工地
 *  > 道路（路网决定运力，用户要求道路优先）> 其它结构（extension…按剩余进度小的先）> rampart/墙 */
function sitePriority(room, site) {
    const plan = (Memory.rooms[room.name] || {}).plan || {};
    const containers = plan.containers || {};
    // spawn 永远最先：没有 spawn 什么都孵不出来（2026-09-06 用户指令；线上新房 W31S6/W31S8 的 builder 在修 24 条路，spawn 工地排在默认档）
    if (site.structureType === STRUCTURE_SPAWN) return -1;
    // 容量还小（<550，RCL3 没建够 extension）时 5000 的塔会把所有 extension 卡在后面：先扩容再建塔
    if (site.structureType === STRUCTURE_TOWER) return room.energyCapacityAvailable >= 550 ? 0 : 10;
    if (site.structureType === STRUCTURE_CONTAINER) {
        if (samePosition(site.pos, containers.src0) || samePosition(site.pos, containers.src1)) return 1;
        if (samePosition(site.pos, containers.ctrl)) return 2;
        return 3;
    }
    // link 排在源容器之后、控制器容器/道路/extension 之前：基准 W34S7 的四个 link 工地放出后 0/5000 躺了 5k tick，builder 一直在做有进度的 ext
    if (site.structureType === STRUCTURE_LINK) return 1.5;
    // 容量 <550（RCL2 的 5 个 extension 还没建）时 extension 排在道路前：容量翻倍所有身体才翻倍，
    // 线上 W35S7 两只 1 WORK 的 builder 在远角修路，5 个 extension 工地 0 进度 4000 tick
    if (site.structureType === STRUCTURE_EXTENSION && room.energyCapacityAvailable < 550) return 4;
    // 没有 storage 的房：storage 工地排在道路前（config.construction.storageBeforeRoads）
    if (site.structureType === STRUCTURE_STORAGE && !room.storage && (config.construction || {}).storageBeforeRoads !== false) return 4.5;
    if (site.structureType === STRUCTURE_ROAD) return 5;
    if (site.structureType === STRUCTURE_RAMPART || site.structureType === STRUCTURE_WALL) return 20;
    return 10;
}

function nextSite(room) {
    // 没过经济门槛的奢侈工地（terminal/lab…，utils.siteWanted）不建：能量先攒进 storage
    return findCached(room, FIND_MY_CONSTRUCTION_SITES).filter((site) => siteWanted(room, site)).sort((left, right) => {
        const priority = sitePriority(room, left) - sitePriority(room, right);
        if (priority !== 0) return priority;
        return (left.progressTotal - left.progress) - (right.progressTotal - right.progress);
    })[0];
}

function withdrawRoomSurplus(creep, room, state) {
    if (state.recovering) return false;
    // spawn 在为队头攒能量：余量正是它要攒的那笔，不能拿走（见 spawnHungry）
    if (spawnHungry(room)) return false;
    if (fallbackBudgetState.tick !== Game.time) {
        fallbackBudgetState.tick = Game.time;
        fallbackBudgetState.rooms = {};
    }
    if (fallbackBudgetState.rooms[room.name] == null) {
        const reserve = Math.min(room.energyCapacityAvailable,
            config.recovery && config.recovery.emergencyHarvestBelow || 200);
        fallbackBudgetState.rooms[room.name] = Math.max(0, room.energyAvailable - reserve);
    }
    const amount = Math.min(creep.store.getFreeCapacity(RESOURCE_ENERGY), fallbackBudgetState.rooms[room.name]);
    if (amount <= 0) return false;
    const source = creep.pos.findClosestByPath(FIND_MY_STRUCTURES, {
        filter: (structure) => (structure.structureType === STRUCTURE_SPAWN ||
            structure.structureType === STRUCTURE_EXTENSION) && structure.store[RESOURCE_ENERGY] > 0,
    });
    if (!source) return false;
    const withdrawal = Math.min(amount, source.store[RESOURCE_ENERGY]);
    fallbackBudgetState.rooms[room.name] -= withdrawal;
    const result = creep.withdraw(source, RESOURCE_ENERGY,
        withdrawal);
    if (result === ERR_NOT_IN_RANGE) movement.go(creep, source, { reusePath: 15 });
    return result === OK || result === ERR_NOT_IN_RANGE;
}

function harvestForSite(creep, room, site) {
    if (!site || !creep.body.some((part) => part.type === WORK && part.hits !== 0)) return false;
    const sources = room.find(FIND_SOURCES).slice().sort((left, right) => {
        const leftFromCreep = Math.max(Math.abs(left.pos.x - creep.pos.x), Math.abs(left.pos.y - creep.pos.y));
        const rightFromCreep = Math.max(Math.abs(right.pos.x - creep.pos.x), Math.abs(right.pos.y - creep.pos.y));
        if (leftFromCreep !== rightFromCreep) return leftFromCreep - rightFromCreep;
        const leftFromSite = Math.max(Math.abs(left.pos.x - site.pos.x), Math.abs(left.pos.y - site.pos.y));
        const rightFromSite = Math.max(Math.abs(right.pos.x - site.pos.x), Math.abs(right.pos.y - site.pos.y));
        return leftFromSite - rightFromSite;
    });
    const source = sources.find((candidate) => candidate.energy > 0) || sources[0];
    if (!source) return false;
    if (creep.pos.isNearTo(source.pos)) creep.harvest(source);
    else movement.go(creep, source, { reusePath: 15 });
    return true;
}

function hasHauler(room) {
    return creepsHomeRole(room.name, 'hauler').length > 0;
}

/** 遥测：本房 builder 的取能节奏。wait = 在工地原地等投递的 tick；self = "本来会等"的条件全成立、
 *  但没有任何 hauler 会来的 tick（旧代码在这些 tick 白等）。线上 W33S7 2026-09-10：两只 hauler 都空着手，
 *  builder 空等 30 tick 再走 13 格去源容器刮 56 能量。 */
function noteFeed(room, key) {
    const mem = Memory.rooms && Memory.rooms[room.name];
    if (!mem) return;
    const track = mem.builderFeed || (mem.builderFeed = { at: 0, wait: 0, self: 0 });
    track.at = Game.time;
    track[key] = (Number(track[key]) || 0) + 1;
}

/** 会不会真有人来投递：光"房里有 hauler"不够——空着手的 hauler 只会让 builder 白等。
 *  线上 W33S7 2026-09-10：两只 hauler 都是 0 能量、没有任务，builder 在工地空等 30 tick（feedAt 到期才走），
 *  然后自己走 13 格去源容器刮 56 能量再走回来。判据：已经有 hauler 认领了"送我这单"（brokerTask.id = builder.id），
 *  或者房里有装着能量、手上没别的活的 hauler（broker 的工地补能是第 2 层，压过回库第 4 层，下一 tick 就会派给它）。 */
function haulerIncoming(creep, room) {
    for (const hauler of creepsHomeRole(room.name, 'hauler')) {
        if (hauler.spawning) continue;
        if (isRetiring(hauler.memory)) continue;   // 走向 spawn 回收中的旧 hauler 不会来投递
        const lease = hauler.memory && hauler.memory.brokerTask;
        if (lease && lease.kind === 'deliver' && lease.id === creep.id) return true;
        if (lease) continue;
        if (hauler.store && Number(hauler.store[RESOURCE_ENERGY] || 0) > 0) return true;
    }
    return false;
}

function run(creep) {
    const room = Game.rooms[creep.memory.home];
    if (!room) { movement.go(creep, new RoomPosition(25, 25, creep.memory.home)); return; }
    const state = (Memory.rooms[room.name] || {}).state || {};

    const hasLoad = creep.store[RESOURCE_ENERGY] > 0;
    if (hasLoad && creep.memory.waitSince) delete creep.memory.waitSince;
    const site = nextSite(room);

    // 危急结构（会消失的容器/道路）优先于建造：一次维修 100 血/能量，重建一条路要 300–1500 能量；开修后修到普通维修线（repairHold）
    if (hasLoad) {
        const critical = repairHold(creep, room) || criticalNear(creep, room);
        if (critical) {
            creep.memory.repairId = critical.id;
            if (creep.repair(critical) === ERR_NOT_IN_RANGE) movement.go(creep, critical, { reusePath: 15 });
            return;
        }
    } else if (creep.memory.repairId) {
        delete creep.memory.repairId;   // 能量用完：这一轮到此为止，下一车重新挑（修到 20% 以上的就不再插队）
    }

    if (hasLoad && site) {
        const ret = creep.build(site);
        if (ret === ERR_NOT_IN_RANGE) movement.go(creep, site, { reusePath: 15 });
        else {
            // 在工地上干活：登记位置，hauler 会把能量直接送到手上（远离容器的工地靠自己往返效率只有 1–2 能量/tick）
            creep.memory.feedAt = Game.time;
            creep.memory.siteId = site.id;
        }
        return;
    }
    // 刚在工地上用完能量：房里有 hauler 就原地等投递，不要空着跑回容器（总等待有上限，hauler 一直被 spawn/ext 占着时不能永远等）
    const waitedTooLong = Game.time - Number(creep.memory.waitSince || Game.time) > (config.builderFeedMaxWait || 50);
    // 房里有闲置能量（容器快满 / 地上成堆）时不等投递：自己去取比让 11 个 WORK 干等划算
    const surplus = !room.storage && energySurplus(room);
    // 取能点就在几格内时也不等：等 50 tick 投递，不如自己走 5 格去取（线上 W33S7 的 builder 在工地上空等 50 tick，
    // 而 5 格外的 storage / 控制器 link 里有能量；等投递只在"取能要走十几格"时才划算）
    const ctrlShare = Number(config.energySurplus && config.energySurplus.ctrlShare) || 0.75;
    const nearSource = hasLoad ? null : energySourceFor(creep, room, ctrlShare);
    const selfFetch = !!nearSource && Math.max(
        Math.abs(nearSource.pos.x - creep.pos.x), Math.abs(nearSource.pos.y - creep.pos.y)) <= (config.builderSelfFetchRange || 8);
    if (!hasLoad && site && !waitedTooLong && !surplus && !selfFetch &&
        Game.time - (creep.memory.feedAt || -1e9) <= (config.builderFeedWait || 30) &&
        creep.pos.inRangeTo(site.pos, 3)) {
        if (haulerIncoming(creep, room)) {
            if (!creep.memory.waitSince) creep.memory.waitSince = Game.time;
            noteFeed(room, 'wait');
            return;
        }
        // 会等的条件全成立，只是没有任何 hauler 会来：记一笔（旧代码在这里白等 30 tick），下面自己去取
        noteFeed(room, 'self');
    }
    if (hasLoad && !site) {
        const broken = damagedStructure(room);
        if (broken) {
            if (creep.repair(broken) === ERR_NOT_IN_RANGE) movement.go(creep, broken, { reusePath: 15 });
            return;
        }
        // 没工地没破损：storage 富余才帮忙升级
        const st = room.storage;
        if (st && st.my && st.store[RESOURCE_ENERGY] > config.builderUpgradeAbove) {
            if (creep.upgradeController(room.controller) === ERR_NOT_IN_RANGE) movement.go(creep, room.controller, { reusePath: 20 });
            return;
        }
    }
    // 补能
    if (!hasLoad || (site && creep.store.getFreeCapacity() > 0 && !room.storage)) {
        // 没 storage 的房 spawn/ext 还没满且有 hauler 在岗：builder 不去源容器抢 hauler 要运给 spawn 的能量
        // （W34S7 RCL3：3 个 builder 把源容器掏空，hauler 全空、spawn 停在 300/400 孵不出 harvester）；去工地等 hauler 投递
        // spawn/ext 未满时让路等投递（W34S7 RCL3 曾被 3 只 builder 掏空源容器）；房里有闲置能量时不等，builder 自己去取
        // （线上 W33S8 spawn 350/400、远处源容器 1952/2000 时 builder 干等 146 tick）
        const spawnFirst = !room.storage && room.energyCapacityAvailable < (config.builderSpawnFirstBelow || 800) &&
            room.energyAvailable < room.energyCapacityAvailable && hasHauler(room) && !waitedTooLong && !surplus;
        // 可取的来源：energySourceFor 按路径距离取最近的一个（容器/storage/收货 link），没得取才用 spawn/ext 余量
        const pile = spawnFirst ? null : creep.pos.findClosestByPath(FIND_DROPPED_RESOURCES, {
            filter: (r) => r.resourceType === RESOURCE_ENERGY && r.amount >= 100,
        });
        const src = spawnFirst ? null : nearSource;
        const range = (target) => Math.max(Math.abs(target.pos.x - creep.pos.x), Math.abs(target.pos.y - creep.pos.y));
        if (pile && (!src || range(pile) <= range(src))) {
            if (creep.pickup(pile) === ERR_NOT_IN_RANGE) movement.go(creep, pile, { reusePath: 15 });
            return;
        }
        if (src) {
            // 遥测：本房 builder 最近的取能点（类型+位置）+ 最近 4 次的历史。诊断"路为什么建得慢"时要看它是不是在跑远路。
            // 只在取能点**变了**的时候记一笔：走向取能点的路上每 tick 都会走到这里，每次都记会让环形缓冲只剩同一条
            // （私服维护房有两只 builder 时，远处那只一次往返就把近处那只的 storage 记录冲掉了）
            const roomMemory = Memory.rooms && (Memory.rooms[room.name] || (Memory.rooms[room.name] = {}));
            if (roomMemory) {
                const entry = { at: Game.time, type: src.structureType, x: src.pos.x, y: src.pos.y };
                const log = roomMemory.builderSourceLog || (roomMemory.builderSourceLog = []);
                const last = log[log.length - 1];
                if (!last || last.type !== entry.type || last.x !== entry.x || last.y !== entry.y) {
                    log.push(entry);
                    if (log.length > 4) log.shift();
                }
                roomMemory.builderSource = entry;
                // 本房 builder 的**第一个**取能点：诊断"取能点规则选错"时最直接的证据
                // （环形历史会被后来的取能点顶掉，长跑之后看不到开局那一次）
                if (!roomMemory.builderSourceFirst) roomMemory.builderSourceFirst = entry;
            }
            const ret = creep.withdraw(src, RESOURCE_ENERGY);
            if (ret === ERR_NOT_IN_RANGE) movement.go(creep, src, { reusePath: 15 });
            return;
        }
        if (spawnFirst && site) {
            if (!creep.memory.waitSince) creep.memory.waitSince = Game.time;
            if (!creep.pos.inRangeTo(site.pos, 3)) movement.go(creep, site, { reusePath: 15 });
            else creep.memory.feedAt = Game.time;
            creep.memory.siteId = site.id;
            return;
        }
        if (!spawnFirst && withdrawRoomSurplus(creep, room, state)) return;
        if (harvestForSite(creep, room, site)) return;
    }
    if (site && hasLoad) {
        if (creep.build(site) === ERR_NOT_IN_RANGE) movement.go(creep, site, { reusePath: 15 });
        return;
    }
    if (taskBroker.runFallback(creep, room)) return;
    // 闲时靠 storage/spawn
    const anchor = room.storage || room.find(FIND_MY_SPAWNS)[0];
    if (anchor && !creep.pos.inRangeTo(anchor.pos, 3)) movement.go(creep, anchor.pos, { range: 3, reusePath: 20 });
}

module.exports = { run, nextSite };

modules.roles_claimer:
'use strict';
/** 占领工：走到目标房 claim controller，占下即退役（spawn 工地由新房自己的轮子方案决定，见 expansion.run） */
const movement = require('movement');
const expansion = require('expansion');
const retire = require('retire');
const { logErr } = require('utils');

function run(creep) {
    if (creep.memory.retired) { retire.retireAtSpawn(creep); return; }
    const target = creep.memory.targetRoom;
    if (!target) return;
    if (creep.room.name !== target) {
        if (expansion.noteStuck(creep)) return;
        movement.noteKeeperTransit(creep);   // 遥测：记录穿 SK 房时到 lair 的最近距离（私服断言用）
        // 允许穿 SK 房（只避他人占领房）+ 保持离 keeper lair 距离，去 SK 环外的目标房（如 W37S5/W38S7）占领
        movement.go(creep, new RoomPosition(25, 25, target), { range: 20, reusePath: 40,
            avoidRooms: movement.hostileTerritoryRooms(), costCallback: movement.keeperAvoidCallback() });
        return;
    }
    const controller = creep.room.controller;
    if (!controller) return;
    if (controller.my) {
        creep.suicide();
        return;
    }
    if (controller.owner) {
        logErr('claimer ' + target, new Error('controller owned by ' + controller.owner.username));
        creep.suicide();
        return;
    }
    const ret = creep.claimController(controller);
    if (ret === ERR_NOT_IN_RANGE) movement.go(creep, controller, { range: 1, reusePath: 25 });
    else if (ret === ERR_GCL_NOT_ENOUGH) logErr('claimer ' + target, new Error('GCL not enough'));
}

module.exports = { run };

modules.roles_courier:
'use strict';
/** 援建搬运（aid.js 派出）：从母房（memory.from）的 storage 取能量，送到弱房（memory.home），投递分层与 remoteHauler 回家一致：
 *  spawn/ext → 低于储备的塔 → 控制器容器 → 和平期塔 → storage（弱房经济没起来，spawn 优先；只挑没被本房 hauler 预留满的 spawn/ext）。
 *  母房 storage 低于 config.aid.exportKeep 时不取（母房自己还要用），弱房放不下时在 spawn 旁等；母房没了 storage 就去最近的 spawn 回收退役。
 *  同 tick 取送 + 起步（引擎允许 withdraw/transfer 与 move 同 tick，射程按 tick 开始时的位置算、store 下一 tick 才变）：取满的那一 tick
 *  就朝弱房走；每次投递后同 tick 挑下一站（排除刚投过的那格）起步、broker 同 tick 扣减，投空的那一 tick 就回母房 */
const config = require('config');
const movement = require('movement');
const retireMod = require('retire');
const haulStats = require('haul_stats');
const taskBroker = require('task_broker');
const { homeTarget, rangeTo } = require('roles_remoteHauler');

function goToRoom(creep, roomName) {
    movement.go(creep, new RoomPosition(25, 25, roomName), { range: 20, reusePath: 35 });
}

function freeOf(target) {
    const store = target && target.store;
    if (!store || typeof store.getFreeCapacity !== 'function') return Infinity;
    return Math.max(0, Number(store.getFreeCapacity(RESOURCE_ENERGY)) || 0);
}

function load(creep) {
    const from = Game.rooms[creep.memory.from];
    if (creep.room.name !== creep.memory.from) { goToRoom(creep, creep.memory.from); return; }
    const storage = from && from.storage;
    if (!storage || storage.my === false || !storage.store) { retireMod.retireAtSpawn(creep); return; }
    const keep = require('utils').aidExportLevels(config.aid, config.upgrading).keep;
    const spare = Number(storage.store[RESOURCE_ENERGY] || 0) - keep;
    if (spare <= 0) {
        haulStats.note(creep, 'wait');
        if (!creep.pos.inRangeTo(storage.pos, 3)) movement.go(creep, storage, { range: 3, reusePath: 25 });
        return;
    }
    const free = creep.store.getFreeCapacity(RESOURCE_ENERGY);
    const amount = Math.min(spare, free);
    const range = rangeTo(creep, storage);
    if (range != null && range > 1) { movement.go(creep, storage, { range: 1, reusePath: 20 }); return; }
    const ret = creep.withdraw(storage, RESOURCE_ENERGY, amount);
    if (ret === ERR_NOT_IN_RANGE) { movement.go(creep, storage, { range: 1, reusePath: 20 }); return; }
    // 取满的那一 tick 就出发（下一 tick run() 看到满仓也会转投递）；只取到零头（storage 只剩导出线以上一点）时照旧等
    if (ret === OK && amount >= free) {
        creep.memory.state = 'deliver';
        goToRoom(creep, creep.memory.home);
    }
}

function deliver(creep) {
    const home = Game.rooms[creep.memory.home];
    if (!home || creep.room.name !== creep.memory.home) { goToRoom(creep, creep.memory.home); return; }
    const exclude = new Set();
    const target = homeTarget(home, creep, { exclude });
    if (!target) {
        haulStats.note(creep, 'full');
        const anchor = home.storage || home.find(FIND_MY_SPAWNS)[0];
        if (anchor && !creep.pos.inRangeTo(anchor.pos, 3)) movement.go(creep, anchor, { range: 3, reusePath: 25 });
        return;
    }
    const range = rangeTo(creep, target);
    if (range != null && range > 1) { movement.go(creep, target, { range: 1, reusePath: 20 }); return; }
    const energy = Number(creep.store[RESOURCE_ENERGY]) || 0;
    const free = freeOf(target);
    const sent = Number.isFinite(free) ? Math.min(energy, free) : energy;
    const ret = creep.transfer(target, RESOURCE_ENERGY, sent);
    if (ret === ERR_NOT_IN_RANGE) { movement.go(creep, target, { range: 1, reusePath: 20 }); return; }
    if (ret !== OK) return;
    if (typeof taskBroker.consume === 'function') taskBroker.consume(creep, home, target, sent, 'deliver');
    const left = energy - sent;
    if (left <= 0) { goToRoom(creep, creep.memory.from); return; }   // 投空的那一 tick 就回母房取货
    exclude.add(target.id);
    const next = homeTarget(home, creep, { exclude });
    const nextRange = next ? rangeTo(creep, next) : null;
    if (next && nextRange != null && nextRange > 1) movement.go(creep, next, { range: 1, reusePath: 20 });
}

function run(creep) {
    if (!creep.memory.home || !creep.memory.from) return;
    if (creep.store[RESOURCE_ENERGY] <= 0) creep.memory.state = 'load';
    else if (creep.store.getFreeCapacity(RESOURCE_ENERGY) === 0) creep.memory.state = 'deliver';
    else if (!creep.memory.state) creep.memory.state = 'deliver';
    if (creep.memory.state === 'load') load(creep);
    else deliver(creep);
}

module.exports = { run };

modules.roles_defender:
'use strict';
/** 防守单位：去目标房，远程风筝或近战贴脸，清 InvaderCore；无敌情一段时间后走到最近的 spawn 回收退役 */
const movement = require('movement');
const defense = require('defense');
const remote = require('remote');
const retireMod = require('retire');
const actions = require('actions');
const { creepsHomeRole } = require('utils');

function range(a, b) {
    return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
}

function closest(creep, list) {
    let best = null;
    let bestRange = Infinity;
    for (const item of list) {
        const r = range(creep.pos, item.pos);
        if (r < bestRange) { best = item; bestRange = r; }
    }
    return best;
}

function clamp(value) {
    return Math.max(1, Math.min(48, value));
}

function stepAway(creep, from) {
    const dx = Math.sign(creep.pos.x - from.pos.x) || 1;
    const dy = Math.sign(creep.pos.y - from.pos.y) || 0;
    const target = new RoomPosition(clamp(creep.pos.x + dx * 3), clamp(creep.pos.y + dy * 3), creep.room.name);
    movement.go(creep, target, { range: 0, reusePath: 3 });
}

function fightRanged(creep, hostiles) {
    const target = closest(creep, hostiles);
    const r = range(creep.pos, target.pos);
    // heal 不在任何管线的阻塞列表里，和 rangedAttack/rangedMassAttack 同 tick 白拿（引擎表见 src/actions.js）
    if (creep.hits < creep.hitsMax) { creep.heal(creep); actions.note(creep, 'heal'); }
    const inRange = hostiles.filter((h) => range(creep.pos, h.pos) <= 3);
    if (inRange.length >= 2) { creep.rangedMassAttack(); actions.note(creep, 'rangedMassAttack'); }
    else if (r <= 3) { creep.rangedAttack(target); actions.note(creep, 'rangedAttack'); }
    if (r < 3) stepAway(creep, target);
    else if (r > 3) movement.go(creep, target, { range: 3, reusePath: 5 });
}

function fightMelee(creep, hostiles) {
    const target = closest(creep, hostiles);
    // 近战：heal / rangedHeal 会把 attack 整个顶掉（引擎表 attack: [...,'rangedHeal','heal']），
    // 所以出手的这一 tick 不自疗——伤害是它存在的理由，自疗留给够不到目标的 tick
    const ret = creep.attack(target);
    if (ret === OK) actions.note(creep, 'attack');
    else if (ret === ERR_NOT_IN_RANGE) {
        movement.go(creep, target, { range: 1, reusePath: 5 });
        if (creep.hits < creep.hitsMax && creep.getActiveBodyparts(HEAL) > 0) { creep.heal(creep); actions.note(creep, 'heal'); }
    }
}

function hitStructure(creep, structure) {
    const ranged = creep.memory.style === 'ranged';
    const ret = ranged ? creep.rangedAttack(structure) : creep.attack(structure);
    if (ret === ERR_NOT_IN_RANGE) movement.go(creep, structure, { range: ranged ? 3 : 1, reusePath: 10 });
}

/** 主动退役：标记 retired（main.js 清理内存时不算阵亡，defense.noteLoss；squadMates 不再算它），然后走到最近的 spawn 回收 */
function retire(creep) {
    creep.memory.retired = true;
    retireMod.retireAtSpawn(creep);
}

/** 同一母房、同一目标房、没退役的 defender（含自己；孵化中的不算） */
function squadMates(creep) {
    const out = [];
    for (const other of creepsHomeRole(creep.memory.home, 'defender')) {
        if (other.memory.targetRoom !== creep.memory.targetRoom) continue;
        if (other.spawning || other.memory.retired) continue;
        out.push(other);
    }
    return out;
}

function remoteRecord(creep) {
    const mem = Memory.rooms && Memory.rooms[creep.memory.home];
    return (mem && mem.remotes && mem.remotes[creep.memory.targetRoom]) || null;
}

/** 进了目标房但队友还没到：守在入口附近不推进，射程内的敌人照打、受伤自疗 */
function holdPosition(creep, hostiles) {
    const target = closest(creep, hostiles);
    const r = range(creep.pos, target.pos);
    const wantHeal = creep.hits < creep.hitsMax && creep.getActiveBodyparts(HEAL) > 0;
    if (creep.memory.style === 'ranged') {
        if (r <= 3) { creep.rangedAttack(target); actions.note(creep, 'rangedAttack'); }
        if (wantHeal) { creep.heal(creep); actions.note(creep, 'heal'); }   // heal 不挡 rangedAttack
        if (r < 3) stepAway(creep, target);
    } else if (r <= 1) {
        // 近战出手的 tick 不自疗：heal 会把 attack 顶掉（大脑可以下发带 HEAL 的近战身体）
        creep.attack(target);
        actions.note(creep, 'attack');
    } else if (wantHeal) {
        creep.heal(creep);
        actions.note(creep, 'heal');
    }
    if (creep.pos.x <= 0 || creep.pos.x >= 49 || creep.pos.y <= 0 || creep.pos.y >= 49) {
        movement.go(creep, new RoomPosition(25, 25, creep.room.name), { range: 22, reusePath: 5 });
    }
}

function run(creep) {
    // 退役中：只管走到 spawn 回收，不再看目标房与敌情——否则会因为"不在目标房"又走回外矿，两房之间来回踱步到寿命结束
    if (creep.memory.retired) { retireMod.retireAtSpawn(creep); return; }
    const target = creep.memory.targetRoom || creep.memory.home;
    if (!target) return;
    const squad = Math.max(1, Number(creep.memory.squad) || 1);
    if (creep.room.name !== target) {
        // 成组出发：在家等到全组都孵出来再一起走（组员没齐时威胁已消失就退役），不再一只一只送
        if (squad > 1 && creep.room.name === creep.memory.home && !creep.memory.launched) {
            const mates = squadMates(creep);
            if (mates.length < squad) {
                // 母房现在已经不想为这房出兵（威胁消失 / 大脑改成 avoid / 组员阵亡后等新敌情）：组永远凑不齐，退役
                const home = Game.rooms[creep.memory.home];
                if (home && !defense.planFor(home, target)) { retire(creep); return; }
                const anchor = creep.room.find(FIND_MY_SPAWNS)[0];
                if (anchor && !creep.pos.inRangeTo(anchor.pos, 3)) movement.go(creep, anchor.pos, { range: 3, reusePath: 20 });
                return;
            }
            creep.memory.launched = true;
        }
        movement.go(creep, new RoomPosition(25, 25, target), { range: 20, reusePath: 40 });
        return;
    }
    // 外矿房：把看到的敌情写回外矿记录（画像 / 到期；清场后立刻解除停用）
    const record = remoteRecord(creep);
    if (record && creep.room.name !== creep.memory.home) {
        const home = Game.rooms[creep.memory.home];
        if (home) remote.observe(home, creep.room);
    }
    const hostiles = defense.armedHostiles(creep.room);
    const any = hostiles.length ? hostiles : creep.room.find(FIND_HOSTILE_CREEPS);
    if (any.length) {
        delete creep.memory.idleSince;
        if (squad > 1 && !creep.memory.engaged) {
            if (!creep.memory.arrivedAt) creep.memory.arrivedAt = Game.time;
            const here = squadMates(creep).filter((mate) => mate.room && mate.room.name === creep.room.name).length;
            if (here < squad && Game.time - creep.memory.arrivedAt < defense.settings().squadWait) {
                holdPosition(creep, any);
                return;
            }
            creep.memory.engaged = true;
        }
        if (creep.memory.style === 'ranged') fightRanged(creep, any);
        else fightMelee(creep, any);
        return;
    }
    const core = defense.invaderCore(creep.room);
    if (core) {
        delete creep.memory.idleSince;
        hitStructure(creep, core);
        return;
    }
    if (creep.hits < creep.hitsMax && creep.getActiveBodyparts(HEAL) > 0) creep.heal(creep);
    // 站在出口格上不动会被引擎弹回邻房，下一 tick 又走回来——先走进房内再等
    if (creep.pos.x <= 0 || creep.pos.x >= 49 || creep.pos.y <= 0 || creep.pos.y >= 49) {
        movement.go(creep, new RoomPosition(25, 25, creep.room.name), { range: 20, reusePath: 10 });
        return;
    }
    // 清场：等一会儿看有没有后续，再去最近的 spawn 回收退役
    if (!creep.memory.idleSince) creep.memory.idleSince = Game.time;
    if (Game.time - creep.memory.idleSince < defense.settings().idleTicks) return;
    retire(creep);
}

module.exports = { run };

modules.roles_downgrader:
'use strict';
/**
 * 攻占围降单位（downgrader）：去目标房控制器旁，控制器仍有主、未开盾时 attackController。
 *   引擎语义：每次攻击 −CONTROLLER_CLAIM_DOWNGRADE(300)×CLAIM 部件、控制器进入 1000 tick upgradeBlocked，
 *   期间对方既不能开 safe mode 也不能 upgrade 恢复；CLAIM 部件寿命仅 600 tick，需 conquest 模块接力补员。
 *   控制器降到无主（level 0）后本单位任务完成，退役回收。
 */
const movement = require('movement');
const retireMod = require('retire');

function run(creep) {
    if (creep.memory.retired) { retireMod.retireAtSpawn(creep); return; }
    const target = creep.memory.targetRoom;
    if (!target) return;
    if (creep.room.name !== target) {
        movement.go(creep, new RoomPosition(25, 25, target), { range: 20, reusePath: 40 });
        return;
    }
    const ctrl = creep.room.controller;
    if (!ctrl) return;
    if (ctrl.my) { creep.memory.retired = true; retireMod.retireAtSpawn(creep); return; }
    const res = ctrl.reservation;
    const enemyReserved = !!(res && (res.username || res.user) && !res.my);
    const suppress = !!creep.memory.suppress;
    // 无主：默认退役（占领交给 claimer）。suppress 时留下拆预定 / 堵在控制器旁防对方再占。
    if (!ctrl.owner) {
        if (!suppress && !enemyReserved) { creep.memory.retired = true; retireMod.retireAtSpawn(creep); return; }
        if (!creep.pos.inRangeTo(ctrl.pos, 1)) { movement.go(creep, ctrl, { range: 1, reusePath: 20 }); return; }
        if (enemyReserved) creep.attackController(ctrl);
        return;
    }
    if (!creep.pos.inRangeTo(ctrl.pos, 1)) { movement.go(creep, ctrl, { range: 1, reusePath: 20 }); return; }
    // safe mode 期间 attackController 无效（引擎 guard），原地等，不空攻
    if (ctrl.safeMode && ctrl.safeMode > 0) return;
    // upgradeBlocked 时返回 ERR_TIRED，引擎自身也是 no-op；直接调用即可
    creep.attackController(ctrl);
}

module.exports = { run };

modules.roles_feeder:
'use strict';
/** 专职短途搬运工：只在 storage 与控制器容器之间来回（storage 富余且控制器由容器供能的房，spawn.feederTarget 出编制）。
 *  取：storage；送：控制器容器（满了就在旁边等，不占容器格）。富余状态关闭（utils.storageRichState 滞回到 storageFeedBelow 以下）
 *  或 storage/容器没了：卸完手里的能量就退役回收（retire.retireAtSpawn），不占编制。
 *  同 tick 取送 + 起步（引擎允许 withdraw/transfer 与 move 同 tick，射程按 tick 开始时的位置算、store 下一 tick 才变）：
 *  取满的那一 tick 就朝控制器容器走，投空的那一 tick 就回 storage——以前每次取送都停一拍，2d+2 的往返白花 2 tick。
 *  不走 task broker：它的活只有这一条线，broker 的兜底规则（源容器优先）正是它要绕过的 */
const movement = require('movement');
const layout = require('layout');
const config = require('config');
const utils = require('utils');
const retireMod = require('retire');
const haulStats = require('haul_stats');

function ctrlContainer(room) {
    const plan = (Memory.rooms[room.name] || {}).plan;
    const spot = plan && plan.containers && plan.containers.ctrl;
    return spot ? layout.structureAt(room, spot.x, spot.y, STRUCTURE_CONTAINER) : null;
}

function energyOf(target) {
    return target && target.store ? Math.max(0, Number(target.store[RESOURCE_ENERGY]) || 0) : 0;
}

function freeOf(target) {
    return target && target.store && typeof target.store.getFreeCapacity === 'function' ?
        Math.max(0, Number(target.store.getFreeCapacity(RESOURCE_ENERGY)) || 0) : 0;
}

/** 位置齐全时自己查射程（mock 的 transfer/withdraw 不查）；位置不全返回 null，交给引擎返回码 */
function reach(creep, target) {
    const a = creep && creep.pos;
    const b = target && target.pos;
    if (!a || !b || typeof a.x !== 'number' || typeof b.x !== 'number') return null;
    if (a.roomName && b.roomName && a.roomName !== b.roomName) return Infinity;
    return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
}

function run(creep) {
    const room = Game.rooms[creep.memory.home];
    if (!room) { movement.go(creep, new RoomPosition(25, 25, creep.memory.home), { reusePath: 20 }); return; }
    const storage = room.storage;
    const container = ctrlContainer(room);
    const rich = utils.storageRichState(room, Memory.rooms[room.name] || {}, config.upgrading || {});
    const energy = energyOf(creep);
    const carrying = energy > 0;
    if (!storage || storage.my === false || !container || (!rich && !carrying)) {
        retireMod.retireAtSpawn(creep);
        return;
    }
    if (carrying) {
        const free = freeOf(container);
        if (free <= 0) {
            haulStats.note(creep, 'full');
            if (!creep.pos.inRangeTo(container.pos, 2)) movement.go(creep, container, { range: 2, reusePath: 20 });
            return;
        }
        const range = reach(creep, container);
        if (range != null && range > 1) { movement.go(creep, container, { range: 1, reusePath: 20 }); return; }
        const sent = Math.min(energy, free);   // tick 开始时的数（引擎对 amount + 存量 > 容量直接 ERR_FULL）
        const ret = creep.transfer(container, RESOURCE_ENERGY, sent);
        if (ret === ERR_NOT_IN_RANGE) { movement.go(creep, container, { range: 1, reusePath: 20 }); return; }
        // 投空的那一 tick 就回 storage；富余已经关了就不往回走（下一 tick 空手退役）
        if (ret === OK && energy - sent <= 0 && rich) movement.go(creep, storage, { range: 1, reusePath: 20 });
        return;
    }
    const range = reach(creep, storage);
    if (range != null && range > 1) { movement.go(creep, storage, { range: 1, reusePath: 20 }); return; }
    const amount = Math.min(freeOf(creep), energyOf(storage));
    if (amount <= 0) return;
    const ret = creep.withdraw(storage, RESOURCE_ENERGY, amount);
    if (ret === ERR_NOT_IN_RANGE) { movement.go(creep, storage, { range: 1, reusePath: 20 }); return; }
    // 取货的那一 tick 就朝控制器容器起步（容器满着就去 2 格内等，不占容器格）
    if (ret === OK) movement.go(creep, container, { range: freeOf(container) > 0 ? 1 : 2, reusePath: 20 });
}

module.exports = { run };

modules.roles_harvester:
'use strict';
/** 静态矿工：站源旁容器上持续采掘；有 link 时喂 link；
 *  容器未建好时切换为"采满→送 spawn/ext"往返模式 */
const layout = require('layout');
const movement = require('movement');
const config = require('config');
const { findCached, bodyTicksPerTile, creepsHomeRole } = require('utils');

function chebyshev(left, right) {
    return Math.max(Math.abs(left.x - right.x), Math.abs(left.y - right.y));
}

function linkNear(room, plan, idx, source) {
    const spot = layout.linkSpot(plan, idx === 1 ? 'src1' : 'src0');
    if (spot) {
        const planned = layout.structureAt(room, spot.x, spot.y, STRUCTURE_LINK);
        if (planned && planned.my) return planned;
    }
    if (!source || typeof room.find !== 'function') return null;
    const nearby = findCached(room, FIND_STRUCTURES).filter((structure) =>
        structure.structureType === STRUCTURE_LINK && structure.my && chebyshev(structure.pos, source.pos) <= 1);
    nearby.sort((left, right) => chebyshev(left.pos, source.pos) - chebyshev(right.pos, source.pos) ||
        left.pos.y - right.pos.y || left.pos.x - right.pos.x);
    return nearby[0] || null;
}

function workOf(creep) {
    return creep.body.filter((part) => part.type === WORK && part.hits !== 0).length;
}

/** 本 creep 的 WORK 少于同源另一只在房内的矿工，且那只已 ≥5 WORK ⇒ 本 creep 多余 */
function redundantSmallMiner(creep, room, src) {
    const mine = workOf(creep);
    if (mine >= 5) return false;
    for (const other of creepsHomeRole(room.name, 'harvester')) {
        if (other === creep) continue;
        if (other.memory.sourceId !== src.id || other.spawning || !other.room || other.room.name !== room.name) continue;
        if (workOf(other) >= 5 && workOf(other) > mine) return true;
    }
    return false;
}

function nearbyContainer(room, source, spot) {
    if (spot) {
        const planned = layout.structureAt(room, spot.x, spot.y, STRUCTURE_CONTAINER);
        if (planned) return planned;
    }
    if (!source || typeof room.find !== 'function') return null;
    const nearby = findCached(room, FIND_STRUCTURES).filter((structure) =>
        structure.structureType === STRUCTURE_CONTAINER && chebyshev(structure.pos, source.pos) <= 1);
    nearby.sort((left, right) => chebyshev(left.pos, source.pos) - chebyshev(right.pos, source.pos) ||
        left.pos.y - right.pos.y || left.pos.x - right.pos.x);
    return nearby[0] || null;
}

/** 源旁的容器工地：规划位优先，否则源 1 格内任意容器工地（矿工自建） */
function containerSiteNear(room, source, spot) {
    if (spot && typeof room.lookForAt === 'function') {
        const planned = (room.lookForAt(LOOK_CONSTRUCTION_SITES, spot.x, spot.y) || [])
            .find((site) => site.structureType === STRUCTURE_CONTAINER);
        if (planned) return planned;
    }
    if (!source || typeof room.find !== 'function') return null;
    return findCached(room, FIND_MY_CONSTRUCTION_SITES).find((site) =>
        site.structureType === STRUCTURE_CONTAINER && chebyshev(site.pos, source.pos) <= 1) || null;
}

function hasHauler(room) {
    return creepsHomeRole(room.name, 'hauler').some((other) => !other.spawning);
}

/** 静态身体：平地每格 > mobileTicksPerTile tick（5W1C1M = 6）——往返送 spawn 一趟 50 能量要上百 tick，不如原地落地/自建容器 */
function isStaticBody(creep) {
    const limit = Number(config.harvesting && config.harvesting.mobileTicksPerTile) || 3;
    return bodyTicksPerTile(creep.body) > limit;
}

/** 容器缺血 ≥ 一次 repair 能补的量（WORK × REPAIR_POWER 100）且身上有能量：这 tick 修容器 */
function containerNeedsRepair(container, creep) {
    if (!container || !(config.harvesting && config.harvesting.selfRepairContainer)) return false;
    if (container.hits == null || container.hitsMax == null) return false;
    const work = workOf(creep);
    if (work <= 0 || (creep.store[RESOURCE_ENERGY] || 0) < work) return false;
    return container.hitsMax - container.hits >= work * 100;
}

function run(creep) {
    const room = Game.rooms[creep.memory.home];
    if (!room) { movement.go(creep, new RoomPosition(25, 25, creep.memory.home)); return; }
    const mem = Memory.rooms[room.name] || {};
    const sources = layout.resolveSources(room, mem, mem.plan);
    let idx = creep.memory.sourceId ? sources.findIndex((source) => source.id === creep.memory.sourceId) : -1;
    if (idx < 0) idx = Math.max(0, Math.min(creep.memory.sourceIdx || 0, sources.length - 1));
    const src = sources[idx];
    if (!src) return;
    if (creep.memory.sourceId !== src.id) creep.memory.sourceId = src.id;
    if (creep.memory.sourceIdx !== idx) creep.memory.sourceIdx = idx;
    // 同一个源已有 ≥5 WORK 的更大矿工在房内（援建矿工到位）：小矿工退役让出容器位，别占着工位让大矿工干等
    if (redundantSmallMiner(creep, room, src)) { creep.suicide(); return; }
    const plan = mem.plan || {};
    const key = 'src' + idx;
    const containerSpot = plan.containers && plan.containers[key];
    const container = nearbyContainer(room, src, containerSpot);
    const configuredWorkSpot = plan.workPositions && plan.workPositions[key];
    const configuredWorkValid = configuredWorkSpot && chebyshev(configuredWorkSpot, src.pos) <= 1 &&
        (!container || chebyshev(configuredWorkSpot, container.pos) <= 1);
    const link = linkNear(room, plan, idx, src);
    const hasCarry = creep.body.some((part) => part.type === 'carry' && part.hits !== 0);
    // 工位必须带 roomName：援建矿工出生在母房，不带房间的 {x,y} 会被解析成当前房间的同名坐标，走到那里就"以为到位"
    const spotIn = (spot) => (spot ? { x: spot.x, y: spot.y, roomName: room.name } : null);
    const atSpot = (spot) => !!spot && creep.pos.roomName === spot.roomName && creep.pos.x === spot.x && creep.pos.y === spot.y;
    let workSpot = spotIn(configuredWorkValid ? configuredWorkSpot : container ? container.pos : link ? link.pos : containerSpot);
    if (!hasCarry && container) workSpot = spotIn(container.pos);
    if (creep.memory.dropMiner || !hasCarry) {
        if (container && workSpot && !atSpot(workSpot)) {
            movement.go(creep, workSpot, { range: 0, reusePath: 20 });
            // 工位被占时挨着源就先采：能量落地由 hauler 捡，比干等强
            if (creep.pos.isNearTo(src.pos)) creep.harvest(src);
            return;
        }
        if (creep.pos.isNearTo(src.pos)) {
            creep.harvest(src);
            if (!container && creep.store[RESOURCE_ENERGY] > 0) creep.drop(RESOURCE_ENERGY);
        } else {
            movement.go(creep, src, { reusePath: 20 });
        }
        return;
    }

    const site = containerSiteNear(room, src, containerSpot);
    if (container || (link && workSpot)) {
        // 静态采掘模式
        if (workSpot && !atSpot(workSpot)) {
            movement.go(creep, workSpot, { range: 0, reusePath: 30 });
            if (creep.pos.isNearTo(src.pos)) creep.harvest(src);
            return;
        }
        // 容器缺血：这 tick 用身上的能量修（repair 与 harvest 同管线，只能二选一；transfer 会和 repair 抢同一份能量，一起跳过）
        if (containerNeedsRepair(container, creep)) {
            creep.repair(container);
            return;
        }
        // CARRY 与 WORK intent 可并行（引擎先处理 transfer 再处理 harvest）。攒批交货：仓里还放得下 transferBatchHarvests 次采集就不交，
        // 每个 intent 约 0.2 CPU，5W1C 从每 tick 交 10 变成每 4 tick 交 40（线上 2026-10-08：26 个源矿工每 tick 一次 transfer ≈ 5 CPU）
        const harvestAmount = workOf(creep) * (Number(config.harvesting && config.harvesting.harvestPower) || 2);
        const batch = Math.max(1, Number(config.harvesting && config.harvesting.transferBatchHarvests) || 1);
        let freeAfter = creep.store.getFreeCapacity(RESOURCE_ENERGY);
        let target = null;
        if (creep.store[RESOURCE_ENERGY] > 0) {
            if (link && link.store.getFreeCapacity(RESOURCE_ENERGY) > 0) target = link;
            else if (container && container.store.getFreeCapacity(RESOURCE_ENERGY) > 0) target = container;
            if (target && freeAfter < harvestAmount * batch) {
                const amount = Math.min(creep.store[RESOURCE_ENERGY], target.store.getFreeCapacity(RESOURCE_ENERGY));
                if (amount > 0 && creep.transfer(target, RESOURCE_ENERGY, amount) === OK) {
                    freeAfter += amount;
                    // 遥测：生涯最大单次交货量（私服生效断言 harvester.batchTransfer 看它）。记最大值而非最近一次：
                    // link/容器装满时一次只能塞进剩余空位（私服 2026-10-08 终态 link 800/800 时最后一次只交 13），最近值反映的是 sink 余量不是攒批；
                    // 只在变大时写，Memory 也不用每批都改
                    if (!(creep.memory.xferBatch >= amount)) creep.memory.xferBatch = amount;
                }
            }
        }
        // link 满了又没有容器：手上的能量拿去建容器工地，否则只能落地（线上 W33S7 源 (14,6)：link 785/800、容器工地 462/5000、地上一堆）
        if (!target && !container && site && creep.store[RESOURCE_ENERGY] >= Math.min(creep.store.getCapacity(RESOURCE_ENERGY) || 0, workOf(creep) * 5)) {
            creep.build(site);
            return;
        }
        // 交完仍装不下这次采集、脚下又不是容器（只有 link 的工位，link 满了）：溢出会落地，宁可这 tick 不采，等 link 送走再继续
        const onContainer = container && creep.pos.x === container.pos.x && creep.pos.y === container.pos.y;
        if (freeAfter < harvestAmount && !onContainer) return;
        creep.harvest(src);
        return;
    }

    // 容器还没建成：静态身体（或房里已有 hauler 的机动身体）站到容器规划位，用自己采的能量把容器工地建起来；
    // 没有工地就原地采、满了落地等 hauler 捡。往返送 spawn 只留给 bootstrap 期没有 hauler 的机动身体
    const staticBody = isStaticBody(creep);
    if (site && (staticBody || hasHauler(room))) {
        const buildSpot = spotIn(configuredWorkValid ? configuredWorkSpot : site.pos);
        if (buildSpot && !atSpot(buildSpot) && !creep.pos.isNearTo(src.pos)) {
            movement.go(creep, buildSpot, { range: 0, reusePath: 20 });
            return;
        }
        if (buildSpot && !atSpot(buildSpot)) movement.go(creep, buildSpot, { range: 0, reusePath: 20 });
        const work = workOf(creep);
        const capacity = creep.store.getCapacity(RESOURCE_ENERGY) || 0;
        // build 与 harvest 同管线：攒够一次 build 的量（WORK × 5，最多一仓）再建，其余 tick 采集
        if (creep.store[RESOURCE_ENERGY] >= Math.min(capacity, work * 5)) creep.build(site);
        else creep.harvest(src);
        return;
    }
    if (staticBody) {
        if (workSpot && !atSpot(workSpot)) {
            movement.go(creep, workSpot, { range: 0, reusePath: 20 });
            if (creep.pos.isNearTo(src.pos)) creep.harvest(src);
            return;
        }
        if (!creep.pos.isNearTo(src.pos)) { movement.go(creep, src, { reusePath: 20 }); return; }
        creep.harvest(src);
        // 仓快满就落地（drop 与 harvest 不同管线，同 tick 都生效）：能量堆由 hauler/builder 捡，比 1 MOVE 拖着 50 能量走 100 tick 强
        if (creep.store.getFreeCapacity(RESOURCE_ENERGY) < workOf(creep) * 2) creep.drop(RESOURCE_ENERGY);
        return;
    }

    // 往返模式（容器建成前）
    const free = creep.store.getFreeCapacity(RESOURCE_ENERGY);
    if (free === 0 || (src.energy <= 0 && creep.store[RESOURCE_ENERGY] > 0)) {
        const target = creep.pos.findClosestByPath(FIND_MY_STRUCTURES, {
            filter: (s) => (s.structureType === STRUCTURE_SPAWN || s.structureType === STRUCTURE_EXTENSION) &&
                s.store.getFreeCapacity(RESOURCE_ENERGY) > 0,
        });
        if (target) {
            if (creep.transfer(target, RESOURCE_ENERGY) === ERR_NOT_IN_RANGE) movement.go(creep, target, { reusePath: 15 });
        } else if (free === 0) {
            creep.drop(RESOURCE_ENERGY); // 哪都放不下就丢地上，别堵在源边
        }
        return;
    }
    if (creep.pos.isNearTo(src.pos)) {
        creep.harvest(src);
    } else {
        movement.go(creep, src, { reusePath: 15 });
    }
}

module.exports = { run };

modules.roles_hauler:
'use strict';
/** 搬运工：源容器 → spawn/ext → 塔 → upgrader 容器 → storage 的能量调度。
 *
 *  每 tick 先规划、再执行：引擎允许同一 tick 各做一次 transfer / withdraw / pickup 外加一次移动（互不冲突，射程按 tick 开始时的位置算，
 *  移动在所有动作之后结算），而 store 要到下一 tick 才变。所以：
 *    - 投递 / 取货成功的那一 tick 就按"动作后的预计载货"挑下一站并起步，不停一拍（以前每次停靠 1.42 tick，线下模拟补满 extension 慢 17–21%）；
 *    - 路过的掉落顺手 pickup、载货路过没满的 spawn/ext 顺手 transfer，都不占这一 tick；
 *    - 取货按"到达时能拿到多少"判断值不值得跑（容量越大、路越远要求越高），不够就在进账的源容器旁边等满，而不是揣着 100 能量来回跑。
 *  目标竞价、按量预留与同 tick 扣减在 task_broker（availableFor / consume / setProjected）。 */
const layout = require('layout');
const config = require('config');
const movement = require('movement');
const taskBroker = require('task_broker');
const links = require('links');
const haulStats = require('haul_stats');
const { findCached, logErr, storageRichState, towerUrgent, spawnWaitingFor } = require('utils');

function energyIn(store) {
    return store ? Number(store[RESOURCE_ENERGY] || 0) : 0;
}

function freeIn(target) {
    const store = target && target.store;
    if (!store || typeof store.getFreeCapacity !== 'function') return 0;
    return Math.max(0, Number(store.getFreeCapacity(RESOURCE_ENERGY)) || 0);
}

function amountAt(target) {
    if (!target) return 0;
    return target.amount != null ? Number(target.amount) || 0 : energyIn(target.store);
}

function posOf(target) {
    return target && target.pos ? target.pos : target;
}

function distance(creep, target) {
    const pos = posOf(target);
    if (!pos || !creep.pos || (pos.roomName && pos.roomName !== creep.pos.roomName)) return 50;
    return Math.max(Math.abs(creep.pos.x - pos.x), Math.abs(creep.pos.y - pos.y));
}

function near(creep, target) {
    return distance(creep, target) <= 1;
}

function hauling() {
    return config.hauling || {};
}

function ctrlContainer(room) {
    if (taskBroker.controllerFeedMode(room) === 'link') return null;
    const plan = (Memory.rooms[room.name] || {}).plan;
    if (!plan || !plan.containers || !plan.containers.ctrl) return null;
    if (layout.controllerFedByStorage(room, plan)) return null;   // 升级者由 storage 供能：容器不再喂
    return layout.structureAt(room, plan.containers.ctrl.x, plan.containers.ctrl.y, STRUCTURE_CONTAINER);
}

const consumerReserveBudget = { tick: -1, rooms: {} };
const roomContexts = { tick: -1, rooms: {} };

/** 每房每 tick 一份：hub 模式、消费者需求、是否急需能量（所有 hauler 共用，不必每只重建一遍 roomTasks） */
function contextFor(room) {
    if (roomContexts.tick !== Game.time) { roomContexts.tick = Game.time; roomContexts.rooms = {}; }
    let ctx = roomContexts.rooms[room.name];
    if (ctx) return ctx;
    const plan = (Memory.rooms[room.name] || {}).plan;
    ctx = { plan, hubFed: links.hubHaulMode(room, plan), demand: null, urgent: null };
    roomContexts.rooms[room.name] = ctx;
    return ctx;
}

/** 非 storage、非源容器、hauler 能送的投递缺口（消费者需求） */
function consumerTasks(room) {
    return taskBroker.pooledTasks(room).filter((task) => task.kind === 'deliver' && task.target &&
        task.target.store && task.target.structureType !== STRUCTURE_STORAGE &&
        !(task.target.structureType === STRUCTURE_CONTAINER && srcIsPlanned(room, task.target)) &&
        (!task.roles || task.roles.includes('hauler')) && task.backlog > 0);
}

/** 消费者还没人认领的缺口：扣掉已经揣着能量在路上的 hauler 承诺的量（以前按 backlog 算，同一个缺口会被重复从 storage 取，
 *  多出来的又被 storage 货锁揣着），再扣掉揣着 storage 货在等缺口的 hauler 手上的货。
 *  本 tick 缓存；有 hauler 租下消费者投递时作废（pickDeliver），后跑的 hauler 看得到这份认领 */
function consumerDemand(room, ctx) {
    if (ctx.demand == null) {
        const open = consumerTasks(room).reduce((sum, task) => sum + Math.max(0, taskBroker.availableFor(task, null)), 0);
        ctx.demand = Math.max(0, open - idleStorageCargo(room, ctx));
    }
    return ctx.demand;
}

/** 揣着 storage 货、手上没有租约的 hauler（消费者刚被别人认领完，在 storage 边等下一个缺口）的货量：下一个缺口它就送去，
 *  不该再从 storage 另取一份（有租约的已经在认领里扣过） */
function idleStorageCargo(room, ctx) {
    if (ctx.idleCargo != null) return ctx.idleCargo;
    let sum = 0;
    for (const other of findCached(room, FIND_MY_CREEPS) || []) {
        const memory = other && other.memory;
        if (!memory || memory.role !== 'hauler' || memory.home !== room.name || !memory.hubCargo) continue;
        if (memory.brokerTask && memory.brokerTask.until >= Game.time) continue;
        sum += energyIn(other.store);
    }
    ctx.idleCargo = sum;
    return sum;
}

/** 房间急需能量：spawn 在等买不起的 creep、spawn/ext 见底、塔紧急 / 危急维修 / 控制器见底（broker 里权重 ≥ 11 的投递）。
 *  急的时候取货门槛降到 50——宁可小车快送，也不让 spawn 干等一只 hauler 攒满 */
function isUrgent(room, ctx) {
    if (ctx.urgent != null) return ctx.urgent;
    const share = Number(hauling().urgentSpawnShare);
    let urgent = spawnWaitingFor(room) ||
        room.energyAvailable < room.energyCapacityAvailable * (Number.isFinite(share) ? share : 0.3);
    if (!urgent) urgent = taskBroker.pooledTasks(room).some((task) => task.kind === 'deliver' && task.tier === 1 && task.weight >= 11 && task.backlog > 0);
    ctx.urgent = urgent;
    return urgent;
}

/** 从 storage 取出的货不再回 storage（以前只有 hub 模式有这条保护：线上 W33S3 从 storage 取 850、750 又放回 storage）。
 *  兜底：揣着 storage 的货超过 storageCargoRelease tick 还送不出去（消费者消失），允许放回，别一直揣着 */
function storageCargoLocked(creep) {
    if (!creep.memory.hubCargo) return false;
    const since = Number(creep.memory.hubCargoAt);
    const release = Number(hauling().storageCargoRelease) || 100;
    return !(since > 0 && Game.time - since > release);
}

function markStorageCargo(creep) {
    creep.memory.hubCargo = true;
    creep.memory.hubCargoAt = Game.time;
}

/** 揣着的 storage 货只剩零头（< max(50, topUpShare × 容量)）又没有消费者可送：解锁。零头放回 storage / 顺路补满都不算来回倒，
 *  锁着它 hauler 就在 storage 边上干等到 storageCargoRelease（审查 EC1：5 能量的零头停了 50 tick） */
function releaseStorageResidual(creep, load, capacity) {
    if (!storageCargoLocked(creep)) return false;
    if (load >= Math.max(50, capacity * (Number(hauling().topUpShare) || 0.25))) return false;
    delete creep.memory.hubCargo;
    delete creep.memory.hubCargoAt;
    noteCounter(creep.room || Game.rooms[creep.memory.home], 'haulCargoRelease');
    return true;
}

/** 累计计数型遥测（私服生效断言用）：Memory.rooms[房][key] = {n, at} */
function noteCounter(room, key) {
    if (!room || !room.name) return;
    const mem = Memory.rooms[room.name] || (Memory.rooms[room.name] = {});
    const rec = mem[key] || (mem[key] = { n: 0 });
    rec.n = (Number(rec.n) || 0) + 1;
    rec.at = Game.time;
}

// ---- 投递目标 ----

/** 投递竞价的轮次：第 1 层先问 spawn/ext 与压过它们的（紧急塔 11、控制器见底 20），再问第 1 层的其余（storage 富余时的
 *  控制器容器 / ctrl link 9）——否则 9 × 1600 的容器缺口按收益压过 10 × 100 的 extension，spawn 有缺口时满载送去控制器 */
const DELIVER_PASSES = [
    (task) => task.tier === 1 && task.weight >= 10,
    (task) => task.tier === 1,
    (task) => task.tier === 2,
    (task) => task.tier === 3,
    (task) => task.tier === 4,
];

function deliverFilter(creep, room, exclude) {
    const locked = storageCargoLocked(creep);
    return (candidate) => candidate.kind === 'deliver' && candidate.target && candidate.target.store &&
        !(exclude && exclude.has(candidate.target.id)) &&
        !(locked && candidate.target.structureType === STRUCTURE_STORAGE) &&
        !(candidate.target.structureType === STRUCTURE_CONTAINER && srcIsPlanned(room, candidate.target));
}

/** 目标在池子里有投递任务时，别人承诺的量还没把它填满（按目标 id 建一次本 tick 的索引，不必每个候选扫整个池子） */
function openTarget(creep, room, target) {
    const ctx = contextFor(room);
    if (!ctx.deliverIndex) {
        ctx.deliverIndex = {};
        for (const task of taskBroker.pooledTasks(room)) {
            if (task.kind !== 'deliver' || !task.target || !task.target.id) continue;
            (ctx.deliverIndex[task.target.id] || (ctx.deliverIndex[task.target.id] = [])).push(task);
        }
    }
    const tasks = ctx.deliverIndex[target.id];
    if (!tasks || !tasks.length) return true;
    return tasks.some((task) => taskBroker.availableFor(task, creep) > 0);
}

/** 返回 { target, task }：逐轮竞价；竞价抛错时走旧的兜底链，平时只为"被卡住检测屏蔽的塔 / spawn / ext"兜底（不抢别人已预留的） */
function pickDeliver(creep, room, exclude) {
    const base = deliverFilter(creep, room, exclude);
    let threw = false;
    try {
        for (const pass of DELIVER_PASSES) {
            const task = taskBroker.pickTask(creep, room, (candidate) => pass(candidate) && base(candidate), true);
            if (!task || !task.target) continue;
            if (task.target.structureType !== STRUCTURE_STORAGE) {
                // 刚租下一个消费者缺口：本 tick 缓存的"没人认领的需求"作废，后跑的 hauler 不再为它从 storage 取
                const ctx = contextFor(room);
                ctx.demand = null;
                ctx.idleCargo = null;
            }
            return { target: task.target, task };
        }
    } catch (error) { threw = true; logErr('hauler.auctionTarget ' + creep.name, error); }
    const target = fallbackDeliver(creep, room, exclude, threw);
    return target ? { target, task: null } : null;
}

function fallbackDeliver(creep, room, exclude, threw) {
    const open = (structure) => !(exclude && exclude.has(structure.id)) && (threw || openTarget(creep, room, structure));
    const linkFeed = taskBroker.controllerFeedLink(room);
    if (threw && linkFeed && linkFeed.starved && open(linkFeed.target)) return linkFeed.target;
    // 塔的大缺口（有敌人或储备被动用，utils.towerUrgent 锁存到补到不缺）先于 spawn/ext：spawn 持续孵化时 spawn/ext 永远有缺口，
    // 塔会几百 tick 没人补（与 broker 分层一致）
    const towerRefillAt = Number(config.towerRefillAt) || 300;
    const towerFilter = (s) => s.structureType === STRUCTURE_TOWER && freeIn(s) >= towerRefillAt && open(s);
    const hostile = room.find(FIND_HOSTILE_CREEPS).length > 0;
    let target = creep.pos.findClosestByPath(FIND_MY_STRUCTURES, { filter: (s) => towerFilter(s) && towerUrgent(room, s, hostile) });
    if (target) return target;
    // spawn / extension 保证孵化
    target = creep.pos.findClosestByPath(FIND_MY_STRUCTURES, {
        filter: (s) => (s.structureType === STRUCTURE_SPAWN || s.structureType === STRUCTURE_EXTENSION) && freeIn(s) > 0 && open(s),
    });
    if (target || !threw) return target || null;
    // 以下只在竞价不可用时：upgrader 供能容器（或 storage 供能时低于地板线的 storage）→ 和平期塔 → storage
    if (linkFeed && open(linkFeed.target)) return linkFeed.target;
    const uc = ctrlContainer(room);
    if (uc && freeIn(uc) > 0 && energyIn(uc.store) < uc.store.getCapacity(RESOURCE_ENERGY) * config.upgraderFillBelow && open(uc)) return uc;
    if (!uc) {
        const feed = taskBroker.controllerFeedStorage(room);
        if (feed && !storageCargoLocked(creep) && open(feed.target)) return feed.target;
    }
    target = creep.pos.findClosestByPath(FIND_MY_STRUCTURES, { filter: towerFilter });
    if (target) return target;
    const st = room.storage;
    if (st && st.my && !storageCargoLocked(creep) && freeIn(st) > 0 && !(exclude && exclude.has(st.id))) return st;
    return null;
}

/** 载货路过的 spawn/ext（相邻、有空位、没被别人预留）：本 tick 顺手 transfer，不停步。主目标是紧急任务（塔 / 控制器见底）时不分货 */
function driveByTarget(creep, room, main, mainTask, exclude) {
    if (mainTask && mainTask.weight >= 11) return null;
    const found = creep.pos.findInRange(FIND_MY_STRUCTURES, 1, {
        filter: (s) => (s.structureType === STRUCTURE_SPAWN || s.structureType === STRUCTURE_EXTENSION) && freeIn(s) > 0,
    }) || [];
    for (const structure of found) {
        if (!structure || structure.id === (main && main.id) || distance(creep, structure) > 1) continue;
        if (exclude && exclude.has(structure.id)) continue;
        if (openTarget(creep, room, structure)) return structure;
    }
    return null;
}

// ---- 取货目标 ----

/** 值得专程跑一趟的最少取货量：急的时候 50；否则随路程涨（每格 pickupPerTile），封顶空位的 pickupShare，至少 pickupMin。
 *  以前是固定 100：1500 容量的 hauler 跑 25 格去拿 150（到达时约 400），一趟只运 25%（基准容器房在途装载率 0.34–0.6） */
function pickupBar(creep, target, free, urgent) {
    if (urgent) return Math.min(free, 50);
    const settings = hauling();
    const minimum = Number(settings.pickupMin) || 100;
    const share = Number(settings.pickupShare) || 0.5;
    const perTile = Number(settings.pickupPerTile) || 25;
    const travel = Math.max(0, distance(creep, target) - 1);
    return Math.min(free, Math.max(minimum, Math.min(free * share, minimum + perTile * travel)));
}

/** hub 模式只为真实消费者从 storage 取（不做 storage → storage） */
function hubNeedsEnergy(room, ctx) {
    return !ctx.hubFed || consumerTasks(room).length > 0;
}

function collectFilter(creep, room, ctx, free, exclude, allowStorage, loaded) {
    const urgent = isUrgent(room, ctx);
    const hubNeeds = hubNeedsEnergy(room, ctx);
    const plan = ctx.plan;
    return (candidate) => {
        if (candidate.kind !== 'collect' || !candidate.target) return false;
        const target = candidate.target;
        if (exclude && exclude.has(target.id)) return false;
        const available = taskBroker.availableFor(candidate, creep);
        if (candidate.tombstone) {
            // tombstone / ruin：近处的 50 就值得顺手拿（几十 tick 后散成掉落物），远处按普通门槛
            const bar = distance(creep, target) <= 5 ? Math.min(free, 50) : pickupBar(creep, target, free, urgent);
            return available >= bar;
        }
        if (available < pickupBar(creep, target, free, urgent)) return false;
        if (target.amount != null) return target.resourceType === RESOURCE_ENERGY;   // 掉落（只收能量：矿物捡了卸不掉）
        // storage 只在 broker 标了 rich（storage 富余且控制器容器/link 不满）或 hub 模式时才是取货来源，否则搬出来又搬回去；
        // 容器供能房里只是兜底（权重 6）：先竞价源容器/掉落/tombstone，都没得取再取 storage——storage 压过源容器会把 hauler 抽走、
        // 矿工溢出到地上衰减（2026-09-06 A/B 总 CP −5%）；link 供能房 storage 权重 8，第一轮就放行（有源在溢出时 broker 降回 6）
        // 身上已有货（补满 / 送完零头）的不去 storage 补：storage 取货只为没人认领的消费者缺口，这只 hauler 没挑到投递才来补，
        // 补上的货还会把整车锁成 storage 货；在源容器补满的会被 storage 拉走、揣着源头的货来回跑（审查 perf-2）
        if (target.structureType === STRUCTURE_STORAGE) {
            if (loaded) { noteCounter(room, 'haulLoadedStorageSkip'); return false; }
            return hubNeeds && (candidate.rich || candidate.hub) && (allowStorage || candidate.weight >= 8 || candidate.hub) &&
                storageWithdrawBudget(creep, room, ctx, free) >= Math.min(50, free);
        }
        // terminal：只有 broker 标了 terminalDrain（storage 不富余时取终端网络送来的能量）才是取货来源
        if (target.structureType === STRUCTURE_TERMINAL) return !!candidate.terminalDrain;
        return target.structureType === STRUCTURE_CONTAINER && srcIsPlanned(room, target) &&
            !links.skipSourceContainer(room, plan, target);
    };
}

/** 返回 { target, task }；第一轮不放行 storage 兜底，第二轮放行；loaded = 身上已有货（不从 storage 补） */
function pickCollect(creep, room, ctx, free, exclude, loaded) {
    try {
        const task = taskBroker.pickTask(creep, room, collectFilter(creep, room, ctx, free, exclude, false, loaded), true) ||
            taskBroker.pickTask(creep, room, collectFilter(creep, room, ctx, free, exclude, true, loaded), true);
        return task && task.target ? { target: task.target, task } : null;
    } catch (error) {
        logErr('hauler.auctionSource ' + creep.name, error);
        const target = fallbackCollect(creep, room, ctx);
        return target ? { target, task: null } : null;
    }
}

/** 竞价不可用时的兜底顺序与 broker 一致：hub storage → 源容器 → 掉落 → storage（富余）→ tombstone */
function fallbackCollect(creep, room, ctx) {
    const plan = ctx.plan;
    const hubNeeds = hubNeedsEnergy(room, ctx);
    const st = room.storage;
    if (ctx.hubFed && hubNeeds && st && st.my && energyIn(st.store) >= 50) return st;
    const container = creep.pos.findClosestByPath(FIND_STRUCTURES, {
        filter: (s) => s.structureType === STRUCTURE_CONTAINER && energyIn(s.store) >= 100 &&
            plan && srcIsPlanned(room, s) && !links.skipSourceContainer(room, plan, s),
    });
    if (container) return container;
    const drop = creep.pos.findClosestByPath(FIND_DROPPED_RESOURCES, {
        filter: (r) => r.resourceType === RESOURCE_ENERGY && r.amount >= 80 && !links.skipLinkedDrop(room, plan, r),
    });
    if (drop) return drop;
    if (st && st.my && hubNeeds && (ctx.hubFed || storageRichState(room, Memory.rooms[room.name], config.upgrading || {}))) return st;
    return creep.pos.findClosestByPath(FIND_TOMBSTONES, { filter: (t) => energyIn(t.store) >= 50 }) ||
        (typeof FIND_RUINS !== 'undefined' ? creep.pos.findClosestByPath(FIND_RUINS, { filter: (t) => energyIn(t.store) >= 50 }) : null);
}

/** 从 storage 取多少：只取还没人认领的消费者缺口，同 tick 各 hauler 共用一份预算——以前富余房按满载取，ctrl link 只缺 800 却两只
 *  850 容量的 hauler 各取一车，多出来的又回 storage（线上 W33S3）；hub 房同样（塔只缺 300 却取 800，揣满 100 tick 再退回 500）。
 *  非 hub 房只动升级者底线（upgrading.reserve）以上的部分；hub 房 storage 是 spawn/ext 唯一的来源，不留底线 */
function storageWithdrawBudget(creep, room, ctx, free) {
    if (!room.storage || !room.storage.my) return 0;
    if (consumerReserveBudget.tick !== Game.time) { consumerReserveBudget.tick = Game.time; consumerReserveBudget.rooms = {}; }
    const reserved = consumerReserveBudget.rooms[room.name] || 0;
    const reserve = ctx.hubFed ? 0 : Math.max(0, Number((config.upgrading || {}).reserve) || 0);
    const available = Math.max(0, energyIn(room.storage.store) - reserve - reserved);
    const unreserved = Math.max(0, consumerDemand(room, ctx) - reserved);
    return Math.min(available, unreserved, free);
}

/** 没有值得跑的取货时去哪等：有进账（矿工在采、link 不收）且还没被别人等着的源容器（取空了也算）。
 *  评分 = 存量 + 进账 × max(路程, WAIT_HORIZON) − 别人的预留：只按"到达时"算的话，站在容器旁的那个（路程 0）永远比远处的
 *  （进账 × 路程）低，hauler 在两个等候点之间来回跑；已经在某个等候点补满的就留在那里（只要它还有进账） */
const WAIT_HORIZON = 30;
function waitTarget(creep, room, ctx, exclude) {
    let best = null;
    let bestAmount = 0;
    const spots = taskBroker.waitSpots(room).filter((task) => task.target && !(exclude && exclude.has(task.target.id)) &&
        srcIsPlanned(room, task.target) && !links.skipSourceContainer(room, ctx.plan, task.target));
    const sticky = creep.memory.fill && spots.find((task) => task.target.id === creep.memory.fill);
    if (sticky && taskBroker.availableFor(sticky, creep) + sticky.inflow * WAIT_HORIZON > 0) return sticky;
    for (const task of spots) {
        const travel = Math.max(0, distance(creep, task.target) - 1);
        const score = taskBroker.availableFor(task, creep) + task.inflow * Math.max(0, WAIT_HORIZON - travel);
        if (score > bestAmount) { best = task; bestAmount = score; }
    }
    return best;
}

// ---- 执行 ----

/** 每 tick 的计划：每类动作最多一次、移动最多一次；exclude 是本 tick 已经服务过的目标；fillKept = 这一 tick 还在补满容器上 */
function newPlan() {
    return { move: null, moveRange: 1, pickup: false, withdraw: false, transfer: false, gained: 0, exclude: new Set(), fillKept: false };
}

function roundTripEstimate(creep, room) {
    const anchor = room.storage || room.find(FIND_MY_SPAWNS)[0];
    return anchor ? 2 * distance(creep, anchor) + 10 : 40;
}

/** 顺手：相邻的能量掉落（pickup）；投递模式下还顺手 withdraw 相邻 tombstone/ruin（withdraw 这一 tick 没别的用处）。都不占这一 tick */
function opportunistic(creep, room, plan, free, delivering) {
    if (free <= 0) return;
    const drops = creep.pos.findInRange(FIND_DROPPED_RESOURCES, 1, { filter: (r) => r.resourceType === RESOURCE_ENERGY && r.amount > 0 }) || [];
    let drop = null;
    for (const item of drops) if (distance(creep, item) <= 1 && (!drop || item.amount > drop.amount)) drop = item;
    // 数量要在调用前取：真引擎里 store/amount 下一 tick 才变，mock 是立即变。
    // 引擎按 transfer → withdraw → pickup 的顺序结算：同 tick 再 withdraw 会先占掉空位，所以后面的 withdraw 只取 pickup 之后剩下的空位
    const dropAmount = drop ? Number(drop.amount) || 0 : 0;
    if (drop && creep.pickup(drop) === OK) {
        const got = Math.min(free, dropAmount);
        plan.pickup = true;
        plan.gained += got;
        plan.exclude.add(drop.id);
        taskBroker.consume(creep, room, drop, got, 'collect');
    }
    const left = free - plan.gained;
    if (!delivering || left < 10) return;
    const kinds = [FIND_TOMBSTONES];
    if (typeof FIND_RUINS !== 'undefined') kinds.push(FIND_RUINS);
    for (const kind of kinds) {
        const found = creep.pos.findInRange(kind, 1, { filter: (t) => t.store && energyIn(t.store) > 0 }) || [];
        const tomb = found.find((t) => distance(creep, t) <= 1);
        const have = tomb ? energyIn(tomb.store) : 0;
        if (tomb && creep.withdraw(tomb, RESOURCE_ENERGY, Math.min(left, have)) === OK) {
            const got = Math.min(left, have);
            plan.withdraw = true;
            plan.gained += got;
            plan.exclude.add(tomb.id);
            taskBroker.consume(creep, room, tomb, got, 'collect');
            return;
        }
    }
}

/** 投递成功后的下一站：还有货就下一个投递目标（排除刚服务的），空了就下一个取货点；都没有就原地等下一 tick 重新评估 */
function planAfterDelivery(creep, room, ctx, plan, left, capacity) {
    if (left > 0) {
        const next = pickDeliver(creep, room, plan.exclude);
        if (next) { if (!near(creep, next.target)) plan.move = next.target; return; }
        releaseStorageResidual(creep, left, capacity);
        if (storageCargoLocked(creep) || capacity - left < capacity * (Number(hauling().topUpShare) || 0.25)) return;
    }
    const free = capacity - left;
    const source = pickCollect(creep, room, ctx, free, plan.exclude, left > 0);
    if (source) { if (!near(creep, source.target)) plan.move = source.target; return; }
    if (left > 0) return;
    const wait = waitTarget(creep, room, ctx, plan.exclude);
    if (wait && !near(creep, wait.target)) plan.move = wait.target;
}

function deliver(creep, room, ctx, plan, energy, capacity) {
    const load = energy + plan.gained;
    const choice = pickDeliver(creep, room, plan.exclude);
    if (!choice) {
        // 没有投递目标：零头不揣着发呆，先去补满（storage 的货不行，那是给消费者的；只剩零头的 storage 货解锁后可以）
        releaseStorageResidual(creep, load, capacity);
        if (!storageCargoLocked(creep) && capacity - load >= capacity * (Number(hauling().topUpShare) || 0.25) &&
            collect(creep, room, ctx, plan, load, capacity)) return;
        haulStats.note(creep, 'full');
        park(creep, room, plan);
        return;
    }
    const target = choice.target;
    if (near(creep, target)) {
        const sent = Math.min(energy, freeIn(target));   // 调用前取（真引擎 store 下一 tick 才变，mock 是立即变）；显式数量与引擎默认值相同
        if (sent > 0 && creep.transfer(target, RESOURCE_ENERGY, sent) === OK) {
            plan.transfer = true;
            taskBroker.consume(creep, room, target, sent, 'deliver');
            plan.exclude.add(target.id);
            const left = Math.max(0, load - sent);
            taskBroker.setProjected(creep, left);
            planAfterDelivery(creep, room, ctx, plan, left, capacity);
        }
        return;
    }
    // 在路上：顺手灌路过的 spawn/ext，灌完就空的话直接转去取货
    const drive = driveByTarget(creep, room, target, choice.task, plan.exclude);
    if (drive) {
        const sent = Math.min(energy, freeIn(drive));
        if (sent > 0 && creep.transfer(drive, RESOURCE_ENERGY, sent) === OK) {
            plan.transfer = true;
            taskBroker.consume(creep, room, drive, sent, 'deliver');
            plan.exclude.add(drive.id);
            const left = Math.max(0, load - sent);
            taskBroker.setProjected(creep, left);
            if (left <= 0) { planAfterDelivery(creep, room, ctx, plan, 0, capacity); return; }
        }
    }
    plan.move = target;
}

/** 取货后走不走：装到 leaveShare 就走；急用就走；源没有进账（掉落 / tombstone / storage）就走；
 *  否则比较"等进账"与"现在走"的效率——进账 × 往返 > 现有载货时等更划算（等 w tick 多拿 inflow×w，吞吐 (L+iw)/(T+w) > L/T ⇔ iT > L） */
function shouldLeave(creep, room, ctx, load, capacity, task) {
    if (load >= capacity * (Number(hauling().leaveShare) || 0.9)) return true;
    if (isUrgent(room, ctx)) return true;
    const inflow = task && task.inflow > 0 ? task.inflow : 0;
    if (!inflow) return true;
    return inflow * roundTripEstimate(creep, room) <= load;
}

/** 取货（空载，或补满零头）。返回是否有事可做 */
function collect(creep, room, ctx, plan, carried, capacity) {
    const free = Math.max(0, capacity - carried);
    if (free <= 0) return false;
    const pick = pickCollect(creep, room, ctx, free, plan.exclude, carried > 0);
    if (pick) {
        const target = pick.target;
        if (target.id === creep.memory.fill) plan.fillKept = true;
        if (!near(creep, target)) { plan.move = target; return true; }
        const got = takeFrom(creep, room, ctx, plan, target, free, pick.task);
        if (got > 0) leaveOrFill(creep, room, ctx, plan, target, pick.task, carried + got, capacity);
        return true;
    }
    if (carried <= 0 && consumerFallback(creep, room, ctx, plan, free)) return true;
    // 没有值得跑的：去有进账的源容器旁边等（租下它，别的 hauler 就不会也来等；源旁装满再走），而不是回 spawn 发呆
    const wait = waitTarget(creep, room, ctx, plan.exclude);
    if (!wait) return false;
    // 补满中的那口源停了进账（源采空等再生 / 源 link 开始收货）：带着货去送，不揣着货换到另一个等候点再等（审查 F1 两格来回跳）
    if (carried > 0 && creep.memory.fill && wait.target.id !== creep.memory.fill) {
        dropFill(creep, room);
        return false;
    }
    haulStats.note(creep, 'wait');
    taskBroker.leaseSpot(creep, wait);
    if (wait.target.id === creep.memory.fill) plan.fillKept = true;
    if (!near(creep, wait.target)) { plan.move = wait.target; return true; }
    if (creep.memory.fill !== wait.target.id) noteFill(room, 'start', carried / Math.max(1, capacity));
    creep.memory.fill = wait.target.id;
    plan.fillKept = true;
    // 攒够一口（FILL_CHUNK 或能装满）才取：每 tick 取 10 能量要多花一次动作的 CPU，能量留在容器里与在身上等价
    const stock = amountAt(wait.target);
    if (stock >= Math.min(free, FILL_CHUNK) && !plan.withdraw) {
        const got = takeFrom(creep, room, ctx, plan, wait.target, free, wait);
        if (got > 0) leaveOrFill(creep, room, ctx, plan, wait.target, wait, carried + got, capacity);
    }
    return true;
}
const FILL_CHUNK = 100;

/** 取到货以后：该走就挑投递目标同 tick 起步，否则记下补满目标，下一 tick 接着取 */
function leaveOrFill(creep, room, ctx, plan, target, task, load, capacity) {
    taskBroker.setProjected(creep, load);
    if (shouldLeave(creep, room, ctx, load, capacity, task)) {
        if (creep.memory.fill) noteFill(room, 'left', load / Math.max(1, capacity));
        delete creep.memory.fill;
        const next = pickDeliver(creep, room, plan.exclude);
        if (next && !near(creep, next.target)) plan.move = next.target;
        return;
    }
    if (creep.memory.fill !== target.id) noteFill(room, 'start', load / Math.max(1, capacity));
    creep.memory.fill = target.id;
    plan.fillKept = true;
    taskBroker.holdClaim(creep, target.id + ':collect');   // 留下来接着等：consume 刚释放的认领记回去
}

/** 遥测（私服生效断言 hauler.fillAtFedContainer）：进入补满的次数，与补满后离开时的平均装载率；drop = 没补满就放弃（进账停了、被别的目标拉走） */
function noteFill(room, kind, share) {
    const mem = Memory.rooms[room.name] || (Memory.rooms[room.name] = {});
    const rec = mem.haulFill || (mem.haulFill = { start: 0, left: 0, share: 0 });
    rec[kind] = (Number(rec[kind]) || 0) + 1;
    if (kind === 'left') rec.share = Math.round(((Number(rec.share) || 0) * (rec.left - 1) + share) / rec.left * 100) / 100;
    rec.at = Game.time;
}

/** 放弃补满：这一 tick 没有在补满容器取货 / 等候 / 往回走（进账停了、被别的取货 / 投递 / storage 兜底拉走）。
 *  以前 fill 一直留着，下一 tick 又把 hauler 拽回补满容器，在两格之间来回跳（审查 F1 / EC4） */
function dropFill(creep, room) {
    if (!creep.memory.fill) return;
    noteFill(room, 'drop');
    delete creep.memory.fill;
}

/** withdraw / pickup 一次，返回预计拿到的量（按 tick 开始时的数值算；同 tick 先跑的 creep 已扣掉的量按池子里的 backlog 算——
 *  withdraw 带显式数量，引擎在目标不够时整笔失败，不能按 tick 开始时的存量去要） */
function takeFrom(creep, room, ctx, plan, target, free, task) {
    const before = task && task.target && task.target.id === target.id ? Math.min(amountAt(target), Math.max(0, Number(task.backlog) || 0)) : amountAt(target);
    if (target.amount != null) {
        if (plan.pickup) return 0;
        if (creep.pickup(target) !== OK) return 0;
        plan.pickup = true;
        const got = Math.min(free, before);
        plan.exclude.add(target.id);
        taskBroker.consume(creep, room, target, got, 'collect');
        return got;
    }
    if (plan.withdraw) return 0;
    const isStorage = target.structureType === STRUCTURE_STORAGE;
    let amount = Math.min(free, before);
    if (isStorage) amount = Math.min(amount, storageWithdrawBudget(creep, room, ctx, free));
    if (amount <= 0 || (isStorage && amount < 50 && amount < free)) return 0;
    if (creep.withdraw(target, RESOURCE_ENERGY, amount) !== OK) return 0;
    plan.withdraw = true;
    plan.exclude.add(target.id);
    taskBroker.consume(creep, room, target, amount, 'collect');
    if (target.structureType === STRUCTURE_TERMINAL) {
        // 遥测（私服生效断言 hauler.terminalDrain）：从 terminal 取出终端网络送来的能量
        const mem = Memory.rooms[room.name] || (Memory.rooms[room.name] = {});
        const rec = mem.terminalDrain || (mem.terminalDrain = { n: 0, amount: 0 });
        rec.n = (Number(rec.n) || 0) + 1;
        rec.amount = (Number(rec.amount) || 0) + amount;
        rec.at = Game.time;
        // storage 富余但低于 terminalDrainStorageBelow 时取回的量（broker 给 terminal 留 feeReserve；生效断言 broker.terminalDrainLow）
        if (task && Number(task.drainKeep) > 0) rec.low = (Number(rec.low) || 0) + amount;
    }
    if (isStorage) {
        markStorageCargo(creep);
        consumerReserveBudget.rooms[room.name] = (consumerReserveBudget.rooms[room.name] || 0) + amount;
        if (ctx.hubFed) {
            // 遥测（私服生效断言 hauler.hubBudgetedWithdraw）：hub 房按缺口取的次数与取量
            const mem = Memory.rooms[room.name] || (Memory.rooms[room.name] = {});
            const rec = mem.hubBudgetedWithdraw || (mem.hubBudgetedWithdraw = { n: 0, amount: 0 });
            rec.n = (Number(rec.n) || 0) + 1;
            rec.amount = (Number(rec.amount) || 0) + amount;
            rec.at = Game.time;
        }
    }
    return amount;
}

/** 闲置储备只为实际消费者兜底；控制器 link 也可消费，不抢源侧物流或回库。 */
function consumerFallback(creep, room, ctx, plan, free) {
    if (ctx.hubFed || !room.storage || !room.storage.my || plan.withdraw) return false;
    const amount = storageWithdrawBudget(creep, room, ctx, free);
    if (amount < 50) return false;
    if (!near(creep, room.storage)) { plan.move = room.storage; return true; }
    const ret = creep.withdraw(room.storage, RESOURCE_ENERGY, amount);
    if (ret !== OK) return true;
    plan.withdraw = true;
    consumerReserveBudget.rooms[room.name] = (consumerReserveBudget.rooms[room.name] || 0) + amount;
    markStorageCargo(creep); // 已有投递保护：消费者消失也不能倒回 storage。
    const memory = Memory.rooms[room.name];
    memory.storageConsumerFallback = (memory.storageConsumerFallback || 0) + amount;
    taskBroker.consume(creep, room, room.storage, amount, 'collect');
    taskBroker.setProjected(creep, amount);
    const next = pickDeliver(creep, room, plan.exclude);
    if (next && !near(creep, next.target)) plan.move = next.target;
    return true;
}

/** 没活干 / 满载无处投：在 storage（没有就 spawn）3 格内等，已在范围内不动 */
function park(creep, room, plan) {
    const anchor = room.storage || room.find(FIND_MY_SPAWNS)[0];
    if (anchor && !creep.pos.inRangeTo(anchor, 3)) { plan.move = anchor; plan.moveRange = 3; }
}

// ---- 打捞：非能量资源（入侵者阵亡掉的 boost 化合物、ruin 里的矿物）----

/** store 里的非能量总量。真引擎的 Store 用 getUsedCapacity 的差值最稳（键的枚举语义不保证），
 *  没有这个方法时退回按键求和 */
function nonEnergyIn(store) {
    if (!store) return 0;
    if (typeof store.getUsedCapacity === 'function') {
        return Math.max(0, (Number(store.getUsedCapacity()) || 0) - (Number(store.getUsedCapacity(RESOURCE_ENERGY)) || 0));
    }
    let sum = 0;
    for (const key of Object.keys(store)) {
        if (key === RESOURCE_ENERGY || typeof store[key] !== 'number') continue;
        sum += Math.max(0, store[key]);
    }
    return sum;
}

function firstNonEnergyType(store) {
    if (!store) return null;
    for (const key of Object.keys(store)) {
        if (key === RESOURCE_ENERGY || typeof store[key] !== 'number' || store[key] <= 0) continue;
        return key;
    }
    return null;
}

/** 打捞的卸货口：terminal 优先（矿物的正经去处，还能挂市场单），其次 storage。都放不下就别去捡——捡了也只能扔 */
function salvageSink(room, type) {
    return [room.terminal, room.storage].find((s) => s && s.my && s.store &&
        typeof s.store.getFreeCapacity === 'function' &&
        Number(s.store.getFreeCapacity(type == null ? undefined : type)) > 0) || null;
}

/** 房里值得打捞的非能量资源，按格聚合成"堆"：tombstone 衰减后散成同一格的几堆掉落（线上 2026-09-12 W35S7 的入侵者
 *  tombstone 是 GO 95 / KO 17 / ZH 23 / UH 11 四堆挤在 (12,5)），分开算每堆都够不着门槛，合起来才值得跑一趟。
 *  三次 find 都走 findCached（本 tick 已经取过），聚合本身只在真有非能量资源时才有成本——绝大多数 tick 是三个空数组 */
function salvageTargets(room) {
    const piles = {};
    const add = (pos, amount, item) => {
        if (!pos || !(amount > 0)) return;
        const key = pos.x + ',' + pos.y;
        const pile = piles[key] || (piles[key] = { pos, amount: 0, items: [] });
        pile.amount += amount;
        pile.items.push(item);
    };
    for (const kind of [FIND_TOMBSTONES, typeof FIND_RUINS !== 'undefined' ? FIND_RUINS : null]) {
        if (kind == null) continue;
        for (const item of findCached(room, kind) || []) add(item.pos, nonEnergyIn(item.store), item);
    }
    for (const drop of findCached(room, FIND_DROPPED_RESOURCES) || []) {
        if (!drop.resourceType || drop.resourceType === RESOURCE_ENERGY) continue;
        add(drop.pos, Number(drop.amount) || 0, drop);
    }
    return Object.keys(piles).map((key) => piles[key]);
}

/** 别的 hauler 已经认领的格子：一堆只派一只，第二只跑到时东西已经在别人身上了 */
function salvageClaimed(room, self) {
    const claimed = new Set();
    for (const other of findCached(room, FIND_MY_CREEPS) || []) {
        const claim = other && other.memory && other.memory.salvage;
        if (!claim || (self && other.name === self.name)) continue;
        claimed.add(claim.x + ',' + claim.y);
    }
    return claimed;
}

/** 配置项取数：不能用 `Number(x) || 默认`——那会把合法的 0 吞掉（minAmount: 0 = 什么都捡、timeout: 0 = 每 tick 重挑） */
function salvageNum(value, fallback) {
    const num = Number(value);
    return Number.isFinite(num) ? num : fallback;
}

/** 挑一堆去捡：门槛随路程涨（minAmount + perTile × 路程），近处密集的优先（量 ÷ 路程） */
function pickSalvage(creep, room, targets) {
    const settings = config.salvage || {};
    const minAmount = salvageNum(settings.minAmount, 30);
    const perTile = salvageNum(settings.perTile, 0);
    const maxRange = salvageNum(settings.maxRange, 40);
    const claimed = salvageClaimed(room, creep);
    let best = null;
    let bestScore = 0;
    for (const pile of targets) {
        if (claimed.has(pile.pos.x + ',' + pile.pos.y)) continue;
        const travel = distance(creep, pile);
        if (travel > maxRange || pile.amount < minAmount + perTile * travel) continue;
        const score = pile.amount / (travel + 1);
        if (score > bestScore) { best = pile; bestScore = score; }
    }
    return best;
}

/** 主动打捞：掉落每 tick 衰减 ceil(amount/1000)、tombstone 按身体部件数 × 5 tick 就散成掉落，没人专程去捡就全丢光
 *  （线上 2026-09-12 W35S7：入侵者掉的 146 单位 T1 化合物在 250 tick 的 tombstone 寿命里没有任何 creep 认领）。
 *  认领按格记在 creep.memory.salvage，卸货走已有的 salvageCargo。返回 true = 这一 tick 就干这个 */
function salvagePickup(creep, room) {
    const settings = config.salvage || {};
    const abandon = () => { delete creep.memory.salvage; return false; };
    if (settings.enabled === false) return abandon();
    const targets = salvageTargets(room);
    if (!targets.length) return abandon();                  // 绝大多数 tick 走到这里就结束
    if (!salvageSink(room)) return abandon();               // terminal / storage 都放不下：捡了只能扔（salvageCargo 的兜底）
    const store = creep.store;
    if (!store || typeof store.getFreeCapacity !== 'function') return abandon();
    let free = Number(store.getFreeCapacity()) || 0;
    if (free <= 0) return false;                            // 装满了：留着认领，先交给 salvageCargo 去卸
    const claim = creep.memory.salvage;
    const stale = claim && Game.time - (Number(claim.at) || 0) > salvageNum(settings.timeout, 200);
    let pos = claim && claim.room === room.name && !stale ? claim : null;
    if (claim && !pos) delete creep.memory.salvage;         // 认领过期 / 换了房：放掉，这一 tick 还能重新挑
    const empty = !(Number(store.getUsedCapacity()) > 0);
    if (!pos) {
        // 只有完全空载的 hauler 才接新单：揣着能量的正在送货，别为几十单位矿物把整车锁在打捞上
        if (!empty) return false;
        const pile = pickSalvage(creep, room, targets);
        // spawn 在等能量 / spawn·ext 见底：先顾经济。必须在写 claim 之前判——否则"接单 → dropFill → 又放手"
        // 每 tick 空转一次，把源容器旁的补满粘性也一起清掉（isUrgent 不便宜，所以放在确实挑到了堆之后）
        if (!pile || isUrgent(room, contextFor(room))) return false;
        creep.memory.salvage = { x: pile.pos.x, y: pile.pos.y, room: room.name, at: Game.time };
        // 明确退出补满模式：遥测要记下这次放弃（否则 haulFill 的 start 永远等不到 left/drop），
        // 等候点的粘性也不该跨过这趟打捞——回来时那口源可能早就没进账了
        dropFill(creep, room);
        leaveBroker(creep);
        pos = creep.memory.salvage;
    } else if (empty && isUrgent(room, contextFor(room))) {
        return abandon();   // 半路上房间变急：空车放手回去运能量（装了货的把这趟跑完，半途而废等于白走）
    }
    const key = pos.x + ',' + pos.y;
    const pile = targets.find((item) => item.pos.x + ',' + item.pos.y === key);
    if (!pile) return abandon();                            // 这一堆捡光了 / 衰减光了 / 被别人收走（房里别的堆下一 tick 再挑）
    if (distance(creep, pile) > 1) { movement.go(creep, pile.items[0], { range: 1, reusePath: 20 }); return true; }
    // 到了。引擎按 transfer → withdraw → pickup 结算，withdraw 先占空位：先显式限量 withdraw，剩下的空位再 pickup，
    // 两条管线同 tick 各一次，四堆资源不用四趟
    let took = 0;
    const container = pile.items.find((item) => item.store && nonEnergyIn(item.store) > 0);
    const type = container ? firstNonEnergyType(container.store) : null;
    if (type) {
        const amount = Math.min(free, Number(container.store[type]) || 0);
        if (amount > 0 && creep.withdraw(container, type, amount) === OK) { took += amount; free -= amount; }
    }
    if (free > 0) {
        const loose = pile.items.find((item) => item.amount != null && item.resourceType !== RESOURCE_ENERGY && Number(item.amount) > 0);
        if (loose && creep.pickup(loose) === OK) took += Math.min(free, Number(loose.amount) || 0);
    }
    if (took > 0) noteSalvage(room, took);
    return true;
}

/** 退出 broker：打捞走独立路径，从 run() 最前面就 return，一路不碰 broker。残留的租约会被卡住检测当成"目标不可达"
 *  ——它按"位置和**能量**都没变"判定（task_broker.js energyOf 只看能量，打捞搬的是矿物；站在堆上取货也不移动），
 *  6 tick 就把租约那个目标屏蔽 150 tick，而且是对全房 hauler 生效。同一格 ≥6 种资源（被拆的 lab/factory 的 ruin）
 *  或路上被挡 6 tick 就会踩到。releaseClaim 连本 tick 的认领一起放掉，别人立刻看得到这个缺口没人管了 */
function leaveBroker(creep) {
    const lease = creep.memory && creep.memory.brokerTask;
    if (!lease) return;
    if (lease.id) taskBroker.releaseClaim(lease.id, creep);
    delete creep.memory.brokerTask;
}

/** 遥测（私服生效断言 hauler.salvagePickup）：主动打捞的次数与总量 */
function noteSalvage(room, amount) {
    const mem = Memory.rooms[room.name] || (Memory.rooms[room.name] = {});
    const rec = mem.salvaged || (mem.salvaged = { n: 0, amount: 0 });
    rec.n = (Number(rec.n) || 0) + 1;
    rec.amount = (Number(rec.amount) || 0) + amount;
    rec.at = Game.time;
}

/** 身上有非能量货（打捞回来的、别的途径塞进来的）：先卸进 terminal / storage，都放不下就扔掉——否则它永远占着容量，
 *  装满了的 hauler 一辈子停在 storage 边，编制里却还算一只（审查 EC6）。返回 true = 这一 tick 就干这个 */
function salvageCargo(creep, room) {
    const store = creep.store;
    if (!store || typeof store.getUsedCapacity !== 'function') return false;
    if (!(Number(store.getUsedCapacity()) > energyIn(store))) return false;
    const type = Object.keys(store).find((key) => key !== RESOURCE_ENERGY && Number(store[key]) > 0);
    if (!type) return false;
    const sink = salvageSink(room, type);
    if (!sink) { creep.drop(type); noteCounter(room, 'haulSalvage'); return false; }
    // 与 salvagePickup 同样的理由：这条路径也从 run() 早早 return、一路不碰 broker，而且每 tick 只 transfer 一种资源、
    // 站在 sink 旁不动、energyOf 不变——六种以上的货就会踩到卡住检测，把租约目标屏蔽 150 tick
    leaveBroker(creep);
    if (near(creep, sink)) { creep.transfer(sink, type); noteCounter(room, 'haulSalvage'); }
    else movement.go(creep, sink, { range: 1, reusePath: 20 });
    return true;
}

function run(creep) {
    const room = Game.rooms[creep.memory.home];
    if (!room) { movement.go(creep, new RoomPosition(25, 25, creep.memory.home), { reusePath: 20 }); return; }
    // 打捞先于卸货：到了堆上要把同一格的几种资源都收完再走，否则捡起第一种就被 salvageCargo 拽去 storage，来回跑四趟
    if (salvagePickup(creep, room)) return;
    if (salvageCargo(creep, room)) return;
    const energy = energyIn(creep.store);
    const free = freeIn(creep);
    const capacity = energy + free;
    if (!energy) { delete creep.memory.hubCargo; delete creep.memory.hubCargoAt; }
    const ctx = contextFor(room);
    const plan = newPlan();
    let fill = creep.memory.fill ? Game.getObjectById(creep.memory.fill) : null;
    if (creep.memory.fill && (!fill || (fill.pos && fill.pos.roomName !== room.name))) { delete creep.memory.fill; fill = null; }
    // 补满模式（在源容器旁等进账）：没急事、没装到 leaveShare 就继续取；否则投递
    let collecting = energy <= 0;
    if (!collecting && fill && !isUrgent(room, ctx) && energy < capacity * (Number(hauling().leaveShare) || 0.9)) collecting = true;
    if (!collecting && creep.memory.fill) {
        noteFill(room, 'left', energy / Math.max(1, capacity));   // 装到 leaveShare 或急用：带着补到的货走
        delete creep.memory.fill;
    }
    try {
        opportunistic(creep, room, plan, free, !collecting);
        if (collecting) {
            if (!collect(creep, room, ctx, plan, energy + plan.gained, capacity)) {
                if (energy + plan.gained > 0) deliver(creep, room, ctx, plan, energy, capacity);
                else { haulStats.note(creep, 'park'); park(creep, room, plan); }
            }
        } else {
            deliver(creep, room, ctx, plan, energy, capacity);
        }
    } finally {
        if (creep.memory.fill && !plan.fillKept) dropFill(creep, room);
        if (plan.move) movement.go(creep, plan.move, { range: plan.moveRange, reusePath: 20 });
    }
}

/** 该容器是否为本房间规划中的源容器（避免把 controller 容器当源容器来回倒）。
 *  方案的控制器容器即使贴着源（源与控制器挨着的地形）也是消费者，不能按"源旁 1 格"的兜底认成源容器：
 *  否则 consumerTasks/deliverFilter 把它滤掉、storage 兜底取货的预算为 0，hauler 一直 park，升级者一点能量都拿不到；
 *  collect/waitTarget 反而把它当取货点从升级者那里往回搬（validation-52vHk6 W41N40：控制器容器 (42,31) 贴着源 (43,30)） */
function srcIsPlanned(room, s) {
    const plan = (Memory.rooms[room.name] || {}).plan;
    const containers = plan && plan.containers;
    if (containers) {
        for (const key of ['src0', 'src1']) {
            const c = containers[key];
            if (c && c.x === s.pos.x && c.y === s.pos.y) return true;
        }
        const ctrl = containers.ctrl;
        if (ctrl && ctrl.x === s.pos.x && ctrl.y === s.pos.y) return false;
    }
    const sources = findCached(room, FIND_SOURCES) || [];
    return sources.some((source) => Math.max(
        Math.abs(source.pos.x - s.pos.x),
        Math.abs(source.pos.y - s.pos.y),
    ) <= 1);
}

module.exports = { run, srcIsPlanned };

modules.roles_labTech:
'use strict';
/**
 * 实验室搬运工（labTech，移植 overmind-absorb 7f4ab27）：照 industry.labPlan 把矿物从 terminal/storage 装进 lab，
 * 再把产物（与装错的货）从 lab 收回 terminal。
 *
 * 这是矿物链上断掉的那一环：矿物躺在 terminal 里，industry 认得出 lab 分工，但没有人把矿物搬进 lab——labs 建好了也永远不反应。
 * 刻意不走 task_broker / hauler：那两处只搬能量、承载账号全部的能量收入；矿物是独立的低频货流（一次装 labFill、几百 tick 才动一次）。
 *
 * 没活干（没有取送计划 / 都装满了 / 库里没货）先在原地等 labTechIdleTicks，再退役回收：
 * 两批之间的空档很短，一有空就回收会为每一批重孵一只。
 * 遥测（私服生效断言 minerals.labChain）：Memory.rooms[母房].labTech {loaded, loadedAmount, drained, drainedAmount, at}
 */
const config = require('config');
const movement = require('movement');
const retireMod = require('retire');
const industry = require('industry');

/** 手里唯一的那种货（labTech 一次只搬一种） */
function carrying(creep) {
    const store = creep.store || {};
    for (const key of Object.keys(store)) {
        if (typeof store[key] === 'number' && store[key] > 0) return key;
    }
    return null;
}

/** 取货点：优先 terminal（矿物的正经去处），否则 storage */
function sourceFor(room, mineral) {
    for (const holder of [room.terminal, room.storage]) {
        if (holder && holder.my !== false && holder.store && Number(holder.store[mineral] || 0) > 0) return holder;
    }
