    if (container && creep.store.getFreeCapacity(RESOURCE_ENERGY) <= 0 && container.store.getFreeCapacity(RESOURCE_ENERGY) <= 0) return;
    remote.noteSkHarvest(creep, creep.harvest(source));   // SK 外矿的开采遥测（普通外矿直接返回）
}

module.exports = { run };

