    remoteHauler: 65,
    courier: 60,
    feeder: 62,
    operator: 90,
    reserver: 45,
    scout: 20,
};
const TASK_WEIGHT = {
    deliver: 8,
    harvest: 7,
    build: 5,
    repair: 4,
    upgrade: 3,
};
const TASK_VALUE = {
    deliver: 1,
    collect: 1,
    harvest: 1.1,
    build: 1.35,
    repair: 0.75,
    upgrade: 0.65,
};
const ACTION_RANGE = {
    deliver: 1,
    collect: 1,
    harvest: 1,
    build: 3,
    repair: 3,
    upgrade: 3,
};
const REPLAN_INTERVAL = 3;
const LEASE_TICKS = 5;
// 卡住检测：持有租约却连续 STUCK_TICKS tick 位置与能量都没变化，视为目标不可达/无效，屏蔽该任务 BLOCK_TICKS
const STUCK_TICKS = 6;
const BLOCK_TICKS = 150;
// 投递分层：spawn/ext 孵化 > tower 大缺口 > controller 供能容器 > storage。hauler 逐层竞价，高层有任务时低层让位
const DELIVER_TIERS = [1, 2, 3, 4];
const runtimeGlobal = typeof global !== 'undefined' ? global : {};
const runtime = runtimeGlobal.__taskBrokerRuntime || (runtimeGlobal.__taskBrokerRuntime = {
