/** 溢出取货最多几只 hauler 同时认领：房里 ≥ 3 只 hauler 放 2 只，否则 1 只 */
function spillSlots(creeps) {
    const haulers = (creeps || []).filter((creep) => creep.memory && creep.memory.role === 'hauler' && !creep.spawning).length;
