const ROLE_CHARACTERS = {
    harvester: '穣子',      // 秋穣子 · 丰收之神，管产出
    hauler: '荷取',         // 河城荷取 · 名字直译就是"搬运"
    upgrader: '慧音',       // 上白泽慧音 · 教书育人，养 controller
    builder: '霖之助',      // 森近霖之助 · 香霖堂店主，造与修
