        if (drop.resourceType === RESOURCE_ENERGY) dropped += Number(drop.amount) || 0;
    }
    return dropped >= settings.dropped;
}


/** 平地上每走一格要几 tick：非 MOVE 部件每个产生 2 疲劳，每个 MOVE 每 tick 消 2；ceil(非 MOVE / MOVE)，没有 MOVE 视为无穷。
