    return costMat;
}
function roomCallbackWithRoute(roomName) {
    if (roomName in route) {
        const roomCache = costMatrixCache[roomName];
        costMat = roomCache ? roomCache[findPathIgnoreCondition] : emptyCostMatrix;
        //console.log('in route ' + roomName);
